package main

import (
	"container/heap"
	"math"
)

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

type Edge struct {
	to      int
	minutes int
	energy  int
}

type Item struct {
	minutes int
	swaps   int
	u       int
	charge  int
}

type PriorityQueue []Item

func (pq PriorityQueue) Len() int { return len(pq) }

func (pq PriorityQueue) Less(i, j int) bool {
	if pq[i].minutes != pq[j].minutes {
		return pq[i].minutes < pq[j].minutes
	}
	return pq[i].swaps < pq[j].swaps
}

func (pq PriorityQueue) Swap(i, j int) {
	pq[i], pq[j] = pq[j], pq[i]
}

func (pq *PriorityQueue) Push(x interface{}) {
	*pq = append(*pq, x.(Item))
}

func (pq *PriorityQueue) Pop() interface{} {
	old := *pq
	n := len(old)
	item := old[n-1]
	*pq = old[0 : n-1]
	return item
}

func FastestDelivery(n int, roads []Tuple1, stations []int, capacity int, swap_time int, max_swaps int, s int, t int) *Tuple2 {
	if s == t {
		return &Tuple2{F0: 0, F1: 0}
	}

	adj := make([][]Edge, n)
	for _, r := range roads {
		u, v, m, e := r.F0, r.F1, r.F2, r.F3
		adj[u] = append(adj[u], Edge{to: v, minutes: m, energy: e})
	}

	hasStation := make([]bool, n)
	for _, st := range stations {
		if st >= 0 && st < n {
			hasStation[st] = true
		}
	}

	cSize := capacity + 1
	sSize := max_swaps + 1
	totalStates := n * cSize * sSize

	dist := make([]int, totalStates)
	for i := range dist {
		dist[i] = math.MaxInt64
	}

	stateIdx := func(u, c, k int) int {
		return (u*cSize+c)*sSize + k
	}

	pq := make(PriorityQueue, 0)
	heap.Init(&pq)

	startIdx := stateIdx(s, capacity, 0)
	dist[startIdx] = 0
	heap.Push(&pq, Item{minutes: 0, swaps: 0, u: s, charge: capacity})

	for pq.Len() > 0 {
		curr := heap.Pop(&pq).(Item)

		if curr.u == t {
			return &Tuple2{F0: curr.minutes, F1: curr.swaps}
		}

		idx := stateIdx(curr.u, curr.charge, curr.swaps)
		if curr.minutes > dist[idx] {
			continue
		}

		// Option 1: Swap battery if at a station and under swap limit
		if hasStation[curr.u] && curr.swaps < max_swaps {
			nextSwaps := curr.swaps + 1
			nextCharge := capacity
			nextMinutes := curr.minutes + swap_time
			nextIdx := stateIdx(curr.u, nextCharge, nextSwaps)
			if nextMinutes < dist[nextIdx] {
				dist[nextIdx] = nextMinutes
				heap.Push(&pq, Item{
					minutes: nextMinutes,
					swaps:   nextSwaps,
					u:       curr.u,
					charge:  nextCharge,
				})
			}
		}

		// Option 2: Drive along outgoing roads
		for _, edge := range adj[curr.u] {
			if edge.energy > 0 && curr.charge < edge.energy {
				continue
			}
			nextCharge := curr.charge - edge.energy
			if nextCharge > capacity {
				nextCharge = capacity
			}
			nextMinutes := curr.minutes + edge.minutes
			nextIdx := stateIdx(edge.to, nextCharge, curr.swaps)
			if nextMinutes < dist[nextIdx] {
				dist[nextIdx] = nextMinutes
				heap.Push(&pq, Item{
					minutes: nextMinutes,
					swaps:   curr.swaps,
					u:       edge.to,
					charge:  nextCharge,
				})
			}
		}
	}

	return nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3) {}

    public record Tuple2(long f0, long f1) {}

    private record Edge(int to, long minutes, int energy) {}

    private record State(long minutes, int swaps, int u, int charge) implements Comparable<State> {
        @Override
        public int compareTo(State other) {
            int cmp = Long.compare(this.minutes, other.minutes);
            if (cmp != 0) return cmp;
            return Integer.compare(this.swaps, other.swaps);
        }
    }

    public static Tuple2 fastestDelivery(long n, List<Tuple1> roads, List<Long> stations, long capacity, long swap_time, long max_swaps, long s, long t) {
        if (s == t) {
            return new Tuple2(0L, 0L);
        }

        int numNodes = (int) n;
        int cap = (int) capacity;
        int maxSwaps = (int) max_swaps;
        int start = (int) s;
        int target = (int) t;

        List<List<Edge>> adj = new ArrayList<>(numNodes);
        for (int i = 0; i < numNodes; i++) {
            adj.add(new ArrayList<>());
        }
        for (Tuple1 r : roads) {
            adj.get((int) r.f0()).add(new Edge((int) r.f1(), r.f2(), (int) r.f3()));
        }

        boolean[] isStation = new boolean[numNodes];
        for (long st : stations) {
            isStation[(int) st] = true;
        }

        // State space: u in [0, n-1], charge in [0, capacity], swaps in [0, max_swaps]
        long[][][] bestMinutes = new long[numNodes][cap + 1][maxSwaps + 1];
        for (int i = 0; i < numNodes; i++) {
            for (int c = 0; c <= cap; c++) {
                Arrays.fill(bestMinutes[i][c], Long.MAX_VALUE);
            }
        }

        PriorityQueue<State> pq = new PriorityQueue<>();
        bestMinutes[start][cap][0] = 0L;
        pq.add(new State(0L, 0, start, cap));

        while (!pq.isEmpty()) {
            State curr = pq.poll();

            if (curr.u == target) {
                return new Tuple2(curr.minutes, (long) curr.swaps);
            }

            if (curr.minutes > bestMinutes[curr.u][curr.charge][curr.swaps]) {
                continue;
            }

            // Pruning: if we already reached (u, >= charge, <= swaps) with strictly better or equal cost
            // Actually standard Dijkstra on the expanded state graph is fast enough:
            // states = 200 * 41 * 7 = 57,400.

            // Option 1: Swap at station
            if (isStation[curr.u] && curr.swaps < maxSwaps && curr.charge < cap) {
                long nextMin = curr.minutes + swap_time;
                int nextSwaps = curr.swaps + 1;
                if (nextMin < bestMinutes[curr.u][cap][nextSwaps]) {
                    bestMinutes[curr.u][cap][nextSwaps] = nextMin;
                    pq.add(new State(nextMin, nextSwaps, curr.u, cap));
                }
            }

            // Option 2: Drive along an outgoing road
            for (Edge edge : adj.get(curr.u)) {
                if (edge.energy > 0 && curr.charge < edge.energy) {
                    continue;
                }
                int nextCharge = Math.min(cap, curr.charge - edge.energy);
                long nextMin = curr.minutes + edge.minutes;
                if (nextMin < bestMinutes[edge.to][nextCharge][curr.swaps]) {
                    bestMinutes[edge.to][nextCharge][curr.swaps] = nextMin;
                    pq.add(new State(nextMin, curr.swaps, edge.to, nextCharge));
                }
            }
        }

        return null;
    }
}

#include <vector>
#include <tuple>
#include <optional>
#include <queue>
#include <algorithm>
#include <limits>

std::optional<std::tuple<long long, long long>> fastest_delivery(
    long long n,
    const std::vector<std::tuple<long long, long long, long long, long long>>& roads,
    const std::vector<long long>& stations,
    long long capacity,
    long long swap_time,
    long long max_swaps,
    long long s,
    long long t)
{
    if (s == t) {
        return std::make_tuple(0LL, 0LL);
    }

    struct Edge {
        long long to;
        long long minutes;
        long long energy;
    };

    std::vector<std::vector<Edge>> adj(n);
    for (const auto& r : roads) {
        auto [u, v, m, e] = r;
        adj[u].push_back({v, m, e});
    }

    std::vector<bool> is_station(n, false);
    for (long long st : stations) {
        if (st >= 0 && st < n) {
            is_station[st] = true;
        }
    }

    const long long INF = std::numeric_limits<long long>::max();

    // State: (u, c, swaps)
    // Dimensions: n * (capacity + 1) * (max_swaps + 1)
    auto get_idx = [&](long long u, long long c, long long sw) {
        return (u * (capacity + 1) + c) * (max_swaps + 1) + sw;
    };

    long long total_states = n * (capacity + 1) * (max_swaps + 1);
    std::vector<long long> dist(total_states, INF);

    // Priority queue stores: (minutes, swaps, u, c)
    // We use greater<> for min-heap, so it naturally orders by smallest minutes, then smallest swaps.
    using State = std::tuple<long long, long long, long long, long long>;
    std::priority_queue<State, std::vector<State>, std::greater<State>> pq;

    dist[get_idx(s, capacity, 0)] = 0;
    pq.push({0, 0, s, capacity});

    while (!pq.empty()) {
        auto [d, sw, u, c] = pq.top();
        pq.pop();

        if (u == t) {
            return std::make_tuple(d, sw);
        }

        if (d > dist[get_idx(u, c, sw)]) {
            continue;
        }

        // Option 1: Swap battery if at a station and haven't reached max_swaps
        if (is_station[u] && sw < max_swaps && c < capacity) {
            long long next_d = d + swap_time;
            long long next_sw = sw + 1;
            long long next_c = capacity;
            long long idx = get_idx(u, next_c, next_sw);
            if (next_d < dist[idx]) {
                dist[idx] = next_d;
                pq.push({next_d, next_sw, u, next_c});
            }
        }

        // Option 2: Drive along an outgoing road
        for (const auto& edge : adj[u]) {
            if (edge.energy > 0 && c < edge.energy) {
                continue;
            }
            long long next_c = std::min(capacity, c - edge.energy);
            long long next_d = d + edge.minutes;
            long long idx = get_idx(edge.to, next_c, sw);
            if (next_d < dist[idx]) {
                dist[idx] = next_d;
                pq.push({next_d, sw, edge.to, next_c});
            }
        }
    }

    return std::nullopt;
}

export function fastestDelivery(
  n: number,
  roads: [number, number, number, number][],
  stations: number[],
  capacity: number,
  swap_time: number,
  max_swaps: number,
  s: number,
  t: number
): [number, number] | null {
  if (s === t) {
    return [0, 0];
  }

  const isStation = new Uint8Array(n);
  for (let i = 0; i < stations.length; i++) {
    isStation[stations[i]] = 1;
  }

  // Adjacency list: head[u], to[e], next[e], minCost[e], energy[e]
  const m = roads.length;
  const head = new Int32Array(n).fill(-1);
  const to = new Int32Array(m);
  const next = new Int32Array(m);
  const minCost = new Int32Array(m);
  const energy = new Int32Array(m);

  for (let i = 0; i < m; i++) {
    const [u, v, mins, en] = roads[i];
    to[i] = v;
    minCost[i] = mins;
    energy[i] = en;
    next[i] = head[u];
    head[u] = i;
  }

  const cap1 = capacity + 1;
  const swaps1 = max_swaps + 1;
  const numStates = n * cap1 * swaps1;

  // Store combined cost: (minutes * 8 + swaps) since max_swaps <= 6 < 8.
  // Max minutes <= numStates * 10^6 ~ 5.7 * 10^10, times 8 is ~4.5 * 10^11 < Number.MAX_SAFE_INTEGER (9 * 10^15).
  const dist = new Float64Array(numStates).fill(Infinity);

  const encodeState = (u: number, c: number, k: number): number => {
    return (u * cap1 + c) * swaps1 + k;
  };

  // Binary heap storing (cost, state)
  let heapCost = new Float64Array(4096);
  let heapState = new Int32Array(4096);
  let heapSize = 0;

  const push = (cost: number, state: number) => {
    if (heapSize === heapCost.length) {
      const newCost = new Float64Array(heapCost.length * 2);
      const newState = new Int32Array(heapState.length * 2);
      newCost.set(heapCost);
      newState.set(heapState);
      heapCost = newCost;
      heapState = newState;
    }
    let idx = heapSize++;
    while (idx > 0) {
      const parent = (idx - 1) >> 1;
      if (heapCost[parent] <= cost) break;
      heapCost[idx] = heapCost[parent];
      heapState[idx] = heapState[parent];
      idx = parent;
    }
    heapCost[idx] = cost;
    heapState[idx] = state;
  };

  const startState = encodeState(s, capacity, 0);
  dist[startState] = 0;
  push(0, startState);

  while (heapSize > 0) {
    const cost = heapCost[0];
    const state = heapState[0];

    // Pop from heap
    heapSize--;
    if (heapSize > 0) {
      const lastCost = heapCost[heapSize];
      const lastState = heapState[heapSize];
      let idx = 0;
      const half = heapSize >> 1;
      while (idx < half) {
        let child = (idx << 1) + 1;
        const right = child + 1;
        if (right < heapSize && heapCost[right] < heapCost[child]) {
          child = right;
        }
        if (lastCost <= heapCost[child]) break;
        heapCost[idx] = heapCost[child];
        heapState[idx] = heapState[child];
        idx = child;
      }
      heapCost[idx] = lastCost;
      heapState[idx] = lastState;
    }

    if (cost > dist[state]) continue;

    // Decode state
    const k = state % swaps1;
    const rem = (state - k) / swaps1;
    const c = rem % cap1;
    const u = (rem - c) / cap1;

    if (u === t) {
      const totalSwaps = cost % 8;
      const totalMinutes = (cost - totalSwaps) / 8;
      return [totalMinutes, totalSwaps];
    }

    // Option 1: Swap at u if it's a station
    if (isStation[u] === 1 && k < max_swaps && c < capacity) {
      const nextState = encodeState(u, capacity, k + 1);
      const nextCost = cost + swap_time * 8 + 1;
      if (nextCost < dist[nextState]) {
        dist[nextState] = nextCost;
        push(nextCost, nextState);
      }
    }

    // Option 2: Drive along outgoing roads
    for (let e = head[u]; e !== -1; e = next[e]) {
      const en = energy[e];
      if (c >= en) {
        let nextC = c - en;
        if (nextC > capacity) nextC = capacity;
        const v = to[e];
        const nextState = encodeState(v, nextC, k);
        const nextCost = cost + minCost[e] * 8;
        if (nextCost < dist[nextState]) {
          dist[nextState] = nextCost;
          push(nextCost, nextState);
        }
      }
    }
  }

  return null;
}

package main

import (
	"errors"
	"math"
)

type Tuple1 struct {
	F0 int
	F1 int
	F2 bool
}

func BestContext(messages []Tuple1, budget int, max_gap int, bonus int) (*int, error) {
	if budget < 0 || max_gap < 0 {
		return nil, errors.New("ValueError: budget and max_gap must be >= 0")
	}

	n := len(messages)
	if n == 0 {
		ans := 0
		return &ans, nil
	}

	effectiveGap := max_gap
	if effectiveGap > n {
		effectiveGap = n
	}

	const negInf = math.MinInt / 2

	stride := budget + 1
	size := (effectiveGap + 2) * stride

	dp := make([]int, size)
	nextDp := make([]int, size)
	for i := range dp {
		dp[i] = negInf
	}

	// Base state: 0 dropped messages before index 0, 0 length used.
	dp[1*stride+0] = 0

	for _, msg := range messages {
		length, value, pinned := msg.F0, msg.F1, msg.F2

		for i := range nextDp {
			nextDp[i] = negInf
		}

		for state := 0; state <= effectiveGap+1; state++ {
			rowOffset := state * stride
			for b := 0; b <= budget; b++ {
				val := dp[rowOffset+b]
				if val == negInf {
					continue
				}

				// Option 1: Keep this message
				if b+length <= budget {
					newVal := val + value
					if state == 0 {
						newVal += bonus
					}
					idx := 0*stride + (b + length)
					if newVal > nextDp[idx] {
						nextDp[idx] = newVal
					}
				}

				// Option 2: Drop this message
				if !pinned {
					var dropped int
					if state == 0 {
						dropped = 1
					} else {
						dropped = state
					}

					if dropped <= effectiveGap {
						nextState := dropped + 1
						idx := nextState*stride + b
						if val > nextDp[idx] {
							nextDp[idx] = val
						}
					}
				}
			}
		}

		dp, nextDp = nextDp, dp
	}

	ans := negInf
	for _, val := range dp {
		if val > ans {
			ans = val
		}
	}

	if ans == negInf {
		return nil, nil
	}

	return &ans, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, boolean f2) {}

    public static Long bestContext(List<Tuple1> messages, long budget, long max_gap, long bonus) {
        if (budget < 0 || max_gap < 0) {
            throw new IllegalArgumentException("budget and max_gap must be non-negative");
        }
        if (messages == null) {
            throw new IllegalArgumentException("messages cannot be null");
        }

        int n = messages.size();
        if (n == 0) {
            return 0L;
        }

        int B = (int) budget;
        int G = (int) Math.min(max_gap, (long) n);

        long NEG_INF = Long.MIN_VALUE / 4;

        // dp[b][g]: max score with total length 'b' and 'g' consecutive dropped messages at the end.
        long[][] dp = new long[B + 1][G + 1];
        for (int b = 0; b <= B; b++) {
            Arrays.fill(dp[b], NEG_INF);
        }
        dp[0][0] = 0L;

        for (int i = 0; i < n; i++) {
            Tuple1 msg = messages.get(i);
            long len = msg.f0();
            long val = msg.f1();
            boolean pinned = msg.f2();

            if (len < 0) {
                throw new IllegalArgumentException("length cannot be negative");
            }

            long[][] nextDp = new long[B + 1][G + 1];
            for (int b = 0; b <= B; b++) {
                Arrays.fill(nextDp[b], NEG_INF);
            }

            for (int b = 0; b <= B; b++) {
                for (int g = 0; g <= G; g++) {
                    long cur = dp[b][g];
                    if (cur <= NEG_INF) {
                        continue;
                    }

                    // Option 1: Keep message i
                    if (len <= B - b) {
                        int nb = b + (int) len;
                        long nval = cur + val + (i > 0 && g == 0 ? bonus : 0L);
                        if (nval > nextDp[nb][0]) {
                            nextDp[nb][0] = nval;
                        }
                    }

                    // Option 2: Drop message i
                    if (!pinned && g + 1 <= G) {
                        if (cur > nextDp[b][g + 1]) {
                            nextDp[b][g + 1] = cur;
                        }
                    }
                }
            }
            dp = nextDp;
        }

        long ans = NEG_INF;
        for (int b = 0; b <= B; b++) {
            for (int g = 0; g <= G; g++) {
                if (dp[b][g] > ans) {
                    ans = dp[b][g];
                }
            }
        }

        return ans <= NEG_INF ? null : ans;
    }
}

#include <vector>
#include <tuple>
#include <optional>
#include <stdexcept>
#include <algorithm>
#include <limits>

std::optional<long long> best_context(const std::vector<std::tuple<long long, long long, bool>>& messages, long long budget, long long max_gap, long long bonus) {
    if (budget < 0 || max_gap < 0) {
        throw std::invalid_argument("budget and max_gap must be non-negative");
    }

    int n = static_cast<int>(messages.size());
    int effective_max_gap = static_cast<int>(std::min<long long>(max_gap, n));
    int B = static_cast<int>(budget);

    const long long NEG_INF = std::numeric_limits<long long>::lowest() / 4;

    // dp[g][w] is the max score with `g` consecutive dropped messages at the end and total kept length `w`.
    std::vector<std::vector<long long>> dp(effective_max_gap + 1, std::vector<long long>(B + 1, NEG_INF));
    dp[0][0] = 0;

    for (int i = 0; i < n; ++i) {
        auto [len, val, pinned] = messages[i];
        std::vector<std::vector<long long>> next_dp(effective_max_gap + 1, std::vector<long long>(B + 1, NEG_INF));

        for (int g = 0; g <= effective_max_gap; ++g) {
            for (int w = 0; w <= B; ++w) {
                if (dp[g][w] == NEG_INF) continue;

                // Option 1: Keep message i
                if (w + len <= B) {
                    long long add_score = val;
                    if (i > 0 && g == 0) {
                        add_score += bonus;
                    }
                    int nw = static_cast<int>(w + len);
                    next_dp[0][nw] = std::max(next_dp[0][nw], dp[g][w] + add_score);
                }

                // Option 2: Drop message i
                if (!pinned && g + 1 <= effective_max_gap) {
                    next_dp[g + 1][w] = std::max(next_dp[g + 1][w], dp[g][w]);
                }
            }
        }
        dp = std::move(next_dp);
    }

    long long ans = NEG_INF;
    for (int g = 0; g <= effective_max_gap; ++g) {
        for (int w = 0; w <= B; ++w) {
            ans = std::max(ans, dp[g][w]);
        }
    }

    if (ans == NEG_INF) {
        return std::nullopt;
    }
    return ans;
}

export function bestContext(
    messages: [number, number, boolean][],
    budget: number,
    max_gap: number,
    bonus: number
): number | null {
    if (budget < 0 || max_gap < 0) {
        throw new Error("budget and max_gap must be non-negative");
    }

    const n = messages.length;
    if (n === 0) {
        return 0;
    }

    const maxG = Math.min(max_gap, n);
    const numStates = (maxG + 1) * (budget + 1);

    let dp = new Float64Array(numStates).fill(-Infinity);
    let nextDp = new Float64Array(numStates);

    dp[0] = 0; // gap = 0, used_budget = 0

    for (let i = 0; i < n; i++) {
        const [len, val, pinned] = messages[i];
        nextDp.fill(-Infinity);

        for (let g = 0; g <= maxG; g++) {
            const gOffset = g * (budget + 1);
            const canDrop = !pinned && g < max_gap;
            const nextGOffset = (g + 1) * (budget + 1);

            for (let b = 0; b <= budget; b++) {
                const currentScore = dp[gOffset + b];
                if (currentScore === -Infinity) continue;

                // Option 1: Keep message i
                if (b + len <= budget) {
                    const addedValue = val + (i > 0 && g === 0 ? bonus : 0);
                    const newScore = currentScore + addedValue;
                    const targetIdx = b + len; // next gap is 0, so offset is 0
                    if (newScore > nextDp[targetIdx]) {
                        nextDp[targetIdx] = newScore;
                    }
                }

                // Option 2: Drop message i
                if (canDrop) {
                    const targetIdx = nextGOffset + b;
                    if (currentScore > nextDp[targetIdx]) {
                        nextDp[targetIdx] = currentScore;
                    }
                }
            }
        }

        const temp = dp;
        dp = nextDp;
        nextDp = temp;
    }

    let ans = -Infinity;
    for (let i = 0; i < numStates; i++) {
        if (dp[i] > ans) {
            ans = dp[i];
        }
    }

    if (ans === -Infinity) {
        return null;
    }
    // Convert -0 to 0 just in case
    return ans === 0 ? 0 : ans;
}

package main

const inf = int(1e18)

func MinPruningCost(parent []int, demand []int, cap []int, cut_cost []int, critical []bool, root_cap int, penalty int) *int {
	n := len(parent)
	children := make([][]int, n)
	for i := 1; i < n; i++ {
		p := parent[i]
		children[p] = append(children[p], i)
	}

	// Build BFS order to avoid recursion depth issues and do bottom-up DP.
	order := make([]int, 0, n)
	order = append(order, 0)
	for i := 0; i < len(order); i++ {
		u := order[i]
		for _, v := range children[u] {
			order = append(order, v)
		}
	}

	hasCrit := make([]bool, n)
	subDemand := make([]int, n)
	for i := n - 1; i >= 0; i-- {
		u := order[i]
		hasCrit[u] = critical[u]
		subDemand[u] = demand[u]
		for _, v := range children[u] {
			if hasCrit[v] {
				hasCrit[u] = true
			}
			subDemand[u] += subDemand[v]
		}
	}

	dp := make([][]int, n)

	for i := n - 1; i >= 0; i-- {
		u := order[i]
		limit := root_cap
		if u > 0 {
			limit = cap[u]
		}
		maxLoad := subDemand[u]
		if limit < maxLoad {
			maxLoad = limit
		}

		if demand[u] > maxLoad {
			// Node u cannot be retained since its own demand exceeds its capacity limit.
			dp[u] = []int{}
			continue
		}

		cur := make([]int, demand[u]+1)
		for l := range cur {
			cur[l] = inf
		}
		cur[demand[u]] = 0

		for _, v := range children[u] {
			dpV := dp[v]
			newMax := len(cur) - 1 + len(dpV) - 1
			if len(dpV) == 0 {
				newMax = len(cur) - 1
			}
			if newMax > maxLoad {
				newMax = maxLoad
			}

			next := make([]int, newMax+1)
			for l := range next {
				next[l] = inf
			}

			// Option 1: cut line v (only allowed if v's subtree has no critical nodes).
			if !hasCrit[v] {
				cCost := cut_cost[v] + penalty*subDemand[v]
				for l1, cost1 := range cur {
					if cost1 < inf {
						next[l1] = cost1 + cCost
					}
				}
			}

			// Option 2: retain line v.
			for l1, cost1 := range cur {
				if cost1 == inf {
					continue
				}
				for l2, cost2 := range dpV {
					if l1+l2 > newMax {
						break
					}
					if cost2 < inf {
						if cost1+cost2 < next[l1+l2] {
							next[l1+l2] = cost1 + cost2
						}
					}
				}
			}

			cur = next
		}

		dp[u] = cur
	}

	ans := inf
	for _, cost := range dp[0] {
		if cost < ans {
			ans = cost
		}
	}

	if ans == inf {
		return nil
	}
	res := ans
	return &res
}

import java.util.*;

public final class Solution {
    private static final long INF = Long.MAX_VALUE / 4;

    public static Long minPruningCost(List<Long> parent, List<Long> demand, List<Long> cap, List<Long> cut_cost, List<Boolean> critical, long root_cap, long penalty) {
        int n = parent.size();
        List<List<Integer>> adj = new ArrayList<>(n);
        for (int i = 0; i < n; i++) {
            adj.add(new ArrayList<>());
        }
        for (int i = 1; i < n; i++) {
            int p = parent.get(i).intValue();
            adj.get(p).add(i);
        }

        // Topological sort (post-order) to process bottom-up
        int[] order = new int[n];
        int head = 0, tail = 0;
        order[tail++] = 0;
        while (head < tail) {
            int u = order[head++];
            for (int v : adj.get(u)) {
                order[tail++] = v;
            }
        }

        long[] subDemand = new long[n];
        boolean[] hasCrit = new boolean[n];
        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            subDemand[u] = demand.get(u);
            hasCrit[u] = critical.get(u);
            for (int v : adj.get(u)) {
                subDemand[u] += subDemand[v];
                hasCrit[u] |= hasCrit[v];
            }
        }

        // dp[u][w] = minimum cost in u's subtree (assuming u is retained) to achieve retained load w
        long[][] dp = new long[n][];

        for (int i = n - 1; i >= 0; i--) {
            int u = order[i];
            int limit = (int) Math.min(subDemand[u], u == 0 ? root_cap : cap.get(u));
            int d_u = demand.get(u).intValue();
            if (d_u > limit) {
                dp[u] = new long[0]; // Impossible to retain u
                continue;
            }

            long[] cur = new long[d_u + 1];
            Arrays.fill(cur, INF);
            cur[d_u] = 0;

            for (int v : adj.get(u)) {
                long[] childDp = dp[v];
                int nextMax = Math.min(limit, (cur.length - 1) + (childDp.length > 0 ? childDp.length - 1 : 0));
                long[] next = new long[nextMax + 1];
                Arrays.fill(next, INF);

                // Option 1: Cut line v (only allowed if v's subtree has no critical nodes)
                if (!hasCrit[v]) {
                    long cutCost = cut_cost.get(v) + penalty * subDemand[v];
                    for (int w1 = 0; w1 < cur.length; w1++) {
                        if (cur[w1] != INF) {
                            next[w1] = Math.min(next[w1], cur[w1] + cutCost);
                        }
                    }
                }

                // Option 2: Retain line v
                for (int w1 = 0; w1 < cur.length; w1++) {
                    if (cur[w1] == INF) continue;
                    for (int w2 = 0; w2 < childDp.length && w1 + w2 <= limit; w2++) {
                        if (childDp[w2] != INF) {
                            next[w1 + w2] = Math.min(next[w1 + w2], cur[w1] + childDp[w2]);
                        }
                    }
                }
                cur = next;
            }
            dp[u] = cur;
        }

        long ans = INF;
        for (long cost : dp[0]) {
            ans = Math.min(ans, cost);
        }

        return ans >= INF ? null : ans;
    }
}

#include <vector>
#include <optional>
#include <algorithm>
#include <limits>

std::optional<long long> min_pruning_cost(
    const std::vector<long long>& parent,
    const std::vector<long long>& demand,
    const std::vector<long long>& cap,
    const std::vector<long long>& cut_cost,
    const std::vector<bool>& critical,
    long long root_cap,
    long long penalty) {

    int n = parent.size();
    std::vector<std::vector<int>> adj(n);
    for (int i = 1; i < n; ++i) {
        adj[parent[i]].push_back(i);
    }

    const long long INF = std::numeric_limits<long long>::max() / 4;

    std::vector<long long> subtree_demand(n, 0);
    std::vector<bool> has_critical(n, false);
    std::vector<std::vector<long long>> dp(n);

    auto dfs = [&](auto& self, int u) -> void {
        subtree_demand[u] = demand[u];
        has_critical[u] = critical[u];

        long long max_u_cap = (u == 0) ? root_cap : cap[u];
        dp[u] = {INF}; // Temporary size, will resize as we merge

        // Initially, just node u itself
        if (demand[u] <= max_u_cap) {
            dp[u].assign(demand[u] + 1, INF);
            dp[u][demand[u]] = 0;
        } else {
            dp[u].clear(); // Cannot retain u
        }

        for (int v : adj[u]) {
            self(self, v);
            subtree_demand[u] += subtree_demand[v];
            if (has_critical[v]) {
                has_critical[u] = true;
            }

            if (dp[u].empty()) {
                continue;
            }

            long long max_new_load = std::min(max_u_cap, (long long)(dp[u].size() - 1 + (dp[v].empty() ? 0 : dp[v].size() - 1)));
            std::vector<long long> next_dp(max_new_load + 1, INF);

            // Option 1: Cut line v (only if v's subtree has no critical nodes)
            if (!has_critical[v]) {
                long long cost_to_cut = cut_cost[v] + penalty * subtree_demand[v];
                for (size_t load_u = 0; load_u < dp[u].size(); ++load_u) {
                    if (dp[u][load_u] != INF) {
                        next_dp[load_u] = std::min(next_dp[load_u], dp[u][load_u] + cost_to_cut);
                    }
                }
            }

            // Option 2: Retain line v
            if (!dp[v].empty()) {
                for (size_t load_u = 0; load_u < dp[u].size(); ++load_u) {
                    if (dp[u][load_u] == INF) continue;
                    for (size_t load_v = 0; load_v < dp[v].size(); ++load_v) {
                        if (dp[v][load_v] == INF) continue;
                        if (load_u + load_v <= (size_t)max_u_cap) {
                            next_dp[load_u + load_v] = std::min(next_dp[load_u + load_v], dp[u][load_u] + dp[v][load_v]);
                        }
                    }
                }
            }

            dp[u] = std::move(next_dp);
        }
    };

    dfs(dfs, 0);

    long long ans = INF;
    for (long long cost : dp[0]) {
        ans = std::min(ans, cost);
    }

    if (ans >= INF) {
        return std::nullopt;
    }
    return ans;
}

export function minPruningCost(
    parent: number[],
    demand: number[],
    cap: number[],
    cut_cost: number[],
    critical: boolean[],
    root_cap: number,
    penalty: number
): number | null {
    const n = parent.length;
    const children: number[][] = Array.from({ length: n }, () => []);
    for (let i = 1; i < n; i++) {
        children[parent[i]].push(i);
    }

    // Topological order (BFS from root 0)
    const order: number[] = [0];
    for (let head = 0; head < order.length; head++) {
        const u = order[head];
        for (const v of children[u]) {
            order.push(v);
        }
    }

    const subtreeDemand = new Array<number>(n).fill(0);
    const hasCritical = new Array<boolean>(n).fill(false);

    for (let i = n - 1; i >= 0; i--) {
        const u = order[i];
        subtreeDemand[u] = demand[u];
        hasCritical[u] = critical[u];
        for (const v of children[u]) {
            subtreeDemand[u] += subtreeDemand[v];
            if (hasCritical[v]) {
                hasCritical[u] = true;
            }
        }
    }

    const dp: number[][] = new Array(n);

    for (let i = n - 1; i >= 0; i--) {
        const u = order[i];
        const maxU = u === 0 ? Math.min(root_cap, subtreeDemand[0]) : Math.min(cap[u], subtreeDemand[u]);

        if (demand[u] > maxU) {
            dp[u] = [];
            continue;
        }

        let cur = new Array<number>(demand[u] + 1).fill(Infinity);
        cur[demand[u]] = 0;

        for (const v of children[u]) {
            const dpV = dp[v];
            const maxLoadV = dpV.length - 1;
            const nextMax = Math.min(maxU, cur.length - 1 + Math.max(0, maxLoadV));
            const next = new Array<number>(nextMax + 1).fill(Infinity);

            // Option 1: cut edge v (valid only if v's subtree has no critical nodes)
            if (!hasCritical[v]) {
                const cutEdgeCost = cut_cost[v] + penalty * subtreeDemand[v];
                for (let l1 = 0; l1 < cur.length; l1++) {
                    if (cur[l1] !== Infinity) {
                        next[l1] = cur[l1] + cutEdgeCost;
                    }
                }
            }

            // Option 2: retain edge v
            if (maxLoadV >= 0) {
                for (let l1 = 0; l1 < cur.length; l1++) {
                    const c1 = cur[l1];
                    if (c1 === Infinity) continue;
                    const limit = Math.min(maxLoadV, nextMax - l1);
                    for (let l2 = 0; l2 <= limit; l2++) {
                        const c2 = dpV[l2];
                        if (c2 !== Infinity) {
                            const sum = c1 + c2;
                            if (sum < next[l1 + l2]) {
                                next[l1 + l2] = sum;
                            }
                        }
                    }
                }
            }

            cur = next;
        }

        dp[u] = cur;
    }

    let ans = Infinity;
    for (let l = 0; l < dp[0].length; l++) {
        if (dp[0][l] < ans) {
            ans = dp[0][l];
        }
    }

    return ans === Infinity ? null : ans;
}

package main

import (
	"math"
	"sort"
)

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
	F3 int
	F4 int
}

type conn struct {
	tripID int
	from   int
	to     int
	dep    int
	arr    int
	trip   int // compact trip index
	pos    int // position in the trip's sorted connection sequence
}

func EarliestArrival(connections []Tuple1, transfer []int, source int, target int, start_time int, max_boardings int) *int {
	if source == target {
		res := start_time
		return &res
	}
	if max_boardings <= 0 || len(connections) == 0 {
		return nil
	}

	numStations := len(transfer)
	const INF = math.MaxInt64 / 4

	// Filter connections that depart before start_time (cannot be used anyway)
	// and map trip IDs to 0..numTrips-1
	tripMap := make(map[int]int)
	var conns []conn
	for _, c := range connections {
		if c.F3 < start_time {
			continue
		}
		tIdx, ok := tripMap[c.F0]
		if !ok {
			tIdx = len(tripMap)
			tripMap[c.F0] = tIdx
		}
		conns = append(conns, conn{
			tripID: c.F0,
			from:   c.F1,
			to:     c.F2,
			dep:    c.F3,
			arr:    c.F4,
			trip:   tIdx,
		})
	}

	if len(conns) == 0 {
		return nil
	}

	numTrips := len(tripMap)
	trips := make([][]conn, numTrips)
	for _, c := range conns {
		trips[c.trip] = append(trips[c.trip], c)
	}

	// Sort each trip's connections by departure time
	for t := 0; t < numTrips; t++ {
		sort.Slice(trips[t], func(i, j int) bool {
			return trips[t][i].dep < trips[t][j].dep
		})
		for i := range trips[t] {
			trips[t][i].pos = i
		}
	}

	// Group by station for fast range queries on departure time
	stationConns := make([][]conn, numStations)
	for t := 0; t < numTrips; t++ {
		for _, c := range trips[t] {
			stationConns[c.from] = append(stationConns[c.from], c)
		}
	}
	for s := 0; s < numStations; s++ {
		sort.Slice(stationConns[s], func(i, j int) bool {
			return stationConns[s][i].dep < stationConns[s][j].dep
		})
	}

	// ptr[s] points to the earliest not-yet-boarded connection at station s.
	// Since ready times only improve, we move ptr[s] from right to left.
	ptr := make([]int, numStations)
	for s := 0; s < numStations; s++ {
		ptr[s] = len(stationConns[s])
	}

	ready := make([]int, numStations)
	for s := 0; s < numStations; s++ {
		ready[s] = INF
	}
	ready[source] = start_time

	// tripReached[t] is the earliest position in trip t that has already been boarded
	tripReached := make([]int, numTrips)
	for t := 0; t < numTrips; t++ {
		tripReached[t] = len(trips[t])
	}

	bestTarget := INF

	changedStations := []int{source}
	inNextChanged := make([]bool, numStations)
	inTripQueue := make([]bool, numTrips)
	tripBestPos := make([]int, numTrips)
	for t := 0; t < numTrips; t++ {
		tripBestPos[t] = INF
	}

	for b := 1; b <= max_boardings; b++ {
		if len(changedStations) == 0 {
			break
		}

		var affectedTrips []int

		// Collect all newly reachable connections from stations whose ready time improved
		for _, u := range changedStations {
			r := ready[u]
			sc := stationConns[u]
			p := ptr[u]
			for p > 0 && sc[p-1].dep >= r {
				p--
				c := sc[p]
				if c.pos < tripReached[c.trip] && c.pos < tripBestPos[c.trip] {
					tripBestPos[c.trip] = c.pos
					if !inTripQueue[c.trip] {
						inTripQueue[c.trip] = true
						affectedTrips = append(affectedTrips, c.trip)
					}
				}
			}
			ptr[u] = p
		}

		if len(affectedTrips) == 0 {
			break
		}

		var nextChanged []int

		// Propagate along the newly boarded portions of trips
		for _, t := range affectedTrips {
			inTripQueue[t] = false
			startPos := tripBestPos[t]
			tripBestPos[t] = INF

			endPos := tripReached[t]
			if startPos >= endPos {
				continue
			}
			tripReached[t] = startPos

			tConns := trips[t]
			for i := startPos; i < endPos; i++ {
				c := tConns[i]
				if c.to == target && c.arr < bestTarget {
					bestTarget = c.arr
				}
				newReady := c.arr + transfer[c.to]
				if newReady < ready[c.to] {
					ready[c.to] = newReady
					if !inNextChanged[c.to] {
						inNextChanged[c.to] = true
						nextChanged = append(nextChanged, c.to)
					}
				}
			}
		}

		for _, s := range nextChanged {
			inNextChanged[s] = false
		}
		changedStations = nextChanged
	}

	if bestTarget == INF {
		return nil
	}
	return &bestTarget
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2, long f3, long f4) {}

    public static Long earliestArrival(List<Tuple1> connections, List<Long> transfer, long source, long target, long start_time, long max_boardings) {
        if (source == target) {
            return start_time;
        }
        if (max_boardings <= 0 || connections.isEmpty()) {
            return null;
        }

        int numStations = transfer.size();
        int m = connections.size();

        long[] transferArr = new long[numStations];
        for (int i = 0; i < numStations; i++) {
            transferArr[i] = transfer.get(i);
        }

        Map<Long, List<Tuple1>> tripsMap = new HashMap<>();
        int[] outDegree = new int[numStations];
        for (Tuple1 c : connections) {
            if (c.f3() < start_time) continue;
            tripsMap.computeIfAbsent(c.f0(), k -> new ArrayList<>()).add(c);
            outDegree[(int) c.f1()]++;
        }

        if (tripsMap.isEmpty()) {
            return null;
        }

        int validM = 0;
        for (List<Tuple1> list : tripsMap.values()) {
            validM += list.size();
        }

        int[] tripStart = new int[tripsMap.size()];
        int[] tripLen = new int[tripsMap.size()];
        int[] connFrom = new int[validM];
        int[] connTo = new int[validM];
        long[] connDep = new long[validM];
        long[] connArr = new long[validM];
        int[] connTrip = new int[validM];
        int[] connIdxInTrip = new int[validM];

        int tripIdCounter = 0;
        int connCounter = 0;

        for (List<Tuple1> list : tripsMap.values()) {
            list.sort(Comparator.comparingLong(Tuple1::f3));
            int tId = tripIdCounter++;
            tripStart[tId] = connCounter;
            tripLen[tId] = list.size();
            for (int i = 0; i < list.size(); i++) {
                Tuple1 c = list.get(i);
                connFrom[connCounter] = (int) c.f1();
                connTo[connCounter] = (int) c.f2();
                connDep[connCounter] = c.f3();
                connArr[connCounter] = c.f4();
                connTrip[connCounter] = tId;
                connIdxInTrip[connCounter] = i;
                connCounter++;
            }
        }

        int[][] stationConns = new int[numStations][];
        int[] currentOutIdx = new int[numStations];
        for (int i = 0; i < numStations; i++) {
            stationConns[i] = new int[outDegree[i]];
        }
        for (int cId = 0; cId < validM; cId++) {
            int u = connFrom[cId];
            stationConns[u][currentOutIdx[u]++] = cId;
        }

        for (int i = 0; i < numStations; i++) {
            if (outDegree[i] > 1) {
                Integer[] boxed = new Integer[outDegree[i]];
                for (int j = 0; j < outDegree[i]; j++) boxed[j] = stationConns[i][j];
                Arrays.sort(boxed, (a, b) -> Long.compare(connDep[b], connDep[a]));
                for (int j = 0; j < outDegree[i]; j++) stationConns[i][j] = boxed[j];
            }
        }

        int numTrips = tripIdCounter;
        int[] tripReachedIdx = new int[numTrips];
        Arrays.fill(tripReachedIdx, Integer.MAX_VALUE);

        int[] stationPtr = new int[numStations];

        long[] readyTime = new long[numStations];
        Arrays.fill(readyTime, Long.MAX_VALUE);
        readyTime[(int) source] = start_time;

        long[] nextReadyTime = new long[numStations];
        Arrays.fill(nextReadyTime, Long.MAX_VALUE);

        int[] activeStations = new int[numStations];
        int numActiveStations = 0;
        activeStations[numActiveStations++] = (int) source;

        int[] nextActiveStations = new int[numStations];
        boolean[] inNextActive = new boolean[numStations];

        int[] touchedTrips = new int[numTrips];
        int[] minStartIdx = new int[numTrips];
        Arrays.fill(minStartIdx, Integer.MAX_VALUE);

        long bestTargetArr = Long.MAX_VALUE;
        int targetInt = (int) target;

        long limit = Math.min(max_boardings, validM);

        for (long k = 1; k <= limit; k++) {
            if (numActiveStations == 0) break;

            int numTouchedTrips = 0;

            for (int i = 0; i < numActiveStations; i++) {
                int u = activeStations[i];
                long rTime = readyTime[u];
                int[] conns = stationConns[u];
                int ptr = stationPtr[u];
                int len = conns.length;

                while (ptr < len && connDep[conns[ptr]] >= rTime) {
                    int cId = conns[ptr];
                    int tId = connTrip[cId];
                    int idx = connIdxInTrip[cId];
                    if (idx < tripReachedIdx[tId]) {
                        if (minStartIdx[tId] == Integer.MAX_VALUE) {
                            touchedTrips[numTouchedTrips++] = tId;
                        }
                        if (idx < minStartIdx[tId]) {
                            minStartIdx[tId] = idx;
                        }
                    }
                    ptr++;
                }
                stationPtr[u] = ptr;
            }

            if (numTouchedTrips == 0) break;

            int numNextActive = 0;

            for (int i = 0; i < numTouchedTrips; i++) {
                int tId = touchedTrips[i];
                int startIdx = minStartIdx[tId];
                minStartIdx[tId] = Integer.MAX_VALUE;

                int endIdx = tripReachedIdx[tId];
                if (endIdx == Integer.MAX_VALUE) {
                    endIdx = tripLen[tId];
                }

                if (startIdx < endIdx) {
                    int base = tripStart[tId];
                    for (int idx = startIdx; idx < endIdx; idx++) {
                        int cId = base + idx;
                        int v = connTo[cId];
                        long arr = connArr[cId];

                        if (v == targetInt && arr < bestTargetArr) {
                            bestTargetArr = arr;
                        }

                        long nr = arr + transferArr[v];
                        if (nr < readyTime[v] && nr < nextReadyTime[v]) {
                            nextReadyTime[v] = nr;
                            if (!inNextActive[v]) {
                                inNextActive[v] = true;
                                nextActiveStations[numNextActive++] = v;
                            }
                        }
                    }
                    tripReachedIdx[tId] = startIdx;
                }
            }

            numActiveStations = 0;
            for (int i = 0; i < numNextActive; i++) {
                int v = nextActiveStations[i];
                readyTime[v] = nextReadyTime[v];
                nextReadyTime[v] = Long.MAX_VALUE;
                inNextActive[v] = false;
                activeStations[numActiveStations++] = v;
            }
        }

        return bestTargetArr == Long.MAX_VALUE ? null : bestTargetArr;
    }
}

#include <vector>
#include <tuple>
#include <optional>
#include <algorithm>
#include <limits>
#include <queue>

std::optional<long long> earliest_arrival(
    const std::vector<std::tuple<long long, long long, long long, long long, long long>>& connections,
    const std::vector<long long>& transfer,
    long long source,
    long long target,
    long long start_time,
    long long max_boardings)
{
    if (source == target) {
        return start_time;
    }
    if (max_boardings <= 0 || connections.empty()) {
        return std::nullopt;
    }

    size_t num_stations = transfer.size();
    const long long INF = std::numeric_limits<long long>::max() / 4;

    struct Conn {
        long long trip_id;
        long long u;
        long long v;
        long long dep;
        long long arr;
    };

    std::vector<Conn> sorted_conns;
    sorted_conns.reserve(connections.size());
    for (const auto& c : connections) {
        long long dep = std::get<3>(c);
        if (dep >= start_time) {
            sorted_conns.push_back({std::get<0>(c), std::get<1>(c), std::get<2>(c), dep, std::get<4>(c)});
        }
    }

    if (sorted_conns.empty()) {
        return std::nullopt;
    }

    // Group by trip_id and sort by departure time to reconstruct trips
    std::sort(sorted_conns.begin(), sorted_conns.end(), [](const Conn& a, const Conn& b) {
        if (a.trip_id != b.trip_id) return a.trip_id < b.trip_id;
        return a.dep < b.dep;
    });

    struct Trip {
        std::vector<Conn> conns;
    };

    std::vector<Trip> trips;
    for (size_t i = 0; i < sorted_conns.size(); ) {
        size_t j = i;
        Trip t;
        while (j < sorted_conns.size() && sorted_conns[j].trip_id == sorted_conns[i].trip_id) {
            t.conns.push_back(sorted_conns[j]);
            j++;
        }
        trips.push_back(std::move(t));
        i = j;
    }

    // Index connections by their departure station
    std::vector<std::vector<std::tuple<long long, int, int>>> station_conns(num_stations);
    for (int t_idx = 0; t_idx < (int)trips.size(); ++t_idx) {
        const auto& c_list = trips[t_idx].conns;
        for (int c_idx = 0; c_idx < (int)c_list.size(); ++c_idx) {
            station_conns[c_list[c_idx].u].emplace_back(c_list[c_idx].dep, t_idx, c_idx);
        }
    }

    // Sort station connections in ascending order of departure time.
    // This allows efficient traversal from latest to earliest by scanning from the back.
    for (size_t u = 0; u < num_stations; ++u) {
        std::sort(station_conns[u].begin(), station_conns[u].end(), [](const auto& a, const auto& b) {
            return std::get<0>(a) < std::get<0>(b);
        });
    }

    // Case 1: max_boardings is large enough that the boarding limit is never more restrictive
    // than a simple path of connections. Use Modified Dijkstra's Algorithm.
    if (max_boardings >= (long long)sorted_conns.size()) {
        std::vector<long long> min_ready(num_stations, INF);
        std::vector<int> ptr(num_stations);
        for (size_t u = 0; u < num_stations; ++u) {
            ptr[u] = (int)station_conns[u].size() - 1;
        }
        std::vector<int> trip_reached(trips.size(), std::numeric_limits<int>::max());

        using P = std::pair<long long, long long>;
        std::priority_queue<P, std::vector<P>, std::greater<P>> pq;

        min_ready[source] = start_time;
        pq.push({start_time, source});

        long long ans = INF;

        while (!pq.empty()) {
            auto [r_time, u] = pq.top();
            pq.pop();

            if (r_time > min_ready[u]) continue;
            if (r_time >= ans) break; // Since transfer >= 0 and arr > dep, we can't beat ans anymore.

            // Scan all connections departing at or after r_time that haven't been processed yet
            while (ptr[u] >= 0 && std::get<0>(station_conns[u][ptr[u]]) >= r_time) {
                auto [dep, t_idx, c_idx] = station_conns[u][ptr[u]];
                ptr[u]--;

                // Propagate along the trip up to the earliest previously reached index
                if (c_idx < trip_reached[t_idx]) {
                    int limit = trip_reached[t_idx];
                    trip_reached[t_idx] = c_idx;
                    const auto& c_list = trips[t_idx].conns;
                    for (int i = c_idx; i < limit && i < (int)c_list.size(); ++i) {
                        long long v = c_list[i].v;
                        long long arr = c_list[i].arr;
                        if (v == target) {
                            ans = std::min(ans, arr);
                        }
                        long long next_ready = arr + transfer[v];
                        if (next_ready < min_ready[v]) {
                            min_ready[v] = next_ready;
                            pq.push({next_ready, v});
                        }
                    }
                }
            }
        }

        if (ans == INF) return std::nullopt;
        return ans;
    } 
    // Case 2: max_boardings is small. Use Round-Based Dynamic Programming (RAPTOR-style).
    else {
        std::vector<long long> ready(num_stations, INF);
        ready[source] = start_time;

        std::vector<int> ptr(num_stations);
        for (size_t u = 0; u < num_stations; ++u) {
            ptr[u] = (int)station_conns[u].size() - 1;
        }
        std::vector<int> trip_reached(trips.size(), std::numeric_limits<int>::max());

        std::vector<long long> active_stations = {source};
        std::vector<int> trip_min_c(trips.size(), std::numeric_limits<int>::max());
        std::vector<int> active_trips;

        std::vector<long long> next_ready(num_stations, INF);
        std::vector<bool> in_next_active(num_stations, false);

        long long ans = INF;

        for (long long k = 1; k <= max_boardings; ++k) {
            active_trips.clear();

            for (long long u : active_stations) {
                long long r_time = ready[u];
                while (ptr[u] >= 0 && std::get<0>(station_conns[u][ptr[u]]) >= r_time) {
                    auto [dep, t_idx, c_idx] = station_conns[u][ptr[u]];
                    ptr[u]--;

                    if (c_idx < trip_reached[t_idx]) {
                        if (trip_min_c[t_idx] == std::numeric_limits<int>::max()) {
                            active_trips.push_back(t_idx);
                        }
                        trip_min_c[t_idx] = std::min(trip_min_c[t_idx], c_idx);
                    }
                }
            }

            if (active_trips.empty()) break;

            std::vector<long long> next_active_stations;

            for (int t_idx : active_trips) {
                int start_c = trip_min_c[t_idx];
                int end_c = trip_reached[t_idx];
                trip_reached[t_idx] = start_c;
                trip_min_c[t_idx] = std::numeric_limits<int>::max(); // Reset for next round

                const auto& c_list = trips[t_idx].conns;
                for (int i = start_c; i < end_c && i < (int)c_list.size(); ++i) {
                    long long v = c_list[i].v;
                    long long arr = c_list[i].arr;
                    if (v == target) {
                        ans = std::min(ans, arr);
                    }
                    long long nr = arr + transfer[v];
                    if (nr < ready[v] && nr < next_ready[v]) {
                        next_ready[v] = nr;
                        if (!in_next_active[v]) {
                            in_next_active[v] = true;
                            next_active_stations.push_back(v);
                        }
                    }
                }
            }

            for (long long v : next_active_stations) {
                ready[v] = next_ready[v];
                next_ready[v] = INF;
                in_next_active[v] = false;
            }

            active_stations = std::move(next_active_stations);
            if (active_stations.empty()) break;
        }

        if (ans == INF) return std::nullopt;
        return ans;
    }
}

export function earliestArrival(
    connections: [number, number, number, number, number][],
    transfer: number[],
    source: number,
    target: number,
    start_time: number,
    max_boardings: number
): number | null {
    if (source === target) {
        return start_time;
    }
    if (max_boardings === 0 || connections.length === 0) {
        return null;
    }

    const numStations = transfer.length;

    // Group connections by trip_id
    const tripMap = new Map<number, [number, number, number, number, number][]>();
    for (let i = 0; i < connections.length; i++) {
        const c = connections[i];
        let list = tripMap.get(c[0]);
        if (!list) {
            list = [];
            tripMap.set(c[0], list);
        }
        list.push(c);
    }

    // Flatten trips into typed arrays for fast access
    const numTrips = tripMap.size;
    const numConns = connections.length;

    const tripStart = new Int32Array(numTrips);
    const tripLen = new Int32Array(numTrips);

    const connFrom = new Int32Array(numConns);
    const connTo = new Int32Array(numConns);
    const connDep = new Float64Array(numConns);
    const connArr = new Float64Array(numConns);

    // Count departures per station to build CSR-like structure for station departures
    const stationDepCount = new Int32Array(numStations);

    let connIdx = 0;
    let tripIdx = 0;
    for (const list of tripMap.values()) {
        list.sort((a, b) => a[3] - b[3]);
        tripStart[tripIdx] = connIdx;
        tripLen[tripIdx] = list.length;
        for (let i = 0; i < list.length; i++) {
            const c = list[i];
            connFrom[connIdx] = c[1];
            connTo[connIdx] = c[2];
            connDep[connIdx] = c[3];
            connArr[connIdx] = c[4];
            stationDepCount[c[1]]++;
            connIdx++;
        }
        tripIdx++;
    }

    // Build station departure lists (sorted by dep descending so we can pop from the end, or ascending with a pointer)
    const stationDepStart = new Int32Array(numStations);
    const stationDepPtr = new Int32Array(numStations);
    let totalDeps = 0;
    for (let s = 0; s < numStations; s++) {
        stationDepStart[s] = totalDeps;
        stationDepPtr[s] = totalDeps;
        totalDeps += stationDepCount[s];
    }

    // Temporary array to hold indices before sorting per station
    const stationDeps = new Int32Array(numConns);
    const stationDepEnd = new Int32Array(numStations);
    for (let s = 0; s < numStations; s++) {
        stationDepEnd[s] = stationDepStart[s];
    }

    // We need to know which trip a connection belongs to and its index within the trip
    const connTrip = new Int32Array(numConns);
    const connTripOffset = new Int32Array(numConns);
    for (let t = 0; t < numTrips; t++) {
        const start = tripStart[t];
        const len = tripLen[t];
        for (let i = 0; i < len; i++) {
            const cIdx = start + i;
            connTrip[cIdx] = t;
            connTripOffset[cIdx] = i;
            const s = connFrom[cIdx];
            stationDeps[stationDepEnd[s]++] = cIdx;
        }
    }

    // Sort each station's departures by departure time descending.
    // As ready time at a station decreases, we can advance a pointer through the sorted connections.
    const tempArr: number[] = [];
    for (let s = 0; s < numStations; s++) {
        const start = stationDepStart[s];
        const end = stationDepEnd[s];
        const len = end - start;
        if (len > 1) {
            tempArr.length = len;
            for (let i = 0; i < len; i++) tempArr[i] = stationDeps[start + i];
            tempArr.sort((a, b) => connDep[b] - connDep[a]);
            for (let i = 0; i < len; i++) stationDeps[start + i] = tempArr[i];
        }
    }

    // For each trip, maintain the earliest connection offset we have already scanned from.
    // Initially, it's tripLen[t]. When we board at offset `i`, we scan `i` up to `tripReached[t] - 1`,
    // and then set `tripReached[t] = i`.
    const tripReached = new Int32Array(numTrips);
    for (let t = 0; t < numTrips; t++) {
        tripReached[t] = tripLen[t];
    }

    // Best ready time at each station
    const INF = Infinity;
    const bestReady = new Float64Array(numStations);
    bestReady.fill(INF);

    let bestTargetArr = INF;

    // Stations whose ready time improved in the previous round
    let activeStations: number[] = [];
    let nextActiveStations: number[] = [];
    const inNextActive = new Uint8Array(numStations);

    // Trips that were boarded in the current round, and the minimum offset they were boarded at
    const boardedTrips: number[] = [];
    const minBoardedOffset = new Int32Array(numTrips);
    minBoardedOffset.fill(1000000000);
    const tripBoardedFlag = new Uint8Array(numTrips);

    // Initialize for source
    bestReady[source] = start_time;
    activeStations.push(source);

    const limit = Math.min(max_boardings, numConns);

    for (let b = 1; b <= limit; b++) {
        if (activeStations.length === 0) {
            break;
        }

        // 1. From all active stations, find newly reachable connections
        for (let i = 0; i < activeStations.length; i++) {
            const s = activeStations[i];
            const ready = bestReady[s];
            let ptr = stationDepPtr[s];
            const end = stationDepEnd[s];

            while (ptr < end) {
                const cIdx = stationDeps[ptr];
                if (connDep[cIdx] >= ready) {
                    const t = connTrip[cIdx];
                    const offset = connTripOffset[cIdx];
                    if (offset < tripReached[t]) {
                        if (tripBoardedFlag[t] === 0) {
                            tripBoardedFlag[t] = 1;
                            boardedTrips.push(t);
                        }
                        if (offset < minBoardedOffset[t]) {
                            minBoardedOffset[t] = offset;
                        }
                    }
                    ptr++;
                } else {
                    break;
                }
            }
            stationDepPtr[s] = ptr;
        }

        if (boardedTrips.length === 0) {
            break;
        }

        // 2. Scan the newly reachable suffixes of trips
        for (let i = 0; i < boardedTrips.length; i++) {
            const t = boardedTrips[i];
            const startOffset = minBoardedOffset[t];
            const endOffset = tripReached[t];
            const baseIdx = tripStart[t];

            for (let offset = startOffset; offset < endOffset; offset++) {
                const cIdx = baseIdx + offset;
                const toSt = connTo[cIdx];
                const arr = connArr[cIdx];

                if (toSt === target && arr < bestTargetArr) {
                    bestTargetArr = arr;
                }

                const newReady = arr + transfer[toSt];
                if (newReady < bestReady[toSt]) {
                    bestReady[toSt] = newReady;
                    if (inNextActive[toSt] === 0) {
                        inNextActive[toSt] = 1;
                        nextActiveStations.push(toSt);
                    }
                }
            }

            tripReached[t] = startOffset;
            tripBoardedFlag[t] = 0;
            minBoardedOffset[t] = 1000000000;
        }
        boardedTrips.length = 0;

        // Prepare for next round
        for (let i = 0; i < nextActiveStations.length; i++) {
            inNextActive[nextActiveStations[i]] = 0;
        }
        const temp = activeStations;
        activeStations = nextActiveStations;
        nextActiveStations = temp;
        nextActiveStations.length = 0;
    }

    return bestTargetArr === INF ? null : bestTargetArr;
}

package main

import (
	"errors"
)

type Tuple1 struct {
	F0 int
	F1 string
	F2 int
	F3 bool
}

type clientState struct {
	tokens     int
	lastT      int
	bannedUntil int
	strikes    []int
	strikeHead int
}

func AdmitRequests(requests []Tuple1, config map[string]int) ([]string, error) {
	n := len(requests)
	for i := 1; i < n; i++ {
		if requests[i].F0 < requests[i-1].F0 {
			return nil, errors.New("requests not sorted by time")
		}
	}

	cCap := config["cap"]
	cPeriod := config["period"]
	gCap := config["gcap"]
	gPeriod := config["gperiod"]
	reserve := config["reserve"]
	maxStrikes := config["strikes"]
	window := config["window"]
	banLen := config["ban"]

	gTokens := gCap
	gLastT := 0

	clients := make(map[string]*clientState)
	results := make([]string, n)

	for i, req := range requests {
		t := req.F0
		cName := req.F1
		cost := req.F2
		vip := req.F3

		// Update global bucket
		if t > gLastT {
			refills := (t / gPeriod) - (gLastT / gPeriod)
			if refills > 0 {
				gTokens += refills
				if gTokens > gCap {
					gTokens = gCap
				}
			}
			gLastT = t
		}

		// Get or create client state
		cs, exists := clients[cName]
		if !exists {
			cs = &clientState{
				tokens:      cCap,
				lastT:       t,
				bannedUntil: -1,
			}
			clients[cName] = cs
		} else {
			if t > cs.lastT {
				refills := (t / cPeriod) - (cs.lastT / cPeriod)
				if refills > 0 {
					cs.tokens += refills
					if cs.tokens > cCap {
						cs.tokens = cCap
					}
				}
				cs.lastT = t
			}
		}

		// Rule 1: Banned check
		if t < cs.bannedUntil {
			results[i] = "BANNED"
			continue
		}

		// Rule 2: Client bucket check
		if cs.tokens < cost {
			cs.strikes = append(cs.strikes, t)
			// Prune old strikes outside (t - window, t]
			cutoff := t - window
			for cs.strikeHead < len(cs.strikes) && cs.strikes[cs.strikeHead] <= cutoff {
				cs.strikeHead++
			}
			activeStrikes := len(cs.strikes) - cs.strikeHead
			if activeStrikes >= maxStrikes {
				results[i] = "BAN"
				cs.bannedUntil = t + banLen
				cs.strikes = nil
				cs.strikeHead = 0
			} else {
				results[i] = "DENY"
			}
			continue
		}

		// Rule 3: Global bucket check
		if vip {
			if gTokens < cost {
				results[i] = "BUSY"
				continue
			}
		} else {
			if gTokens-cost < reserve {
				results[i] = "BUSY"
				continue
			}
		}

		// Rule 4: Admit
		cs.tokens -= cost
		gTokens -= cost
		results[i] = "OK"
	}

	return results, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, String f1, long f2, boolean f3) {}

    private static final class ClientState {
        long tokens;
        long lastT;
        long bannedUntil = -1;
        final ArrayDeque<Long> strikes = new ArrayDeque<>();

        ClientState(long cap, long t) {
            this.tokens = cap;
            this.lastT = t;
        }
    }

    public static List<String> admitRequests(List<Tuple1> requests, Map<String, Long> config) {
        int n = requests.size();
        for (int i = 1; i < n; i++) {
            if (requests.get(i).f0() < requests.get(i - 1).f0()) {
                throw new IllegalArgumentException("Timestamps must be non-decreasing");
            }
        }

        long cap = config.get("cap");
        long period = config.get("period");
        long gcap = config.get("gcap");
        long gperiod = config.get("gperiod");
        long reserve = config.get("reserve");
        long strikesLimit = config.get("strikes");
        long window = config.get("window");
        long ban = config.get("ban");

        long gtokens = gcap;
        long glastT = 0;

        Map<String, ClientState> clients = new HashMap<>();
        List<String> result = new ArrayList<>(n);

        for (Tuple1 req : requests) {
            long t = req.f0();
            String c = req.f1();
            long cost = req.f2();
            boolean vip = req.f3();

            // Refill global bucket
            if (t > glastT) {
                long refills = (t / gperiod) - (glastT / gperiod);
                if (refills > 0) {
                    gtokens = Math.min(gcap, gtokens + refills);
                }
                glastT = t;
            }

            // Get or create client bucket, and refill if already existing
            ClientState cs = clients.get(c);
            if (cs == null) {
                cs = new ClientState(cap, t);
                clients.put(c, cs);
            } else if (t > cs.lastT) {
                long refills = (t / period) - (cs.lastT / period);
                if (refills > 0) {
                    cs.tokens = Math.min(cap, cs.tokens + refills);
                }
                cs.lastT = t;
            }

            // Rule 1: Check ban
            if (t < cs.bannedUntil) {
                result.add("BANNED");
                continue;
            }

            // Rule 2: Check client tokens
            if (cs.tokens < cost) {
                cs.strikes.addLast(t);
                long cutoff = t - window;
                while (!cs.strikes.isEmpty() && cs.strikes.peekFirst() <= cutoff) {
                    cs.strikes.pollFirst();
                }
                if (cs.strikes.size() >= strikesLimit) {
                    cs.strikes.clear();
                    cs.bannedUntil = t + ban;
                    result.add("BAN");
                } else {
                    result.add("DENY");
                }
                continue;
            }

            // Rule 3: Check global tokens
            boolean globalOk = vip ? (gtokens >= cost) : (gtokens - cost >= reserve);
            if (!globalOk) {
                result.add("BUSY");
                continue;
            }

            // Rule 4: Admit
            cs.tokens -= cost;
            gtokens -= cost;
            result.add("OK");
        }

        return result;
    }
}

#include <algorithm>
#include <deque>
#include <map>
#include <stdexcept>
#include <string>
#include <tuple>
#include <unordered_map>
#include <vector>

struct ClientState {
    long long tokens;
    long long last_time;
    long long ban_until = -1;
    std::deque<long long> strikes;
};

std::vector<std::string> admit_requests(
    const std::vector<std::tuple<long long, std::string, long long, bool>>& requests,
    const std::map<std::string, long long>& config) {

    // Validate non-decreasing timestamps before producing anything
    for (size_t i = 1; i < requests.size(); ++i) {
        if (std::get<0>(requests[i]) < std::get<0>(requests[i - 1])) {
            throw std::invalid_argument("Request times must be non-decreasing");
        }
    }

    long long cap = config.at("cap");
    long long period = config.at("period");
    long long gcap = config.at("gcap");
    long long gperiod = config.at("gperiod");
    long long reserve = config.at("reserve");
    long long strikes_limit = config.at("strikes");
    long long window = config.at("window");
    long long ban_len = config.at("ban");

    long long global_tokens = gcap;
    long long global_last_time = 0;

    std::unordered_map<std::string, ClientState> clients;
    clients.reserve(5000);

    std::vector<std::string> results;
    results.reserve(requests.size());

    for (const auto& req : requests) {
        long long t = std::get<0>(req);
        const std::string& client = std::get<1>(req);
        long long cost = std::get<2>(req);
        bool vip = std::get<3>(req);

        // Update global bucket
        long long g_refills = (t / gperiod) - (global_last_time / gperiod);
        if (g_refills > 0) {
            global_tokens = std::min(gcap, global_tokens + g_refills);
        }
        global_last_time = t;

        // Find or create client state
        auto it = clients.find(client);
        if (it == clients.end()) {
            it = clients.emplace(client, ClientState{cap, t, -1, {}}).first;
        } else {
            long long c_refills = (t / period) - (it->second.last_time / period);
            if (c_refills > 0) {
                it->second.tokens = std::min(cap, it->second.tokens + c_refills);
            }
            it->second.last_time = t;
        }

        ClientState& st = it->second;

        // Rule 1: Check if banned
        if (t < st.ban_until) {
            results.push_back("BANNED");
            continue;
        }

        // Rule 2: Check client bucket capacity
        if (st.tokens < cost) {
            st.strikes.push_back(t);
            while (!st.strikes.empty() && st.strikes.front() <= t - window) {
                st.strikes.pop_front();
            }
            if (static_cast<long long>(st.strikes.size()) >= strikes_limit) {
                st.strikes.clear();
                st.ban_until = t + ban_len;
                results.push_back("BAN");
            } else {
                results.push_back("DENY");
            }
            continue;
        }

        // Rule 3: Check global bucket
        long long needed_left = vip ? 0 : reserve;
        if (global_tokens - cost < needed_left) {
            results.push_back("BUSY");
            continue;
        }

        // Rule 4: Admit request
        st.tokens -= cost;
        global_tokens -= cost;
        results.push_back("OK");
    }

    return results;
}

interface ClientState {
    tokens: number;
    lastRefillMultiple: number;
    bannedUntil: number;
    strikes: number[];
    strikeHead: number;
}

export function admitRequests(
    requests: [number, string, number, boolean][],
    config: Record<string, number>
): string[] {
    const n = requests.length;
    for (let i = 1; i < n; i++) {
        if (requests[i][0] < requests[i - 1][0]) {
            throw new Error("Requests are not sorted by time");
        }
    }

    const cap = config["cap"];
    const period = config["period"];
    const gcap = config["gcap"];
    const gperiod = config["gperiod"];
    const reserve = config["reserve"];
    const maxStrikes = config["strikes"];
    const windowLen = config["window"];
    const banLen = config["ban"];

    let globalTokens = gcap;
    let globalLastMultiple = 0;

    const clients = new Map<string, ClientState>();
    const results: string[] = new Array(n);

    for (let i = 0; i < n; i++) {
        const req = requests[i];
        const t = req[0];
        const clientId = req[1];
        const cost = req[2];
        const vip = req[3];

        // Update global bucket
        const currentGlobalMultiple = Math.floor(t / gperiod);
        if (currentGlobalMultiple > globalLastMultiple) {
            globalTokens = Math.min(gcap, globalTokens + (currentGlobalMultiple - globalLastMultiple));
            globalLastMultiple = currentGlobalMultiple;
        }

        // Get or create client state, and update client bucket
        const currentClientMultiple = Math.floor(t / period);
        let client = clients.get(clientId);
        if (client === undefined) {
            client = {
                tokens: cap,
                lastRefillMultiple: currentClientMultiple,
                bannedUntil: -1,
                strikes: [],
                strikeHead: 0,
            };
            clients.set(clientId, client);
        } else if (currentClientMultiple > client.lastRefillMultiple) {
            client.tokens = Math.min(cap, client.tokens + (currentClientMultiple - client.lastRefillMultiple));
            client.lastRefillMultiple = currentClientMultiple;
        }

        // Rule 1: Check if banned
        if (t < client.bannedUntil) {
            results[i] = "BANNED";
            continue;
        }

        // Rule 2: Check client bucket
        if (client.tokens < cost) {
            client.strikes.push(t);
            const cutoff = t - windowLen;
            while (client.strikeHead < client.strikes.length && client.strikes[client.strikeHead] <= cutoff) {
                client.strikeHead++;
            }
            const activeStrikes = client.strikes.length - client.strikeHead;
            if (activeStrikes >= maxStrikes) {
                client.bannedUntil = t + banLen;
                client.strikes = [];
                client.strikeHead = 0;
                results[i] = "BAN";
            } else {
                results[i] = "DENY";
            }
            continue;
        }

        // Rule 3: Check global bucket
        const minGlobalRemaining = vip ? 0 : reserve;
        if (globalTokens - cost < minGlobalRemaining) {
            results[i] = "BUSY";
            continue;
        }

        // Rule 4: Admit request
        client.tokens -= cost;
        globalTokens -= cost;
        results[i] = "OK";
    }

    return results;
}

package main

import (
	"fmt"
	"strings"
)

type Tuple1 struct {
	F0 string
	F1 []string
	F2 string
	F3 string
}

type parsedRule struct {
	index         int
	isDeny        bool
	principalType int // 0: *, 1: group, 2: user
	principalName string
	actionAny     bool
	actions       map[string]bool
	segments      []string
	specificityL  int
	specificityP  int
	specificityA  int
}

func isName(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_') {
			return false
		}
	}
	return true
}

func isActionWord(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !(c >= 'a' && c <= 'z') {
			return false
		}
	}
	return true
}

func isPathSegment(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-') {
			return false
		}
	}
	return true
}

func parseResource(s string, allowWildcards bool) ([]string, int, bool) {
	if s == "/" {
		return []string{}, 0, true
	}
	if !strings.HasPrefix(s, "/") {
		return nil, 0, false
	}
	parts := strings.Split(s[1:], "/")
	L := 0
	for _, p := range parts {
		if allowWildcards && (p == "*" || p == "**") {
			continue
		}
		if !isPathSegment(p) {
			return nil, 0, false
		}
		L++
	}
	return parts, L, true
}

func matchSegments(pattern, path []string) bool {
	m := len(pattern)
	n := len(path)
	dp := make([]bool, n+1)
	dp[0] = true

	for i := 1; i <= m; i++ {
		pat := pattern[i-1]
		if pat == "**" {
			for j := 1; j <= n; j++ {
				dp[j] = dp[j] || dp[j-1]
			}
		} else {
			for j := n; j >= 1; j-- {
				if pat == "*" || pat == path[j-1] {
					dp[j] = dp[j-1]
				} else {
					dp[j] = false
				}
			}
			dp[0] = false
		}
	}
	return dp[n]
}

func EvaluateAccess(rules []string, requests []Tuple1) ([]string, error) {
	parsedRules := make([]parsedRule, len(rules))

	for i, r := range rules {
		fields := strings.Fields(r)
		if len(fields) != 4 {
			return nil, fmt.Errorf("rule %d: expected 4 fields, got %d", i, len(fields))
		}
		effect, principal, action, resource := fields[0], fields[1], fields[2], fields[3]

		var isDeny bool
		if effect == "ALLOW" {
			isDeny = false
		} else if effect == "DENY" {
			isDeny = true
		} else {
			return nil, fmt.Errorf("rule %d: bad effect %q", i, effect)
		}

		var pType int
		var pName string
		if principal == "*" {
			pType = 0
		} else if strings.HasPrefix(principal, "user:") {
			pName = principal[5:]
			if !isName(pName) {
				return nil, fmt.Errorf("rule %d: bad principal %q", i, principal)
			}
			pType = 2
		} else if strings.HasPrefix(principal, "group:") {
			pName = principal[6:]
			if !isName(pName) {
				return nil, fmt.Errorf("rule %d: bad principal %q", i, principal)
			}
			pType = 1
		} else {
			return nil, fmt.Errorf("rule %d: bad principal %q", i, principal)
		}

		var actionAny bool
		var actionMap map[string]bool
		var specA int
		if action == "*" {
			actionAny = true
			specA = 0
		} else {
			parts := strings.Split(action, ",")
			actionMap = make(map[string]bool, len(parts))
			for _, part := range parts {
				if !isActionWord(part) {
					return nil, fmt.Errorf("rule %d: bad action %q", i, action)
				}
				actionMap[part] = true
			}
			specA = 1
		}

		segs, specL, ok := parseResource(resource, true)
		if !ok {
			return nil, fmt.Errorf("rule %d: bad resource %q", i, resource)
		}

		parsedRules[i] = parsedRule{
			index:         i,
			isDeny:        isDeny,
			principalType: pType,
			principalName: pName,
			actionAny:     actionAny,
			actions:       actionMap,
			segments:      segs,
			specificityL:  specL,
			specificityP:  pType,
			specificityA:  specA,
		}
	}

	type parsedRequest struct {
		user     string
		groups   map[string]bool
		action   string
		segments []string
	}
	parsedRequests := make([]parsedRequest, len(requests))

	for j, req := range requests {
		if !isName(req.F0) {
			return nil, fmt.Errorf("request %d: bad user %q", j, req.F0)
		}
		if req.F1 == nil {
			// In Go, nil slice might be passed as empty list or invalid,
			// but usually empty slice is valid. Still, check elements.
		}
		gMap := make(map[string]bool, len(req.F1))
		for _, g := range req.F1 {
			if !isName(g) {
				return nil, fmt.Errorf("request %d: bad groups", j)
			}
			gMap[g] = true
		}
		if !isActionWord(req.F2) {
			return nil, fmt.Errorf("request %d: bad action %q", j, req.F2)
		}
		segs, _, ok := parseResource(req.F3, false)
		if !ok {
			return nil, fmt.Errorf("request %d: bad path %q", j, req.F3)
		}
		parsedRequests[j] = parsedRequest{
			user:     req.F0,
			groups:   gMap,
			action:   req.F2,
			segments: segs,
		}
	}

	results := make([]string, len(requests))
	for j, req := range parsedRequests {
		bestL, bestP, bestA := -1, -1, -1
		bestDenyIdx := -1
		bestAllowIdx := -1

		for i := range parsedRules {
			rule := &parsedRules[i]

			// Match principal
			if rule.principalType == 2 {
				if rule.principalName != req.user {
					continue
				}
			} else if rule.principalType == 1 {
				if !req.groups[rule.principalName] {
					continue
				}
			}

			// Match action
			if !rule.actionAny {
				if !rule.actions[req.action] {
					continue
				}
			}

			// Match resource
			if !matchSegments(rule.segments, req.segments) {
				continue
			}

			// Check specificity
			greater := false
			equal := false
			if rule.specificityL != bestL {
				greater = rule.specificityL > bestL
			} else if rule.specificityP != bestP {
				greater = rule.specificityP > bestP
			} else if rule.specificityA != bestA {
				greater = rule.specificityA > bestA
			} else {
				equal = true
			}

			if greater {
				bestL = rule.specificityL
				bestP = rule.specificityP
				bestA = rule.specificityA
				if rule.isDeny {
					bestDenyIdx = rule.index
					bestAllowIdx = -1
				} else {
					bestAllowIdx = rule.index
					bestDenyIdx = -1
				}
			} else if equal {
				if rule.isDeny {
					if bestDenyIdx == -1 {
						bestDenyIdx = rule.index
					}
				} else {
					if bestAllowIdx == -1 {
						bestAllowIdx = rule.index
					}
				}
			}
		}

		if bestL == -1 {
			results[j] = "DENY by default"
		} else if bestDenyIdx != -1 {
			results[j] = fmt.Sprintf("DENY by rule %d", bestDenyIdx)
		} else {
			results[j] = fmt.Sprintf("ALLOW by rule %d", bestAllowIdx)
		}
	}

	return results, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, List<String> f1, String f2, String f3) {}

    private static final class ParsedRule {
        final int index;
        final boolean isDeny;
        final int pType; // 0: *, 1: group, 2: user
        final String pName;
        final boolean anyAction;
        final Set<String> actions;
        final String[] resourceSegments;
        final int specificity; // packed (L << 3) | (P << 1) | A

        ParsedRule(int index, boolean isDeny, int pType, String pName,
                   boolean anyAction, Set<String> actions, String[] resourceSegments, int lCount) {
            this.index = index;
            this.isDeny = isDeny;
            this.pType = pType;
            this.pName = pName;
            this.anyAction = anyAction;
            this.actions = actions;
            this.resourceSegments = resourceSegments;
            int aSpec = anyAction ? 0 : 1;
            this.specificity = (lCount << 3) | (pType << 1) | aSpec;
        }
    }

    private static final class ParsedRequest {
        final String user;
        final Set<String> groups;
        final String action;
        final String[] pathSegments;

        ParsedRequest(String user, Set<String> groups, String action, String[] pathSegments) {
            this.user = user;
            this.groups = groups;
            this.action = action;
            this.pathSegments = pathSegments;
        }
    }

    public static List<String> evaluateAccess(List<String> rules, List<Tuple1> requests) {
        if (rules == null) {
            throw new IllegalArgumentException("rules must be a list");
        }
        if (requests == null) {
            throw new IllegalArgumentException("requests must be a list");
        }

        List<ParsedRule> parsedRules = new ArrayList<>(rules.size());
        for (int i = 0; i < rules.size(); i++) {
            String ruleStr = rules.get(i);
            if (ruleStr == null) {
                throw new IllegalArgumentException("rule " + i + ": not a str");
            }
            List<String> fields = splitWhitespace(ruleStr);
            if (fields.size() != 4) {
                throw new IllegalArgumentException("rule " + i + ": expected 4 fields, got " + fields.size());
            }

            String effect = fields.get(0);
            String principal = fields.get(1);
            String action = fields.get(2);
            String resource = fields.get(3);

            // Validate EFFECT
            boolean isDeny;
            if ("ALLOW".equals(effect)) {
                isDeny = false;
            } else if ("DENY".equals(effect)) {
                isDeny = true;
            } else {
                throw new IllegalArgumentException("rule " + i + ": bad effect '" + effect + "'");
            }

            // Validate PRINCIPAL
            int pType;
            String pName = null;
            if ("*".equals(principal)) {
                pType = 0;
            } else if (principal.startsWith("user:")) {
                pType = 2;
                pName = principal.substring(5);
                if (!isValidName(pName)) {
                    throw new IllegalArgumentException("rule " + i + ": bad principal '" + principal + "'");
                }
            } else if (principal.startsWith("group:")) {
                pType = 1;
                pName = principal.substring(6);
                if (!isValidName(pName)) {
                    throw new IllegalArgumentException("rule " + i + ": bad principal '" + principal + "'");
                }
            } else {
                throw new IllegalArgumentException("rule " + i + ": bad principal '" + principal + "'");
            }

            // Validate ACTION
            boolean anyAction = false;
            Set<String> actions = null;
            if ("*".equals(action)) {
                anyAction = true;
            } else {
                String[] parts = action.split(",", -1);
                if (parts.length == 0) {
                    throw new IllegalArgumentException("rule " + i + ": bad action '" + action + "'");
                }
                actions = new HashSet<>(parts.length * 2);
                for (String part : parts) {
                    if (!isValidActionWord(part)) {
                        throw new IllegalArgumentException("rule " + i + ": bad action '" + action + "'");
                    }
                    actions.add(part);
                }
            }

            // Validate RESOURCE
            String[] resSegments = parsePathOrResource(resource, true);
            if (resSegments == null) {
                throw new IllegalArgumentException("rule " + i + ": bad resource '" + resource + "'");
            }
            int lCount = 0;
            for (String seg : resSegments) {
                if (!"*".equals(seg) && !"**".equals(seg)) {
                    lCount++;
                }
            }

            parsedRules.add(new ParsedRule(i, isDeny, pType, pName, anyAction, actions, resSegments, lCount));
        }

        List<ParsedRequest> parsedRequests = new ArrayList<>(requests.size());
        for (int j = 0; j < requests.size(); j++) {
            Tuple1 req = requests.get(j);
            if (req == null) {
                throw new IllegalArgumentException("request " + j + ": expected 4-tuple");
            }
            String user = req.f0();
            List<String> groups = req.f1();
            String action = req.f2();
            String path = req.f3();

            if (!isValidName(user)) {
                throw new IllegalArgumentException("request " + j + ": bad user " + repr(user));
            }
            if (groups == null) {
                throw new IllegalArgumentException("request " + j + ": bad groups");
            }
            Set<String> groupSet = new HashSet<>(groups.size() * 2);
            for (String g : groups) {
                if (!isValidName(g)) {
                    throw new IllegalArgumentException("request " + j + ": bad groups");
                }
                groupSet.add(g);
            }
            if (!isValidActionWord(action)) {
                throw new IllegalArgumentException("request " + j + ": bad action " + repr(action));
            }
            String[] pathSegments = parsePathOrResource(path, false);
            if (pathSegments == null) {
                throw new IllegalArgumentException("request " + j + ": bad path " + repr(path));
            }

            parsedRequests.add(new ParsedRequest(user, groupSet, action, pathSegments));
        }

        List<String> decisions = new ArrayList<>(parsedRequests.size());
        for (ParsedRequest req : parsedRequests) {
            int maxSpec = -1;
            int bestAllowIdx = -1;
            int bestDenyIdx = -1;

            for (ParsedRule rule : parsedRules) {
                if (rule.specificity < maxSpec) {
                    continue;
                }
                if (!matchesPrincipal(rule, req) || !matchesAction(rule, req)) {
                    continue;
                }
                if (!matchesResource(rule.resourceSegments, req.pathSegments)) {
                    continue;
                }

                if (rule.specificity > maxSpec) {
                    maxSpec = rule.specificity;
                    if (rule.isDeny) {
                        bestDenyIdx = rule.index;
                        bestAllowIdx = -1;
                    } else {
                        bestAllowIdx = rule.index;
                        bestDenyIdx = -1;
                    }
                } else {
                    if (rule.isDeny) {
                        if (bestDenyIdx == -1) {
                            bestDenyIdx = rule.index;
                        }
                    } else {
                        if (bestAllowIdx == -1) {
                            bestAllowIdx = rule.index;
                        }
                    }
                }
            }

            if (maxSpec == -1) {
                decisions.add("DENY by default");
            } else if (bestDenyIdx != -1) {
                decisions.add("DENY by rule " + bestDenyIdx);
            } else {
                decisions.add("ALLOW by rule " + bestAllowIdx);
            }
        }

        return decisions;
    }

    private static boolean matchesPrincipal(ParsedRule rule, ParsedRequest req) {
        return switch (rule.pType) {
            case 0 -> true;
            case 2 -> rule.pName.equals(req.user);
            case 1 -> req.groups.contains(rule.pName);
            default -> false;
        };
    }

    private static boolean matchesAction(ParsedRule rule, ParsedRequest req) {
        return rule.anyAction || rule.actions.contains(req.action);
    }

    private static boolean matchesResource(String[] res, String[] path) {
        int m = res.length;
        int n = path.length;
        boolean[] dp = new boolean[n + 1];
        dp[0] = true;

        for (int i = 0; i < m; i++) {
            String r = res[i];
            if ("**".equals(r)) {
                for (int j = 1; j <= n; j++) {
                    if (dp[j - 1]) {
                        dp[j] = true;
                    }
                }
            } else if ("*".equals(r)) {
                for (int j = n; j >= 1; j--) {
                    dp[j] = dp[j - 1];
                }
                dp[0] = false;
            } else {
                for (int j = n; j >= 1; j--) {
                    dp[j] = dp[j - 1] && r.equals(path[j - 1]);
                }
                dp[0] = false;
            }
        }
        return dp[n];
    }

    private static boolean isPythonWhitespace(char c) {
        return switch (c) {
            case '\t', '\n', '\u000B', '\f', '\r', '\u001C', '\u001D', '\u001E', '\u001F',
                 ' ', '\u0085', '\u00A0', '\u1680', '\u2000', '\u2001', '\u2002', '\u2003',
                 '\u2004', '\u2005', '\u2006', '\u2007', '\u2008', '\u2009', '\u200A',
                 '\u2028', '\u2029', '\u202F', '\u205F', '\u3000' -> true;
            default -> false;
        };
    }

    private static List<String> splitWhitespace(String s) {
        List<String> res = new ArrayList<>();
        int n = s.length();
        int i = 0;
        while (i < n) {
            while (i < n && isPythonWhitespace(s.charAt(i))) {
                i++;
            }
            if (i >= n) break;
            int start = i;
            while (i < n && !isPythonWhitespace(s.charAt(i))) {
                i++;
            }
            res.add(s.substring(start, i));
        }
        return res;
    }

    private static boolean isValidName(String s) {
        if (s == null || s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) {
                return false;
            }
        }
        return true;
    }

    private static boolean isValidActionWord(String s) {
        if (s == null || s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!(c >= 'a' && c <= 'z')) {
                return false;
            }
        }
        return true;
    }

    private static boolean isValidSegmentChars(String s) {
        if (s == null || s.isEmpty()) return false;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-')) {
                return false;
            }
        }
        return true;
    }

    private static String[] parsePathOrResource(String s, boolean allowWildcards) {
        if (s == null || !s.startsWith("/")) {
            return null;
        }
        if ("/".equals(s)) {
            return new String[0];
        }
        String[] parts = s.substring(1).split("/", -1);
        for (String p : parts) {
            if (p.isEmpty()) {
                return null;
            }
            if (allowWildcards && ("*".equals(p) || "**".equals(p))) {
                continue;
            }
            if (!isValidSegmentChars(p)) {
                return null;
            }
        }
        return parts;
    }

    private static String repr(String s) {
        if (s == null) return "None";
        return "'" + s + "'";
    }
}

#include <algorithm>
#include <cctype>
#include <stdexcept>
#include <string>
#include <tuple>
#include <unordered_set>
#include <vector>

namespace {

bool is_python_whitespace(unsigned char c) {
    // Standard ASCII whitespace + a few others, though input is likely ASCII.
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\v' || c == '\f';
}

std::vector<std::string> split_whitespace(const std::string& s) {
    std::vector<std::string> res;
    size_t i = 0, n = s.size();
    while (i < n) {
        while (i < n && is_python_whitespace(static_cast<unsigned char>(s[i]))) {
            ++i;
        }
        if (i >= n) break;
        size_t j = i;
        while (j < n && !is_python_whitespace(static_cast<unsigned char>(s[j]))) {
            ++j;
        }
        res.push_back(s.substr(i, j - i));
        i = j;
    }
    return res;
}

bool is_valid_name(const std::string& s) {
    if (s.empty()) return false;
    for (unsigned char c : s) {
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_')) {
            return false;
        }
    }
    return true;
}

bool is_valid_action_word(const std::string& s) {
    if (s.empty()) return false;
    for (unsigned char c : s) {
        if (!(c >= 'a' && c <= 'z')) {
            return false;
        }
    }
    return true;
}

bool is_valid_segment_chars(const std::string& s) {
    if (s.empty()) return false;
    for (unsigned char c : s) {
        if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '.' || c == '_' || c == '-')) {
            return false;
        }
    }
    return true;
}

enum class PrincipalType { ANY, USER, GROUP };

struct ParsedRule {
    int index;
    bool is_allow;
    PrincipalType p_type;
    std::string p_name;
    bool action_any;
    std::unordered_set<std::string> actions;
    std::vector<std::string> resource_segments;
    std::tuple<int, int, int> specificity;
};

struct ParsedRequest {
    std::string user;
    std::unordered_set<std::string> groups;
    std::string action;
    std::vector<std::string> path_segments;
};

bool parse_path(const std::string& s, bool allow_wildcards, std::vector<std::string>& segments, int& literal_count) {
    segments.clear();
    literal_count = 0;
    if (s.empty() || s[0] != '/') return false;
    if (s == "/") return true;
    size_t i = 1, n = s.size();
    while (i <= n) {
        size_t next_slash = s.find('/', i);
        std::string seg;
        if (next_slash == std::string::npos) {
            seg = s.substr(i);
            i = n + 1;
        } else {
            seg = s.substr(i, next_slash - i);
            i = next_slash + 1;
        }
        if (seg.empty()) return false;
        if (allow_wildcards && (seg == "*" || seg == "**")) {
            segments.push_back(seg);
        } else if (is_valid_segment_chars(seg)) {
            segments.push_back(seg);
            literal_count++;
        } else {
            return false;
        }
    }
    return true;
}

bool match_resource(const std::vector<std::string>& res, const std::vector<std::string>& path) {
    size_t R = res.size();
    size_t P = path.size();
    std::vector<bool> dp(P + 1, false);
    dp[0] = true;

    for (size_t i = 0; i < R; ++i) {
        const std::string& r = res[i];
        if (r == "**") {
            bool found = false;
            for (size_t j = 0; j <= P; ++j) {
                if (dp[j]) found = true;
                if (found) dp[j] = true;
            }
        } else if (r == "*") {
            for (size_t j = P; j >= 1; --j) {
                dp[j] = dp[j - 1];
            }
            dp[0] = false;
        } else {
            for (size_t j = P; j >= 1; --j) {
                dp[j] = dp[j - 1] && (path[j - 1] == r);
            }
            dp[0] = false;
        }
    }
    return dp[P];
}

} // namespace

std::vector<std::string> evaluate_access(
    const std::vector<std::string>& rules,
    const std::vector<std::tuple<std::string, std::vector<std::string>, std::string, std::string>>& requests) {

    std::vector<ParsedRule> parsed_rules;
    parsed_rules.reserve(rules.size());

    for (size_t i = 0; i < rules.size(); ++i) {
        auto fields = split_whitespace(rules[i]);
        if (fields.size() != 4) {
            throw std::invalid_argument("rule " + std::to_string(i) + ": expected 4 fields, got " + std::to_string(fields.size()));
        }

        ParsedRule pr;
        pr.index = static_cast<int>(i);

        // 1. EFFECT
        const std::string& effect = fields[0];
        if (effect == "ALLOW") {
            pr.is_allow = true;
        } else if (effect == "DENY") {
            pr.is_allow = false;
        } else {
            throw std::invalid_argument("rule " + std::to_string(i) + ": bad effect '" + effect + "'");
        }

        // 2. PRINCIPAL
        const std::string& principal = fields[1];
        int p_spec = 0;
        if (principal == "*") {
            pr.p_type = PrincipalType::ANY;
            p_spec = 0;
        } else if (principal.rfind("user:", 0) == 0) {
            std::string name = principal.substr(5);
            if (!is_valid_name(name)) {
                throw std::invalid_argument("rule " + std::to_string(i) + ": bad principal '" + principal + "'");
            }
            pr.p_type = PrincipalType::USER;
            pr.p_name = name;
            p_spec = 2;
        } else if (principal.rfind("group:", 0) == 0) {
            std::string name = principal.substr(6);
            if (!is_valid_name(name)) {
                throw std::invalid_argument("rule " + std::to_string(i) + ": bad principal '" + principal + "'");
            }
            pr.p_type = PrincipalType::GROUP;
            pr.p_name = name;
            p_spec = 1;
        } else {
            throw std::invalid_argument("rule " + std::to_string(i) + ": bad principal '" + principal + "'");
        }

        // 3. ACTION
        const std::string& action = fields[2];
        int a_spec = 0;
        if (action == "*") {
            pr.action_any = true;
            a_spec = 0;
        } else {
            pr.action_any = false;
            a_spec = 1;
            if (action.empty()) {
                throw std::invalid_argument("rule " + std::to_string(i) + ": bad action '" + action + "'");
            }
            size_t pos = 0, n = action.size();
            while (pos <= n) {
                size_t comma = action.find(',', pos);
                std::string word;
                if (comma == std::string::npos) {
                    word = action.substr(pos);
                    pos = n + 1;
                } else {
                    word = action.substr(pos, comma - pos);
                    pos = comma + 1;
                }
                if (!is_valid_action_word(word)) {
                    throw std::invalid_argument("rule " + std::to_string(i) + ": bad action '" + action + "'");
                }
                pr.actions.insert(word);
            }
        }

        // 4. RESOURCE
        const std::string& resource = fields[3];
        int l_spec = 0;
        if (!parse_path(resource, true, pr.resource_segments, l_spec)) {
            throw std::invalid_argument("rule " + std::to_string(i) + ": bad resource '" + resource + "'");
        }

        pr.specificity = std::make_tuple(l_spec, p_spec, a_spec);
        parsed_rules.push_back(std::move(pr));
    }

    std::vector<ParsedRequest> parsed_requests;
    parsed_requests.reserve(requests.size());

    for (size_t j = 0; j < requests.size(); ++j) {
        const auto& [user, groups, action, path] = requests[j];

        if (!is_valid_name(user)) {
            throw std::invalid_argument("request " + std::to_string(j) + ": bad user '" + user + "'");
        }

        ParsedRequest preq;
        preq.user = user;

        for (const auto& g : groups) {
            if (!is_valid_name(g)) {
                throw std::invalid_argument("request " + std::to_string(j) + ": bad groups");
            }
            preq.groups.insert(g);
        }

        if (!is_valid_action_word(action)) {
            throw std::invalid_argument("request " + std::to_string(j) + ": bad action '" + action + "'");
        }
        preq.action = action;

        int dummy_l = 0;
        if (!parse_path(path, false, preq.path_segments, dummy_l)) {
            throw std::invalid_argument("request " + std::to_string(j) + ": bad path '" + path + "'");
        }

        parsed_requests.push_back(std::move(preq));
    }

    std::vector<std::string> results;
    results.reserve(parsed_requests.size());

    for (const auto& req : parsed_requests) {
        bool has_match = false;
        std::tuple<int, int, int> max_spec = {-1, -1, -1};
        int best_deny_idx = -1;
        int best_allow_idx = -1;

        for (const auto& rule : parsed_rules) {
            // Check principal
            if (rule.p_type == PrincipalType::USER) {
                if (rule.p_name != req.user) continue;
            } else if (rule.p_type == PrincipalType::GROUP) {
                if (req.groups.find(rule.p_name) == req.groups.end()) continue;
            }

            // Check action
            if (!rule.action_any) {
                if (rule.actions.find(req.action) == rule.actions.end()) continue;
            }

            // Check resource
            if (!match_resource(rule.resource_segments, req.path_segments)) continue;

            // Matched!
            if (!has_match || rule.specificity > max_spec) {
                has_match = true;
                max_spec = rule.specificity;
                if (rule.is_allow) {
                    best_allow_idx = rule.index;
                    best_deny_idx = -1;
                } else {
                    best_deny_idx = rule.index;
                    best_allow_idx = -1;
                }
            } else if (rule.specificity == max_spec) {
                if (rule.is_allow) {
                    if (best_allow_idx == -1) best_allow_idx = rule.index;
                } else {
                    if (best_deny_idx == -1) best_deny_idx = rule.index;
                }
            }
        }

        if (!has_match) {
            results.push_back("DENY by default");
        } else if (best_deny_idx != -1) {
            results.push_back("DENY by rule " + std::to_string(best_deny_idx));
        } else {
            results.push_back("ALLOW by rule " + std::to_string(best_allow_idx));
        }
    }

    return results;
}

const NAME_RE = /^[a-z0-9_]+$/;
const ACTION_WORD_RE = /^[a-z]+$/;
const SEGMENT_RE = /^[a-z0-9._-]+$/;

// Python str.split() with no arguments splits on ASCII and Unicode whitespace.
// Standard whitespace regex \s+ covers common ASCII whitespace (\t\n\x0b\x0c\r ) and Unicode spaces.
function pySplit(s: string): string[] {
  const trimmed = s.trim();
  if (trimmed.length === 0) return [];
  return trimmed.split(/\s+/);
}

function pyRepr(val: unknown): string {
  if (typeof val === "string") {
    return `'${val.replace(/\\/g, "\\\\").replace(/'/g, "\\'")}'`;
  }
  if (val === null) return "None";
  if (typeof val === "boolean") return val ? "True" : "False";
  return String(val);
}

interface ParsedRule {
  index: number;
  isDeny: boolean;
  principalType: 0 | 1 | 2; // 0: *, 1: group, 2: user
  principalName: string;
  actions: Set<string> | null; // null means *
  segments: string[];
  specificity: number; // Encoded (L, P, A) for fast comparison
}

interface ParsedRequest {
  user: string;
  groups: Set<string>;
  action: string;
  segments: string[];
}

function matchSegments(pattern: string[], path: string[]): boolean {
  const m = pattern.length;
  const n = path.length;

  // dp[j] = can pattern[0..i) match path[0..j)
  let dp = new Uint8Array(n + 1);
  dp[0] = 1;

  for (let i = 0; i < m; i++) {
    const p = pattern[i];
    const nextDp = new Uint8Array(n + 1);
    if (p === "**") {
      let seen = 0;
      for (let j = 0; j <= n; j++) {
        if (dp[j]) seen = 1;
        nextDp[j] = seen;
      }
    } else if (p === "*") {
      for (let j = 0; j < n; j++) {
        nextDp[j + 1] = dp[j];
      }
    } else {
      for (let j = 0; j < n; j++) {
        if (dp[j] && path[j] === p) {
          nextDp[j + 1] = 1;
        }
      }
    }
    dp = nextDp;
  }

  return dp[n] === 1;
}

export function evaluateAccess(
  rules: string[],
  requests: [string, string[], string, string][]
): string[] {
  if (!Array.isArray(rules)) {
    throw new TypeError("rules must be a list");
  }
  if (!Array.isArray(requests)) {
    throw new TypeError("requests must be a list");
  }

  const parsedRules: ParsedRule[] = [];

  for (let i = 0; i < rules.length; i++) {
    const r = rules[i] as unknown;
    if (typeof r !== "string") {
      throw new TypeError(`rule ${i}: not a str`);
    }
    const fields = pySplit(r);
    if (fields.length !== 4) {
      throw new Error(`rule ${i}: expected 4 fields, got ${fields.length}`);
    }
    const [effect, principal, action, resource] = fields;

    // Validate EFFECT
    if (effect !== "ALLOW" && effect !== "DENY") {
      throw new Error(`rule ${i}: bad effect ${pyRepr(effect)}`);
    }

    // Validate PRINCIPAL
    let principalType: 0 | 1 | 2 = 0;
    let principalName = "";
    if (principal === "*") {
      principalType = 0;
    } else if (principal.startsWith("user:")) {
      principalName = principal.slice(5);
      if (!NAME_RE.test(principalName)) {
        throw new Error(`rule ${i}: bad principal ${pyRepr(principal)}`);
      }
      principalType = 2;
    } else if (principal.startsWith("group:")) {
      principalName = principal.slice(6);
      if (!NAME_RE.test(principalName)) {
        throw new Error(`rule ${i}: bad principal ${pyRepr(principal)}`);
      }
      principalType = 1;
    } else {
      throw new Error(`rule ${i}: bad principal ${pyRepr(principal)}`);
    }

    // Validate ACTION
    let actions: Set<string> | null = null;
    if (action !== "*") {
      const parts = action.split(",");
      if (parts.length === 0) {
        throw new Error(`rule ${i}: bad action ${pyRepr(action)}`);
      }
      actions = new Set<string>();
      for (const part of parts) {
        if (!ACTION_WORD_RE.test(part)) {
          throw new Error(`rule ${i}: bad action ${pyRepr(action)}`);
        }
        actions.add(part);
      }
    }

    // Validate RESOURCE
    let segments: string[] = [];
    let literalCount = 0;
    if (resource === "/") {
      segments = [];
    } else if (resource.startsWith("/")) {
      const rawSegs = resource.slice(1).split("/");
      for (const seg of rawSegs) {
        if (seg === "*" || seg === "**") {
          continue;
        }
        if (!SEGMENT_RE.test(seg)) {
          throw new Error(`rule ${i}: bad resource ${pyRepr(resource)}`);
        }
        literalCount++;
      }
      segments = rawSegs;
    } else {
      throw new Error(`rule ${i}: bad resource ${pyRepr(resource)}`);
    }

    const A = actions === null ? 0 : 1;
    // Encode (L, P, A) into a single number: L * 6 + P * 2 + A
    const specificity = literalCount * 6 + principalType * 2 + A;

    parsedRules.push({
      index: i,
      isDeny: effect === "DENY",
      principalType,
      principalName,
      actions,
      segments,
      specificity,
    });
  }

  const parsedRequests: ParsedRequest[] = [];

  for (let j = 0; j < requests.length; j++) {
    const req = requests[j] as unknown;
    if (!Array.isArray(req) || req.length !== 4) {
      throw new TypeError(`request ${j}: expected 4-tuple`);
    }
    const [user, groups, action, path] = req as [unknown, unknown, unknown, unknown];

    if (typeof user !== "string" || !NAME_RE.test(user)) {
      throw new Error(`request ${j}: bad user ${pyRepr(user)}`);
    }

    if (!Array.isArray(groups)) {
      throw new Error(`request ${j}: bad groups`);
    }
    const groupSet = new Set<string>();
    for (const g of groups) {
      if (typeof g !== "string" || !NAME_RE.test(g)) {
        throw new Error(`request ${j}: bad groups`);
      }
      groupSet.add(g);
    }

    if (typeof action !== "string" || !ACTION_WORD_RE.test(action)) {
      throw new Error(`request ${j}: bad action ${pyRepr(action)}`);
    }

    let pathSegments: string[] = [];
    if (typeof path !== "string" || !path.startsWith("/")) {
      throw new Error(`request ${j}: bad path ${pyRepr(path)}`);
    }
    if (path === "/") {
      pathSegments = [];
    } else {
      const rawSegs = path.slice(1).split("/");
      for (const seg of rawSegs) {
        if (!SEGMENT_RE.test(seg)) {
          throw new Error(`request ${j}: bad path ${pyRepr(path)}`);
        }
      }
      pathSegments = rawSegs;
    }

    parsedRequests.push({
      user,
      groups: groupSet,
      action,
      segments: pathSegments,
    });
  }

  const results: string[] = [];

  for (let j = 0; j < parsedRequests.length; j++) {
    const req = parsedRequests[j];
    let bestSpec = -1;
    let bestDenyIndex = -1;
    let bestAllowIndex = -1;

    for (let i = 0; i < parsedRules.length; i++) {
      const rule = parsedRules[i];

      // If this rule's specificity is strictly worse than what we already found, skip
      if (rule.specificity < bestSpec) {
        continue;
      }

      // Check principal
      if (rule.principalType === 2) {
        if (rule.principalName !== req.user) continue;
      } else if (rule.principalType === 1) {
        if (!req.groups.has(rule.principalName)) continue;
      }

      // Check action
      if (rule.actions !== null && !rule.actions.has(req.action)) {
        continue;
      }

      // Check resource path
      if (!matchSegments(rule.segments, req.segments)) {
        continue;
      }

      // Rule matches!
      if (rule.specificity > bestSpec) {
        bestSpec = rule.specificity;
        if (rule.isDeny) {
          bestDenyIndex = rule.index;
          bestAllowIndex = -1;
        } else {
          bestDenyIndex = -1;
          bestAllowIndex = rule.index;
        }
      } else {
        // rule.specificity === bestSpec
        if (rule.isDeny) {
          if (bestDenyIndex === -1) {
            bestDenyIndex = rule.index;
          }
        } else {
          if (bestAllowIndex === -1) {
            bestAllowIndex = rule.index;
          }
        }
      }
    }

    if (bestSpec === -1) {
      results.push("DENY by default");
    } else if (bestDenyIndex !== -1) {
      results.push(`DENY by rule ${bestDenyIndex}`);
    } else {
      results.push(`ALLOW by rule ${bestAllowIndex}`);
    }
  }

  return results;
}

package main

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"
	"unicode"
	"unicode/utf8"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
	F3 string
}

var (
	openingRe = regexp.MustCompile(`^-?(0|[1-9][0-9]{0,8})\.[0-9]{2}$`)
	dateRe    = regexp.MustCompile(`^[0-9]{4}-[0-9]{2}-[0-9]{2}$`)
	amountRe  = regexp.MustCompile(`^(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?$`)
)

func parseCents(s string) int64 {
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	parts := strings.Split(s, ".")
	intPart, _ := strconv.ParseInt(parts[0], 10, 64)
	fracPart := int64(0)
	if len(parts) > 1 {
		f := parts[1]
		if len(f) == 1 {
			f += "0"
		}
		fracPart, _ = strconv.ParseInt(f, 10, 64)
	}
	total := intPart*100 + fracPart
	if neg {
		return -total
	}
	return total
}

func formatMoney(cents int64) string {
	if cents == 0 {
		return "0.00"
	}
	neg := false
	if cents < 0 {
		neg = true
		cents = -cents
	}
	dollars := cents / 100
	rem := cents % 100

	dStr := strconv.FormatInt(dollars, 10)
	var chunks []string
	for len(dStr) > 3 {
		chunks = append(chunks, dStr[len(dStr)-3:])
		dStr = dStr[:len(dStr)-3]
	}
	chunks = append(chunks, dStr)

	var sb strings.Builder
	if neg {
		sb.WriteByte('-')
	}
	for i := len(chunks) - 1; i >= 0; i-- {
		sb.WriteString(chunks[i])
		if i > 0 {
			sb.WriteByte(',')
		}
	}
	fmt.Fprintf(&sb, ".%02d", rem)
	return sb.String()
}

func isValidDate(d string) bool {
	if !dateRe.MatchString(d) {
		return false
	}
	year, err := strconv.Atoi(d[0:4])
	if err != nil || year < 1900 || year > 2999 {
		return false
	}
	t, err := time.Parse("2006-01-02", d)
	if err != nil {
		return false
	}
	return t.Format("2006-01-02") == d
}

func isPythonSpace(r rune) bool {
	if r >= 0x1C && r <= 0x1F {
		return true
	}
	return unicode.IsSpace(r)
}

func splitWhitespace(s string) []string {
	return strings.FieldsFunc(s, isPythonSpace)
}

func isValidMemo(m string) bool {
	for _, r := range m {
		if r < 32 || r == 127 {
			return false
		}
	}
	words := splitWhitespace(m)
	return len(words) > 0
}

func formatMemo(m string) string {
	norm := strings.Join(splitWhitespace(m), " ")
	runes := []rune(norm)
	if len(runes) > 20 {
		norm = string(runes[:19]) + "~"
		runes = []rune(norm)
	}
	pad := 20 - len(runes)
	if pad > 0 {
		norm += strings.Repeat(" ", pad)
	}
	return norm
}

func rjust(s string, width int) string {
	n := utf8.RuneCountInString(s)
	if n >= width {
		return s
	}
	return strings.Repeat(" ", width-n) + s
}

func RenderStatement(opening string, entries []Tuple1) ([]string, error) {
	if !openingRe.MatchString(opening) {
		return nil, fmt.Errorf("opening: bad amount %q", opening)
	}

	type parsedEntry struct {
		date   string
		kind   string
		amount int64
		memo   string
	}

	var parsed []parsedEntry
	var prevDate string

	for i, e := range entries {
		date, kind, amountStr, memo := e.F0, e.F1, e.F2, e.F3

		if !isValidDate(date) {
			return nil, fmt.Errorf("entry %d: bad date %q", i, date)
		}
		if i > 0 && date < prevDate {
			return nil, fmt.Errorf("entry %d: date out of order", i)
		}
		prevDate = date

		if kind != "credit" && kind != "debit" && kind != "fee" {
			return nil, fmt.Errorf("entry %d: bad kind %q", i, kind)
		}

		if !amountRe.MatchString(amountStr) {
			return nil, fmt.Errorf("entry %d: bad amount %q", i, amountStr)
		}
		amtCents := parseCents(amountStr)
		if amtCents == 0 {
			return nil, fmt.Errorf("entry %d: bad amount %q", i, amountStr)
		}

		if !isValidMemo(memo) {
			return nil, fmt.Errorf("entry %d: bad memo", i)
		}

		parsed = append(parsed, parsedEntry{
			date:   date,
			kind:   kind,
			amount: amtCents,
			memo:   memo,
		})
	}

	balance := parseCents(opening)
	lines := []string{
		"Opening balance: " + formatMoney(balance),
	}

	odFeeDates := make(map[string]bool)
	var credits, debits, fees int

	applyAndRender := func(date, kind string, amount int64, memo string) {
		sign := "-"
		switch kind {
		case "credit":
			balance += amount
			sign = "+"
			credits++
		case "debit":
			balance -= amount
			debits++
		case "fee":
			balance -= amount
			fees++
		}

		memoFormatted := formatMemo(memo)
		amtFormatted := rjust(sign+formatMoney(amount), 14)
		balFormatted := rjust(formatMoney(balance), 15)
		flag := ""
		if balance < 0 {
			flag = " OD"
		}

		line := fmt.Sprintf("%s  %s  %s  %s%s", date, memoFormatted, amtFormatted, balFormatted, flag)
		lines = append(lines, line)
	}

	for _, e := range parsed {
		applyAndRender(e.date, e.kind, e.amount, e.memo)
		if e.kind == "debit" && balance < 0 && !odFeeDates[e.date] {
			odFeeDates[e.date] = true
			applyAndRender(e.date, "fee", 2500, "OVERDRAFT FEE")
		}
	}

	lines = append(lines, "Closing balance: "+formatMoney(balance))
	lines = append(lines, fmt.Sprintf("Credits: %d  Debits: %d  Fees: %d", credits, debits, fees))

	return lines, nil
}

import java.util.*;
import java.util.regex.Pattern;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2, String f3) {}

    private static final Pattern OPENING_PATTERN = Pattern.compile("-?(0|[1-9][0-9]{0,8})\\.[0-9]{2}");
    private static final Pattern DATE_PATTERN = Pattern.compile("[0-9]{4}-[0-9]{2}-[0-9]{2}");
    private static final Pattern AMOUNT_PATTERN = Pattern.compile("(0|[1-9][0-9]{0,8})(\\.[0-9]{1,2})?");

    private record ValidEntry(String date, String kind, long amountCents, String memo) {}

    public static List<String> renderStatement(String opening, List<Tuple1> entries) {
        if (opening == null) {
            throw new IllegalArgumentException("opening must be a str");
        }
        if (!OPENING_PATTERN.matcher(opening).matches()) {
            throw new IllegalArgumentException("opening: bad amount '" + opening + "'");
        }
        if (entries == null) {
            throw new IllegalArgumentException("entries must be a list");
        }

        long openingCents = parseOpeningCents(opening);
        List<ValidEntry> validEntries = new ArrayList<>(entries.size());
        String prevDate = null;

        for (int i = 0; i < entries.size(); i++) {
            Tuple1 e = entries.get(i);
            if (e == null) {
                throw new IllegalArgumentException("entry " + i + ": expected 4-tuple");
            }
            String date = e.f0();
            String kind = e.f1();
            String amount = e.f2();
            String memo = e.f3();

            if (!isValidDate(date)) {
                throw new IllegalArgumentException("entry " + i + ": bad date '" + date + "'");
            }
            if (prevDate != null && date.compareTo(prevDate) < 0) {
                throw new IllegalArgumentException("entry " + i + ": date out of order");
            }
            prevDate = date;

            if (kind == null || (!kind.equals("credit") && !kind.equals("debit") && !kind.equals("fee"))) {
                throw new IllegalArgumentException("entry " + i + ": bad kind '" + kind + "'");
            }

            if (amount == null || !AMOUNT_PATTERN.matcher(amount).matches()) {
                throw new IllegalArgumentException("entry " + i + ": bad amount '" + amount + "'");
            }
            long amountCents = parseAmountCents(amount);
            if (amountCents == 0) {
                throw new IllegalArgumentException("entry " + i + ": bad amount '" + amount + "'");
            }

            String normalizedMemo = validateAndNormalizeMemo(memo);
            if (normalizedMemo == null) {
                throw new IllegalArgumentException("entry " + i + ": bad memo");
            }

            validEntries.add(new ValidEntry(date, kind, amountCents, normalizedMemo));
        }

        List<String> result = new ArrayList<>();
        result.add("Opening balance: " + formatMoney(openingCents));

        long balance = openingCents;
        Set<String> overdraftDates = new HashSet<>();
        long creditsCount = 0;
        long debitsCount = 0;
        long feesCount = 0;

        for (ValidEntry ve : validEntries) {
            if (ve.kind().equals("credit")) {
                balance += ve.amountCents();
                creditsCount++;
            } else if (ve.kind().equals("debit")) {
                balance -= ve.amountCents();
                debitsCount++;
            } else {
                balance -= ve.amountCents();
                feesCount++;
            }
            result.add(formatLine(ve.date(), ve.memo(), ve.kind(), ve.amountCents(), balance));

            if (ve.kind().equals("debit") && balance < 0 && !overdraftDates.contains(ve.date())) {
                overdraftDates.add(ve.date());
                long feeCents = 2500L;
                balance -= feeCents;
                feesCount++;
                result.add(formatLine(ve.date(), "OVERDRAFT FEE", "fee", feeCents, balance));
            }
        }

        result.add("Closing balance: " + formatMoney(balance));
        result.add("Credits: " + creditsCount + "  Debits: " + debitsCount + "  Fees: " + feesCount);

        return result;
    }

    private static boolean isValidDate(String date) {
        if (date == null || !DATE_PATTERN.matcher(date).matches()) {
            return false;
        }
        int year = Integer.parseInt(date.substring(0, 4));
        int month = Integer.parseInt(date.substring(5, 7));
        int day = Integer.parseInt(date.substring(8, 10));

        if (year < 1900 || year > 2999) return false;
        if (month < 1 || month > 12) return false;

        int[] daysInMonths = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (isLeapYear(year)) {
            daysInMonths[2] = 29;
        }
        return day >= 1 && day <= daysInMonths[month];
    }

    private static boolean isLeapYear(int year) {
        return (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0);
    }

    private static long parseOpeningCents(String s) {
        boolean neg = s.startsWith("-");
        String abs = neg ? s.substring(1) : s;
        String[] parts = abs.split("\\.");
        long dollars = Long.parseLong(parts[0]);
        long cents = Long.parseLong(parts[1]);
        long total = dollars * 100L + cents;
        return neg ? -total : total;
    }

    private static long parseAmountCents(String s) {
        int dotIndex = s.indexOf('.');
        if (dotIndex == -1) {
            return Long.parseLong(s) * 100L;
        }
        long dollars = Long.parseLong(s.substring(0, dotIndex));
        String frac = s.substring(dotIndex + 1);
        long cents = Long.parseLong(frac);
        if (frac.length() == 1) {
            cents *= 10L;
        }
        return dollars * 100L + cents;
    }

    private static boolean isPythonWhitespace(int cp) {
        if (cp >= 0x0009 && cp <= 0x000D) return true;
        if (cp >= 0x001C && cp <= 0x0020) return true;
        if (cp == 0x0085 || cp == 0x00A0 || cp == 0x1680) return true;
        if (cp >= 0x2000 && cp <= 0x200A) return true;
        if (cp == 0x2028 || cp == 0x2029 || cp == 0x202F || cp == 0x205F || cp == 0x3000) return true;
        return Character.isWhitespace(cp);
    }

    private static String validateAndNormalizeMemo(String memo) {
        if (memo == null) return null;
        int len = memo.length();
        for (int i = 0; i < len; ) {
            int cp = memo.codePointAt(i);
            if (cp < 32 || cp == 127) {
                return null;
            }
            i += Character.charCount(cp);
        }

        List<String> words = new ArrayList<>();
        StringBuilder currentWord = new StringBuilder();
        for (int i = 0; i < len; ) {
            int cp = memo.codePointAt(i);
            if (isPythonWhitespace(cp)) {
                if (currentWord.length() > 0) {
                    words.add(currentWord.toString());
                    currentWord.setLength(0);
                }
            } else {
                currentWord.appendCodePoint(cp);
            }
            i += Character.charCount(cp);
        }
        if (currentWord.length() > 0) {
            words.add(currentWord.toString());
        }

        if (words.isEmpty()) {
            return null;
        }
        return String.join(" ", words);
    }

    private static String formatMoney(long cents) {
        boolean neg = cents < 0;
        long absCents = Math.abs(cents);
        long dollars = absCents / 100;
        long remCents = absCents % 100;
        return String.format(Locale.US, "%s%,d.%02d", neg ? "-" : "", dollars, remCents);
    }

    private static String formatMemoColumn(String normalizedMemo) {
        int cpCount = normalizedMemo.codePointCount(0, normalizedMemo.length());
        String truncated;
        int finalCpCount;
        if (cpCount > 20) {
            int endIdx = normalizedMemo.offsetByCodePoints(0, 19);
            truncated = normalizedMemo.substring(0, endIdx) + "~";
            finalCpCount = 20;
        } else {
            truncated = normalizedMemo;
            finalCpCount = cpCount;
        }
        StringBuilder sb = new StringBuilder(truncated);
        for (int i = finalCpCount; i < 20; i++) {
            sb.append(' ');
        }
        return sb.toString();
    }

    private static String leftPad(String s, int width) {
        int cpCount = s.codePointCount(0, s.length());
        if (cpCount >= width) return s;
        StringBuilder sb = new StringBuilder();
        for (int i = cpCount; i < width; i++) {
            sb.append(' ');
        }
        sb.append(s);
        return sb.toString();
    }

    private static String formatLine(String date, String normalizedMemo, String kind, long amountCents, long balanceCents) {
        String memoCol = formatMemoColumn(normalizedMemo);
        String sign = kind.equals("credit") ? "+" : "-";
        String amtStr = sign + formatMoney(amountCents);
        String amtCol = leftPad(amtStr, 14);
        String balStr = formatMoney(balanceCents);
        String balCol = leftPad(balStr, 15);
        String flag = balanceCents < 0 ? " OD" : "";

        return date + "  " + memoCol + "  " + amtCol + "  " + balCol + flag;
    }
}

#include <iostream>
#include <vector>
#include <string>
#include <tuple>
#include <stdexcept>
#include <cctype>
#include <set>
#include <algorithm>

namespace {

bool is_digit(char c) {
    return c >= '0' && c <= '9';
}

bool parse_opening(const std::string& s, long long& cents) {
    if (s.empty()) return false;
    size_t idx = 0;
    bool neg = false;
    if (s[idx] == '-') {
        neg = true;
        idx++;
    }
    auto dot = s.find('.', idx);
    if (dot == std::string::npos) return false;
    if (s.size() - dot - 1 != 2) return false;
    if (!is_digit(s[dot + 1]) || !is_digit(s[dot + 2])) return false;

    std::string int_part = s.substr(idx, dot - idx);
    if (int_part.empty() || int_part.size() > 9) return false;
    if (int_part.size() > 1 && int_part[0] == '0') return false;
    for (char c : int_part) {
        if (!is_digit(c)) return false;
    }

    long long ip = std::stoll(int_part);
    long long fp = (s[dot + 1] - '0') * 10 + (s[dot + 2] - '0');
    cents = ip * 100 + fp;
    if (neg && cents != 0) cents = -cents;
    return true;
}

bool parse_entry_amount(const std::string& s, long long& cents) {
    if (s.empty()) return false;
    auto dot = s.find('.');
    std::string int_part;
    std::string frac_part;
    if (dot == std::string::npos) {
        int_part = s;
    } else {
        int_part = s.substr(0, dot);
        frac_part = s.substr(dot + 1);
        if (frac_part.empty() || frac_part.size() > 2) return false;
        for (char c : frac_part) {
            if (!is_digit(c)) return false;
        }
    }
    if (int_part.empty() || int_part.size() > 9) return false;
    if (int_part.size() > 1 && int_part[0] == '0') return false;
    for (char c : int_part) {
        if (!is_digit(c)) return false;
    }

    long long ip = std::stoll(int_part);
    long long fp = 0;
    if (frac_part.size() == 1) {
        fp = (frac_part[0] - '0') * 10;
    } else if (frac_part.size() == 2) {
        fp = (frac_part[0] - '0') * 10 + (frac_part[1] - '0');
    }
    cents = ip * 100 + fp;
    return cents > 0;
}

bool is_valid_date(const std::string& d) {
    if (d.size() != 10) return false;
    if (d[4] != '-' || d[7] != '-') return false;
    for (int i : {0, 1, 2, 3, 5, 6, 8, 9}) {
        if (!is_digit(d[i])) return false;
    }
    int y = std::stoi(d.substr(0, 4));
    int m = std::stoi(d.substr(5, 2));
    int day = std::stoi(d.substr(8, 2));
    if (y < 1900 || y > 2999) return false;
    if (m < 1 || m > 12) return false;
    int days_in_month[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
    bool leap = (y % 4 == 0 && (y % 100 != 0 || y % 400 == 0));
    if (leap) days_in_month[2] = 29;
    if (day < 1 || day > days_in_month[m]) return false;
    return true;
}

bool normalize_and_validate_memo(const std::string& memo, std::string& norm) {
    for (unsigned char c : memo) {
        if (c < 32 || c == 127) return false;
    }
    std::vector<std::string> tokens;
    std::string cur;
    for (unsigned char c : memo) {
        if (c == ' ') {
            if (!cur.empty()) {
                tokens.push_back(cur);
                cur.clear();
            }
        } else {
            cur.push_back(static_cast<char>(c));
        }
    }
    if (!cur.empty()) tokens.push_back(cur);
    if (tokens.empty()) return false;

    norm.clear();
    for (size_t i = 0; i < tokens.size(); ++i) {
        if (i > 0) norm += ' ';
        norm += tokens[i];
    }
    return true;
}

std::string format_money(long long cents) {
    bool neg = cents < 0;
    unsigned long long abs_cents = neg ? -static_cast<unsigned long long>(cents) : static_cast<unsigned long long>(cents);
    unsigned long long dollars = abs_cents / 100;
    unsigned long long rem = abs_cents % 100;

    std::string d_str = std::to_string(dollars);
    std::string d_with_commas;
    int count = 0;
    for (int i = static_cast<int>(d_str.size()) - 1; i >= 0; --i) {
        if (count > 0 && count % 3 == 0) {
            d_with_commas.push_back(',');
        }
        d_with_commas.push_back(d_str[i]);
        count++;
    }
    std::reverse(d_with_commas.begin(), d_with_commas.end());

    std::string res = (neg ? "-" : "") + d_with_commas + ".";
    if (rem < 10) res += "0";
    res += std::to_string(rem);
    return res;
}

struct ParsedEntry {
    std::string date;
    std::string kind;
    long long amount;
    std::string norm_memo;
};

std::string render_entry_line(const std::string& date, const std::string& norm_memo, const std::string& kind, long long amount, long long balance) {
    std::string memo_col = norm_memo;
    if (memo_col.size() > 20) {
        memo_col = memo_col.substr(0, 19) + "~";
    }
    memo_col.append(20 - memo_col.size(), ' ');

    std::string amt_str = (kind == "credit" ? "+" : "-") + format_money(amount);
    if (amt_str.size() < 14) {
        amt_str = std::string(14 - amt_str.size(), ' ') + amt_str;
    }

    std::string bal_str = format_money(balance);
    if (bal_str.size() < 15) {
        bal_str = std::string(15 - bal_str.size(), ' ') + bal_str;
    }

    std::string flag = (balance < 0) ? " OD" : "";

    return date + "  " + memo_col + "  " + amt_str + "  " + bal_str + flag;
}

} // namespace

std::vector<std::string> render_statement(
    const std::string& opening,
    const std::vector<std::tuple<std::string, std::string, std::string, std::string>>& entries) 
{
    long long balance = 0;
    if (!parse_opening(opening, balance)) {
        throw std::invalid_argument("opening: bad amount '" + opening + "'");
    }

    std::vector<ParsedEntry> parsed_entries;
    parsed_entries.reserve(entries.size());

    std::string prev_date = "";
    for (size_t i = 0; i < entries.size(); ++i) {
        const auto& [date, kind, amount_str, memo] = entries[i];

        if (!is_valid_date(date)) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad date '" + date + "'");
        }
        if (i > 0 && date < prev_date) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": date out of order");
        }
        prev_date = date;

        if (kind != "credit" && kind != "debit" && kind != "fee") {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad kind '" + kind + "'");
        }

        long long amt_cents = 0;
        if (!parse_entry_amount(amount_str, amt_cents)) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad amount '" + amount_str + "'");
        }

        std::string norm_memo;
        if (!normalize_and_validate_memo(memo, norm_memo)) {
            throw std::invalid_argument("entry " + std::to_string(i) + ": bad memo");
        }

        parsed_entries.push_back({date, kind, amt_cents, norm_memo});
    }

    std::vector<std::string> out;
    out.push_back("Opening balance: " + format_money(balance));

    long long credits_count = 0;
    long long debits_count = 0;
    long long fees_count = 0;
    std::set<std::string> overdraft_dates;

    for (const auto& entry : parsed_entries) {
        if (entry.kind == "credit") {
            balance += entry.amount;
            credits_count++;
        } else if (entry.kind == "debit") {
            balance -= entry.amount;
            debits_count++;
        } else {
            balance -= entry.amount;
            fees_count++;
        }

        out.push_back(render_entry_line(entry.date, entry.norm_memo, entry.kind, entry.amount, balance));

        if (entry.kind == "debit" && balance < 0 && overdraft_dates.find(entry.date) == overdraft_dates.end()) {
            overdraft_dates.insert(entry.date);
            balance -= 2500;
            fees_count++;
            out.push_back(render_entry_line(entry.date, "OVERDRAFT FEE", "fee", 2500, balance));
        }
    }

    out.push_back("Closing balance: " + format_money(balance));
    out.push_back("Credits: " + std::to_string(credits_count) +
                  "  Debits: " + std::to_string(debits_count) +
                  "  Fees: " + std::to_string(fees_count));

    return out;
}

function isValidDate(dateStr: string): boolean {
    if (typeof dateStr !== 'string') return false;
    if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(dateStr)) return false;
    const year = parseInt(dateStr.slice(0, 4), 10);
    const month = parseInt(dateStr.slice(5, 7), 10);
    const day = parseInt(dateStr.slice(8, 10), 10);
    if (year < 1900 || year > 2999) return false;
    if (month < 1 || month > 12) return false;
    const daysInMonth = [0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    const isLeap = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);
    if (isLeap) {
        daysInMonth[2] = 29;
    }
    if (day < 1 || day > daysInMonth[month]) return false;
    return true;
}

const PYTHON_WS = /^[\t\n\x0b\x0c\r\x1c\x1d\x1e\x1f \x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+$/;
const PYTHON_WS_SPLIT = /[\t\n\x0b\x0c\r\x1c\x1d\x1e\x1f \x85\xa0\u1680\u2000-\u200a\u2028\u2029\u202f\u205f\u3000]+/;

function splitPythonWhitespace(s: string): string[] {
    return s.split(PYTHON_WS_SPLIT).filter(part => part.length > 0);
}

function isValidMemo(memo: unknown): memo is string {
    if (typeof memo !== 'string') return false;
    for (let i = 0; i < memo.length; i++) {
        const code = memo.charCodeAt(i);
        if (code < 32 || code === 127) {
            return false;
        }
    }
    const parts = splitPythonWhitespace(memo);
    if (parts.length === 0) return false;
    return true;
}

function parseCents(amountStr: string): bigint {
    let neg = false;
    let s = amountStr;
    if (s.startsWith('-')) {
        neg = true;
        s = s.slice(1);
    }
    const parts = s.split('.');
    const intPart = BigInt(parts[0]);
    let decPart = 0n;
    if (parts.length > 1) {
        const decStr = parts[1].padEnd(2, '0');
        decPart = BigInt(decStr);
    }
    const total = intPart * 100n + decPart;
    return neg ? -total : total;
}

function formatMoney(cents: bigint): string {
    if (cents === 0n) return "0.00";
    const neg = cents < 0n;
    const absCents = neg ? -cents : cents;
    const intPart = absCents / 100n;
    const decPart = absCents % 100n;

    const intStr = intPart.toString();
    const withCommas = intStr.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    const decStr = decPart.toString().padStart(2, '0');
    return (neg ? "-" : "") + withCommas + "." + decStr;
}

function formatMemo(memo: string): string {
    const normalized = splitPythonWhitespace(memo).join(' ');
    let truncated = normalized;
    if (normalized.length > 20) {
        truncated = normalized.slice(0, 19) + '~';
    }
    return truncated.padEnd(20, ' ');
}

export function renderStatement(opening: string, entries: [string, string, string, string][]): string[] {
    // 1. If opening is not a str: raise TypeError("opening must be a str")
    if (typeof opening !== 'string') {
        throw new TypeError("opening must be a str");
    }

    // 2. If opening does not match the pattern
    const openingPattern = /^-?(0|[1-9][0-9]{0,8})\.[0-9]{2}$/;
    if (!openingPattern.test(opening)) {
        throw new Error(`opening: bad amount '${opening}'`);
    }

    // 3. If entries is not a list: raise TypeError("entries must be a list")
    if (!Array.isArray(entries)) {
        throw new TypeError("entries must be a list");
    }

    // 4. Validate entries
    const amountPattern = /^(0|[1-9][0-9]{0,8})(\.[0-9]{1,2})?$/;
    let prevDate: string | null = null;

    for (let i = 0; i < entries.length; i++) {
        const entry = entries[i];
        // a. not a tuple, or a tuple whose length is not 4
        if (!Array.isArray(entry) || entry.length !== 4) {
            throw new TypeError(`entry ${i}: expected 4-tuple`);
        }

        const [date, kind, amount, memo] = entry;

        // b. date validation
        if (!isValidDate(date)) {
            throw new Error(`entry ${i}: bad date ${JSON.stringify(date)}`);
        }

        // c. date order validation
        if (prevDate !== null && date < prevDate) {
            throw new Error(`entry ${i}: date out of order`);
        }
        prevDate = date;

        // d. kind validation
        if (typeof kind !== 'string' || (kind !== 'credit' && kind !== 'debit' && kind !== 'fee')) {
            throw new Error(`entry ${i}: bad kind ${JSON.stringify(kind)}`);
        }

        // e. amount validation
        if (typeof amount !== 'string' || !amountPattern.test(amount)) {
            throw new Error(`entry ${i}: bad amount ${JSON.stringify(amount)}`);
        }
        const cents = parseCents(amount);
        if (cents === 0n) {
            throw new Error(`entry ${i}: bad amount ${JSON.stringify(amount)}`);
        }

        // f. memo validation
        if (!isValidMemo(memo)) {
            throw new Error(`entry ${i}: bad memo`);
        }
    }

    // Processing
    let balance = parseCents(opening);
    const lines: string[] = [];
    lines.push(`Opening balance: ${formatMoney(balance)}`);

    const overdraftDates = new Set<string>();
    let creditsCount = 0;
    let debitsCount = 0;
    let feesCount = 0;

    function applyAndRender(date: string, kind: string, amountCents: bigint, memo: string) {
        if (kind === 'credit') {
            balance += amountCents;
            creditsCount++;
        } else if (kind === 'debit') {
            balance -= amountCents;
            debitsCount++;
        } else if (kind === 'fee') {
            balance -= amountCents;
            feesCount++;
        }

        const memoCol = formatMemo(memo);
        const sign = kind === 'credit' ? '+' : '-';
        const amtCol = (sign + formatMoney(amountCents)).padStart(14, ' ');
        const balCol = formatMoney(balance).padStart(15, ' ');
        const flag = balance < 0n ? ' OD' : '';

        lines.push(`${date}  ${memoCol}  ${amtCol}  ${balCol}${flag}`);
    }

    for (let i = 0; i < entries.length; i++) {
        const [date, kind, amount, memo] = entries[i];
        const amountCents = parseCents(amount);
        applyAndRender(date, kind, amountCents, memo);

        if (kind === 'debit' && balance < 0n && !overdraftDates.has(date)) {
            overdraftDates.add(date);
            applyAndRender(date, 'fee', 2500n, 'OVERDRAFT FEE');
        }
    }

    lines.push(`Closing balance: ${formatMoney(balance)}`);
    lines.push(`Credits: ${creditsCount}  Debits: ${debitsCount}  Fees: ${feesCount}`);

    return lines;
}

package main

import (
	"errors"
	"fmt"
	"math/big"
	"strings"
)

type Version struct {
	Raw string
	X   *big.Int
	Y   *big.Int
	Z   *big.Int
	RC  *big.Int // nil if not a release candidate
}

func (v *Version) IsRC() bool {
	return v.RC != nil
}

func CompareVersion(a, b *Version) int {
	if c := a.X.Cmp(b.X); c != 0 {
		return c
	}
	if c := a.Y.Cmp(b.Y); c != 0 {
		return c
	}
	if c := a.Z.Cmp(b.Z); c != 0 {
		return c
	}
	if a.RC == nil && b.RC == nil {
		return 0
	}
	if a.RC != nil && b.RC == nil {
		return -1
	}
	if a.RC == nil && b.RC != nil {
		return 1
	}
	return a.RC.Cmp(b.RC)
}

func parsePart(s string, allowZero bool) (*big.Int, bool) {
	if len(s) == 0 {
		return nil, false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return nil, false
		}
	}
	if s[0] == '0' {
		if len(s) > 1 || !allowZero {
			return nil, false
		}
	}
	n := new(big.Int)
	n.SetString(s, 10)
	return n, true
}

func parseVersion(s string) (*Version, bool) {
	var mainPart, rcPart string
	hasRC := false

	if idx := strings.Index(s, "~"); idx != -1 {
		if !strings.HasPrefix(s[idx:], "~rc") {
			return nil, false
		}
		mainPart = s[:idx]
		rcPart = s[idx+3:]
		hasRC = true
	} else {
		mainPart = s
	}

	parts := strings.Split(mainPart, ".")
	if len(parts) != 3 {
		return nil, false
	}

	x, ok := parsePart(parts[0], true)
	if !ok {
		return nil, false
	}
	y, ok := parsePart(parts[1], true)
	if !ok {
		return nil, false
	}
	z, ok := parsePart(parts[2], true)
	if !ok {
		return nil, false
	}

	var rc *big.Int
	if hasRC {
		rc, ok = parsePart(rcPart, false)
		if !ok {
			return nil, false
		}
	}

	return &Version{
		Raw: s,
		X:   x,
		Y:   y,
		Z:   z,
		RC:  rc,
	}, true
}

type ClauseType int

const (
	ClauseAny ClauseType = iota
	ClauseEq
	ClauseNe
	ClauseGt
	ClauseGe
	ClauseLt
	ClauseLe
	ClauseMajor
	ClauseMajorMinor
	ClauseAt
)

type Clause struct {
	Type ClauseType
	V    *Version
	X    *big.Int
	Y    *big.Int
}

func (c *Clause) Matches(v *Version) bool {
	switch c.Type {
	case ClauseAny:
		return true
	case ClauseEq:
		return CompareVersion(v, c.V) == 0
	case ClauseNe:
		return CompareVersion(v, c.V) != 0
	case ClauseGt:
		return CompareVersion(v, c.V) > 0
	case ClauseGe:
		return CompareVersion(v, c.V) >= 0
	case ClauseLt:
		return CompareVersion(v, c.V) < 0
	case ClauseLe:
		return CompareVersion(v, c.V) <= 0
	case ClauseMajor:
		return v.X.Cmp(c.X) == 0
	case ClauseMajorMinor:
		return v.X.Cmp(c.X) == 0 && v.Y.Cmp(c.Y) == 0
	case ClauseAt:
		return v.X.Cmp(c.X) == 0 && v.Y.Cmp(c.Y) >= 0
	}
	return false
}

func parseClause(s string) (*Clause, bool) {
	if s == "" {
		return nil, false
	}
	if s == "*" {
		return &Clause{Type: ClauseAny}, true
	}
	if strings.HasPrefix(s, "!=") {
		v, ok := parseVersion(s[2:])
		if !ok {
			return nil, false
		}
		return &Clause{Type: ClauseNe, V: v}, true
	}
	if strings.HasPrefix(s, ">=") {
		v, ok := parseVersion(s[2:])
		if !ok {
			return nil, false
		}
		return &Clause{Type: ClauseGe, V: v}, true
	}
	if strings.HasPrefix(s, "<=") {
		v, ok := parseVersion(s[2:])
		if !ok {
			return nil, false
		}
		return &Clause{Type: ClauseLe, V: v}, true
	}
	if strings.HasPrefix(s, ">") {
		v, ok := parseVersion(s[1:])
		if !ok {
			return nil, false
		}
		return &Clause{Type: ClauseGt, V: v}, true
	}
	if strings.HasPrefix(s, "<") {
		v, ok := parseVersion(s[1:])
		if !ok {
			return nil, false
		}
		return &Clause{Type: ClauseLt, V: v}, true
	}
	if strings.HasPrefix(s, "=") {
		v, ok := parseVersion(s[1:])
		if !ok {
			return nil, false
		}
		return &Clause{Type: ClauseEq, V: v}, true
	}
	if strings.HasPrefix(s, "@") {
		parts := strings.Split(s[1:], ".")
		if len(parts) != 2 {
			return nil, false
		}
		x, ok1 := parsePart(parts[0], true)
		y, ok2 := parsePart(parts[1], true)
		if !ok1 || !ok2 {
			return nil, false
		}
		return &Clause{Type: ClauseAt, X: x, Y: y}, true
	}
	if strings.HasSuffix(s, ".*") {
		prefix := s[:len(s)-2]
		parts := strings.Split(prefix, ".")
		if len(parts) == 1 {
			x, ok := parsePart(parts[0], true)
			if !ok {
				return nil, false
			}
			return &Clause{Type: ClauseMajor, X: x}, true
		} else if len(parts) == 2 {
			x, ok1 := parsePart(parts[0], true)
			y, ok2 := parsePart(parts[1], true)
			if !ok1 || !ok2 {
				return nil, false
			}
			return &Clause{Type: ClauseMajorMinor, X: x, Y: y}, true
		}
		return nil, false
	}

	v, ok := parseVersion(s)
	if !ok {
		return nil, false
	}
	return &Clause{Type: ClauseEq, V: v}, true
}

type Alternative struct {
	AllowRC bool
	Clauses []*Clause
}

func (alt *Alternative) Matches(v *Version) bool {
	if v.IsRC() && !alt.AllowRC {
		return false
	}
	for _, c := range alt.Clauses {
		if !c.Matches(v) {
			return false
		}
	}
	return true
}

func stripSpaces(s string) string {
	start := 0
	for start < len(s) && s[start] == ' ' {
		start++
	}
	end := len(s)
	for end > start && s[end-1] == ' ' {
		end--
	}
	return s[start:end]
}

func PickVersion(available []string, constraint string) (*string, error) {
	if available == nil {
		return nil, errors.New("available must be a list")
	}

	parsedVersions := make([]*Version, len(available))
	for i, vStr := range available {
		v, ok := parseVersion(vStr)
		if !ok {
			return nil, fmt.Errorf("invalid version at index %d: %q", i, vStr)
		}
		parsedVersions[i] = v
	}

	if stripSpaces(constraint) == "" {
		return nil, errors.New("empty constraint")
	}

	rawAlts := strings.Split(constraint, "|")
	alternatives := make([]*Alternative, 0, len(rawAlts))

	for aIdx, rawAlt := range rawAlts {
		aNum := aIdx + 1
		altStr := stripSpaces(rawAlt)
		allowRC := false
		if strings.HasPrefix(altStr, "?") {
			allowRC = true
			altStr = stripSpaces(altStr[1:])
		}
		if altStr == "" {
			return nil, fmt.Errorf("alternative %d is empty", aNum)
		}

		rawClauses := strings.Split(altStr, ",")
		clauses := make([]*Clause, 0, len(rawClauses))
		for cIdx, rawClause := range rawClauses {
			cNum := cIdx + 1
			cStr := stripSpaces(rawClause)
			c, ok := parseClause(cStr)
			if !ok {
				return nil, fmt.Errorf("alternative %d, clause %d: invalid clause %q", aNum, cNum, cStr)
			}
			clauses = append(clauses, c)
		}

		alternatives = append(alternatives, &Alternative{
			AllowRC: allowRC,
			Clauses: clauses,
		})
	}

	var best *Version
	for _, v := range parsedVersions {
		matched := false
		for _, alt := range alternatives {
			if alt.Matches(v) {
				matched = true
				break
			}
		}
		if matched {
			if best == nil || CompareVersion(v, best) > 0 {
				best = v
			}
		}
	}

	if best == nil {
		return nil, nil
	}
	res := best.Raw
	return &res, nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {

    private static final class Version implements Comparable<Version> {
        final BigInteger major;
        final BigInteger minor;
        final BigInteger patch;
        final BigInteger rc; // null if not RC, >= 1 if RC
        final String original;

        Version(BigInteger major, BigInteger minor, BigInteger patch, BigInteger rc, String original) {
            this.major = major;
            this.minor = minor;
            this.patch = patch;
            this.rc = rc;
            this.original = original;
        }

        boolean isRc() {
            return rc != null;
        }

        @Override
        public int compareTo(Version o) {
            int c = this.major.compareTo(o.major);
            if (c != 0) return c;
            c = this.minor.compareTo(o.minor);
            if (c != 0) return c;
            c = this.patch.compareTo(o.patch);
            if (c != 0) return c;
            if (this.rc == null && o.rc == null) return 0;
            if (this.rc == null) return 1; // plain release > RC
            if (o.rc == null) return -1;
            return this.rc.compareTo(o.rc);
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Version)) return false;
            Version v = (Version) o;
            return this.compareTo(v) == 0;
        }

        @Override
        public int hashCode() {
            return Objects.hash(major, minor, patch, rc);
        }
    }

    private interface Clause {
        boolean matches(Version v);
    }

    private static final class Alternative {
        final boolean allowRc;
        final List<Clause> clauses;

        Alternative(boolean allowRc, List<Clause> clauses) {
            this.allowRc = allowRc;
            this.clauses = clauses;
        }

        boolean matches(Version v) {
            if (v.isRc() && !allowRc) {
                return false;
            }
            for (Clause c : clauses) {
                if (!c.matches(v)) {
                    return false;
                }
            }
            return true;
        }
    }

    private static BigInteger parseNumber(String s, boolean allowZero) {
        if (s == null || s.isEmpty()) return null;
        if (s.equals("0")) {
            return allowZero ? BigInteger.ZERO : null;
        }
        if (s.charAt(0) == '0') {
            return null; // leading zero
        }
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch < '0' || ch > '9') {
                return null;
            }
        }
        return new BigInteger(s);
    }

    private static Version parseVersion(String s) {
        if (s == null || s.isEmpty()) return null;
        String mainPart = s;
        BigInteger rcVal = null;

        int tildeIdx = s.indexOf('~');
        if (tildeIdx != -1) {
            mainPart = s.substring(0, tildeIdx);
            String rcPart = s.substring(tildeIdx + 1);
            if (!rcPart.startsWith("rc")) {
                return null;
            }
            rcVal = parseNumber(rcPart.substring(2), false);
            if (rcVal == null) {
                return null;
            }
        }

        String[] parts = mainPart.split("\\.", -1);
        if (parts.length != 3) {
            return null;
        }
        BigInteger x = parseNumber(parts[0], true);
        BigInteger y = parseNumber(parts[1], true);
        BigInteger z = parseNumber(parts[2], true);
        if (x == null || y == null || z == null) {
            return null;
        }
        return new Version(x, y, z, rcVal, s);
    }

    private static String trimSpaces(String s) {
        int start = 0;
        int end = s.length();
        while (start < end && s.charAt(start) == ' ') {
            start++;
        }
        while (end > start && s.charAt(end - 1) == ' ') {
            end--;
        }
        return s.substring(start, end);
    }

    private static Clause parseClause(String s) {
        if (s.isEmpty()) return null;
        if (s.equals("*")) {
            return v -> true;
        }
        if (s.startsWith("!=")) {
            Version target = parseVersion(s.substring(2));
            if (target == null) return null;
            return v -> v.compareTo(target) != 0;
        }
        if (s.startsWith(">=")) {
            Version target = parseVersion(s.substring(2));
            if (target == null) return null;
            return v -> v.compareTo(target) >= 0;
        }
        if (s.startsWith("<=")) {
            Version target = parseVersion(s.substring(2));
            if (target == null) return null;
            return v -> v.compareTo(target) <= 0;
        }
        if (s.startsWith(">")) {
            Version target = parseVersion(s.substring(1));
            if (target == null) return null;
            return v -> v.compareTo(target) > 0;
        }
        if (s.startsWith("<")) {
            Version target = parseVersion(s.substring(1));
            if (target == null) return null;
            return v -> v.compareTo(target) < 0;
        }
        if (s.startsWith("=")) {
            Version target = parseVersion(s.substring(1));
            if (target == null) return null;
            return v -> v.compareTo(target) == 0;
        }
        if (s.startsWith("@")) {
            String rest = s.substring(1);
            String[] parts = rest.split("\\.", -1);
            if (parts.length != 2) return null;
            BigInteger x = parseNumber(parts[0], true);
            BigInteger y = parseNumber(parts[1], true);
            if (x == null || y == null) return null;
            return v -> v.major.equals(x) && v.minor.compareTo(y) >= 0;
        }
        if (s.endsWith(".*")) {
            String prefix = s.substring(0, s.length() - 2);
            String[] parts = prefix.split("\\.", -1);
            if (parts.length == 1) {
                BigInteger x = parseNumber(parts[0], true);
                if (x == null) return null;
                return v -> v.major.equals(x);
            } else if (parts.length == 2) {
                BigInteger x = parseNumber(parts[0], true);
                BigInteger y = parseNumber(parts[1], true);
                if (x == null || y == null) return null;
                return v -> v.major.equals(x) && v.minor.equals(y);
            } else {
                return null;
            }
        }
        Version target = parseVersion(s);
        if (target != null) {
            return v -> v.compareTo(target) == 0;
        }
        return null;
    }

    public static String pickVersion(List<String> available, String constraint) {
        if (available == null) {
            throw new IllegalArgumentException("available must be a list");
        }
        List<Version> parsedVersions = new ArrayList<>(available.size());
        for (int i = 0; i < available.size(); i++) {
            String el = available.get(i);
            if (el == null) {
                throw new IllegalArgumentException("invalid version at index " + i + ": None");
            }
            Version v = parseVersion(el);
            if (v == null) {
                throw new IllegalArgumentException("invalid version at index " + i + ": '" + el + "'");
            }
            parsedVersions.add(v);
        }

        if (constraint == null) {
            throw new IllegalArgumentException("constraint must be a str");
        }
        if (trimSpaces(constraint).isEmpty()) {
            throw new IllegalArgumentException("empty constraint");
        }

        String[] altStrings = constraint.split("\\|", -1);
        List<Alternative> alternatives = new ArrayList<>(altStrings.length);
        for (int a = 0; a < altStrings.length; a++) {
            int altNum = a + 1;
            String altStr = trimSpaces(altStrings[a]);
            boolean allowRc = false;
            if (altStr.startsWith("?")) {
                allowRc = true;
                altStr = trimSpaces(altStr.substring(1));
            }
            if (altStr.isEmpty()) {
                throw new IllegalArgumentException("alternative " + altNum + " is empty");
            }
            String[] clauseStrings = altStr.split(",", -1);
            List<Clause> clauses = new ArrayList<>(clauseStrings.length);
            for (int c = 0; c < clauseStrings.length; c++) {
                int clauseNum = c + 1;
                String clauseStr = trimSpaces(clauseStrings[c]);
                Clause clause = parseClause(clauseStr);
                if (clause == null) {
                    throw new IllegalArgumentException(
                            "alternative " + altNum + ", clause " + clauseNum + ": invalid clause '" + clauseStr + "'");
                }
                clauses.add(clause);
            }
            alternatives.add(new Alternative(allowRc, clauses));
        }

        Version best = null;
        for (Version v : parsedVersions) {
            boolean matched = false;
            for (Alternative alt : alternatives) {
                if (alt.matches(v)) {
                    matched = true;
                    break;
                }
            }
            if (matched) {
                if (best == null || v.compareTo(best) > 0) {
                    best = v;
                }
            }
        }

        return best == null ? null : best.original;
    }
}

#include <algorithm>
#include <cctype>
#include <optional>
#include <stdexcept>
#include <string>
#include <string_view>
#include <tuple>
#include <vector>

namespace {

bool is_valid_int(std::string_view s, bool allow_zero = true) {
    if (s.empty()) return false;
    for (char c : s) {
        if (c < '0' || c > '9') return false;
    }
    if (s.size() > 1 && s[0] == '0') return false;
    if (!allow_zero && s == "0") return false;
    return true;
}

int compare_num(std::string_view a, std::string_view b) {
    if (a.size() != b.size()) {
        return a.size() < b.size() ? -1 : 1;
    }
    int cmp = a.compare(b);
    if (cmp < 0) return -1;
    if (cmp > 0) return 1;
    return 0;
}

struct Version {
    std::string raw;
    std::string x;
    std::string y;
    std::string z;
    bool is_rc = false;
    std::string rc;

    int compare(const Version& o) const {
        if (int c = compare_num(x, o.x); c != 0) return c;
        if (int c = compare_num(y, o.y); c != 0) return c;
        if (int c = compare_num(z, o.z); c != 0) return c;
        if (is_rc != o.is_rc) {
            return is_rc ? -1 : 1; // RC is lower than plain release
        }
        if (is_rc) {
            return compare_num(rc, o.rc);
        }
        return 0;
    }

    bool operator==(const Version& o) const { return compare(o) == 0; }
    bool operator!=(const Version& o) const { return compare(o) != 0; }
    bool operator<(const Version& o) const { return compare(o) < 0; }
    bool operator<=(const Version& o) const { return compare(o) <= 0; }
    bool operator>(const Version& o) const { return compare(o) > 0; }
    bool operator>=(const Version& o) const { return compare(o) >= 0; }
};

std::optional<Version> parse_version(std::string_view s) {
    Version v;
    v.raw = std::string(s);

    auto tilde_pos = s.find('~');
    std::string_view main_part = s;
    if (tilde_pos != std::string_view::npos) {
        main_part = s.substr(0, tilde_pos);
        std::string_view rc_part = s.substr(tilde_pos + 1);
        if (rc_part.substr(0, 2) != "rc") return std::nullopt;
        std::string_view n_part = rc_part.substr(2);
        if (!is_valid_int(n_part, false)) return std::nullopt;
        v.is_rc = true;
        v.rc = std::string(n_part);
    }

    auto dot1 = main_part.find('.');
    if (dot1 == std::string_view::npos) return std::nullopt;
    auto dot2 = main_part.find('.', dot1 + 1);
    if (dot2 == std::string_view::npos) return std::nullopt;
    if (main_part.find('.', dot2 + 1) != std::string_view::npos) return std::nullopt;

    std::string_view x_part = main_part.substr(0, dot1);
    std::string_view y_part = main_part.substr(dot1 + 1, dot2 - dot1 - 1);
    std::string_view z_part = main_part.substr(dot2 + 1);

    if (!is_valid_int(x_part) || !is_valid_int(y_part) || !is_valid_int(z_part)) {
        return std::nullopt;
    }

    v.x = std::string(x_part);
    v.y = std::string(y_part);
    v.z = std::string(z_part);
    return v;
}

std::string_view trim_spaces(std::string_view s) {
    size_t start = 0;
    while (start < s.size() && s[start] == ' ') start++;
    size_t end = s.size();
    while (end > start && s[end - 1] == ' ') end--;
    return s.substr(start, end - start);
}

std::vector<std::string_view> split(std::string_view s, char delim) {
    std::vector<std::string_view> res;
    size_t start = 0;
    while (true) {
        size_t pos = s.find(delim, start);
        if (pos == std::string_view::npos) {
            res.push_back(s.substr(start));
            break;
        }
        res.push_back(s.substr(start, pos - start));
        start = pos + 1;
    }
    return res;
}

enum class ClauseType {
    ANY,
    EQ,
    NE,
    LT,
    LE,
    GT,
    GE,
    WILDCARD_X,
    WILDCARD_XY,
    AT_XY
};

struct Clause {
    ClauseType type;
    Version v;
    std::string x;
    std::string y;

    bool matches(const Version& ver) const {
        switch (type) {
            case ClauseType::ANY: return true;
            case ClauseType::EQ: return ver == v;
            case ClauseType::NE: return ver != v;
            case ClauseType::LT: return ver < v;
            case ClauseType::LE: return ver <= v;
            case ClauseType::GT: return ver > v;
            case ClauseType::GE: return ver >= v;
            case ClauseType::WILDCARD_X: return compare_num(ver.x, x) == 0;
            case ClauseType::WILDCARD_XY: return compare_num(ver.x, x) == 0 && compare_num(ver.y, y) == 0;
            case ClauseType::AT_XY: return compare_num(ver.x, x) == 0 && compare_num(ver.y, y) >= 0;
        }
        return false;
    }
};

std::optional<Clause> parse_clause(std::string_view s) {
    if (s.empty()) return std::nullopt;
    if (s == "*") {
        return Clause{ClauseType::ANY, {}, "", ""};
    }
    if (s.substr(0, 2) == "!=") {
        if (auto v = parse_version(s.substr(2))) return Clause{ClauseType::NE, *v, "", ""};
        return std::nullopt;
    }
    if (s.substr(0, 2) == ">=") {
        if (auto v = parse_version(s.substr(2))) return Clause{ClauseType::GE, *v, "", ""};
        return std::nullopt;
    }
    if (s.substr(0, 2) == "<=") {
        if (auto v = parse_version(s.substr(2))) return Clause{ClauseType::LE, *v, "", ""};
        return std::nullopt;
    }
    if (s[0] == '>') {
        if (auto v = parse_version(s.substr(1))) return Clause{ClauseType::GT, *v, "", ""};
        return std::nullopt;
    }
    if (s[0] == '<') {
        if (auto v = parse_version(s.substr(1))) return Clause{ClauseType::LT, *v, "", ""};
        return std::nullopt;
    }
    if (s[0] == '=') {
        if (auto v = parse_version(s.substr(1))) return Clause{ClauseType::EQ, *v, "", ""};
        return std::nullopt;
    }
    if (s[0] == '@') {
        std::string_view rest = s.substr(1);
        auto dot = rest.find('.');
        if (dot == std::string_view::npos) return std::nullopt;
        if (rest.find('.', dot + 1) != std::string_view::npos) return std::nullopt;
        std::string_view x = rest.substr(0, dot);
        std::string_view y = rest.substr(dot + 1);
        if (is_valid_int(x) && is_valid_int(y)) {
            return Clause{ClauseType::AT_XY, {}, std::string(x), std::string(y)};
        }
        return std::nullopt;
    }
    if (s.size() >= 2 && s.substr(s.size() - 2) == ".*") {
        std::string_view prefix = s.substr(0, s.size() - 2);
        auto dot = prefix.find('.');
        if (dot == std::string_view::npos) {
            if (is_valid_int(prefix)) {
                return Clause{ClauseType::WILDCARD_X, {}, std::string(prefix), ""};
            }
            return std::nullopt;
        } else {
            if (prefix.find('.', dot + 1) != std::string_view::npos) return std::nullopt;
            std::string_view x = prefix.substr(0, dot);
            std::string_view y = prefix.substr(dot + 1);
            if (is_valid_int(x) && is_valid_int(y)) {
                return Clause{ClauseType::WILDCARD_XY, {}, std::string(x), std::string(y)};
            }
            return std::nullopt;
        }
    }
    if (auto v = parse_version(s)) {
        return Clause{ClauseType::EQ, *v, "", ""};
    }
    return std::nullopt;
}

struct Alternative {
    bool allow_rc = false;
    std::vector<Clause> clauses;

    bool matches(const Version& ver) const {
        if (ver.is_rc && !allow_rc) return false;
        for (const auto& c : clauses) {
            if (!c.matches(ver)) return false;
        }
        return true;
    }
};

} // namespace

std::optional<std::string> pick_version(const std::vector<std::string>& available, const std::string& constraint) {
    // 1. Validate available versions
    std::vector<Version> parsed_available;
    parsed_available.reserve(available.size());
    for (size_t i = 0; i < available.size(); ++i) {
        auto v = parse_version(available[i]);
        if (!v) {
            throw std::invalid_argument("invalid version at index " + std::to_string(i));
        }
        parsed_available.push_back(std::move(*v));
    }

    // 2. Validate constraint not empty or spaces only
    if (trim_spaces(constraint).empty()) {
        throw std::invalid_argument("empty constraint");
    }

    // 3. Parse alternatives and clauses
    auto alt_strs = split(constraint, '|');
    std::vector<Alternative> alternatives;
    alternatives.reserve(alt_strs.size());

    for (size_t a = 0; a < alt_strs.size(); ++a) {
        std::string_view alt_sv = trim_spaces(alt_strs[a]);
        Alternative alt;
        if (!alt_sv.empty() && alt_sv[0] == '?') {
            alt.allow_rc = true;
            alt_sv = trim_spaces(alt_sv.substr(1));
        }
        if (alt_sv.empty()) {
            throw std::invalid_argument("alternative " + std::to_string(a + 1) + " is empty");
        }

        auto clause_strs = split(alt_sv, ',');
        alt.clauses.reserve(clause_strs.size());
        for (size_t c = 0; c < clause_strs.size(); ++c) {
            std::string_view clause_sv = trim_spaces(clause_strs[c]);
            auto parsed_c = parse_clause(clause_sv);
            if (!parsed_c) {
                throw std::invalid_argument("alternative " + std::to_string(a + 1) +
                                            ", clause " + std::to_string(c + 1) +
                                            ": invalid clause");
            }
            alt.clauses.push_back(std::move(*parsed_c));
        }
        alternatives.push_back(std::move(alt));
    }

    // 4. Find highest matching version
    const Version* best = nullptr;
    for (const auto& ver : parsed_available) {
        bool matched = false;
        for (const auto& alt : alternatives) {
            if (alt.matches(ver)) {
                matched = true;
                break;
            }
        }
        if (matched) {
            if (!best || *best < ver) {
                best = &ver;
            }
        }
    }

    if (best) {
        return best->raw;
    }
    return std::nullopt;
}

type Version = {
  raw: string;
  major: number;
  minor: number;
  patch: number;
  rc: number | null; // null means plain release (which is > any rc)
};

type Clause = (v: Version) => boolean;

type Alternative = {
  allowRc: boolean;
  clauses: Clause[];
};

const VERSION_REGEX = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)(?:~rc([1-9][0-9]*))?$/;
const X_STAR_REGEX = /^(0|[1-9][0-9]*)\.\*$/;
const X_Y_STAR_REGEX = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.\*$/;
const AT_X_Y_REGEX = /^@(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/;

function stripSpaces(s: string): string {
  let start = 0;
  let end = s.length;
  while (start < end && s[start] === ' ') {
    start++;
  }
  while (end > start && s[end - 1] === ' ') {
    end--;
  }
  return s.slice(start, end);
}

function parseVersion(s: string): Version | null {
  const m = VERSION_REGEX.exec(s);
  if (!m) return null;
  return {
    raw: s,
    major: Number(m[1]),
    minor: Number(m[2]),
    patch: Number(m[3]),
    rc: m[4] !== undefined ? Number(m[4]) : null,
  };
}

function compareVersions(a: Version, b: Version): number {
  if (a.major !== b.major) return a.major - b.major;
  if (a.minor !== b.minor) return a.minor - b.minor;
  if (a.patch !== b.patch) return a.patch - b.patch;
  if (a.rc === null && b.rc === null) return 0;
  if (a.rc === null) return 1; // plain release > rc
  if (b.rc === null) return -1;
  return a.rc - b.rc;
}

function parseClause(clauseStr: string): Clause | null {
  if (clauseStr === '*') {
    return () => true;
  }

  let m = X_STAR_REGEX.exec(clauseStr);
  if (m) {
    const major = Number(m[1]);
    return (v) => v.major === major;
  }

  m = X_Y_STAR_REGEX.exec(clauseStr);
  if (m) {
    const major = Number(m[1]);
    const minor = Number(m[2]);
    return (v) => v.major === major && v.minor === minor;
  }

  m = AT_X_Y_REGEX.exec(clauseStr);
  if (m) {
    const major = Number(m[1]);
    const minor = Number(m[2]);
    return (v) => v.major === major && v.minor >= minor;
  }

  const ops = ['!=', '>=', '<=', '=', '>', '<'];
  for (const op of ops) {
    if (clauseStr.startsWith(op)) {
      const target = parseVersion(clauseStr.slice(op.length));
      if (!target) return null;
      switch (op) {
        case '=':
          return (v) => compareVersions(v, target) === 0;
        case '!=':
          return (v) => compareVersions(v, target) !== 0;
        case '>':
          return (v) => compareVersions(v, target) > 0;
        case '>=':
          return (v) => compareVersions(v, target) >= 0;
        case '<':
          return (v) => compareVersions(v, target) < 0;
        case '<=':
          return (v) => compareVersions(v, target) <= 0;
      }
    }
  }

  const target = parseVersion(clauseStr);
  if (target) {
    return (v) => compareVersions(v, target) === 0;
  }

  return null;
}

export function pickVersion(available: string[], constraint: string): string | null {
  // 1. `available` is not a list -> TypeError("available must be a list")
  if (!Array.isArray(available)) {
    throw new TypeError("available must be a list");
  }

  // 2. each element in index order: not a str or not a valid version
  const parsedAvailable: Version[] = [];
  for (let i = 0; i < available.length; i++) {
    const el = available[i];
    if (typeof el !== 'string') {
      throw new Error(`invalid version at index ${i}: ${JSON.stringify(el)}`);
    }
    const v = parseVersion(el);
    if (!v) {
      throw new Error(`invalid version at index ${i}: '${el}'`);
    }
    parsedAvailable.push(v);
  }

  // 3. `constraint` is not a str -> TypeError("constraint must be a str")
  if (typeof constraint !== 'string') {
    throw new TypeError("constraint must be a str");
  }

  // 4. `constraint` is empty or consists only of spaces -> ValueError("empty constraint")
  if (stripSpaces(constraint) === '') {
    throw new Error("empty constraint");
  }

  // 5. alternatives left to right
  const rawAlternatives = constraint.split('|');
  const alternatives: Alternative[] = [];

  for (let aIdx = 0; aIdx < rawAlternatives.length; aIdx++) {
    const aNum = aIdx + 1;
    let altStr = stripSpaces(rawAlternatives[aIdx]);
    let allowRc = false;
    if (altStr.startsWith('?')) {
      allowRc = true;
      altStr = stripSpaces(altStr.slice(1));
    }

    if (altStr === '') {
      throw new Error(`alternative ${aNum} is empty`);
    }

    const rawClauses = altStr.split(',');
    const clauses: Clause[] = [];

    for (let cIdx = 0; cIdx < rawClauses.length; cIdx++) {
      const cNum = cIdx + 1;
      const clauseStr = stripSpaces(rawClauses[cIdx]);
      const fn = parseClause(clauseStr);
      if (!fn) {
        throw new Error(`alternative ${aNum}, clause ${cNum}: invalid clause '${clauseStr}'`);
      }
      clauses.push(fn);
    }

    alternatives.push({ allowRc, clauses });
  }

  // Matching
  let best: Version | null = null;
  for (const v of parsedAvailable) {
    let matchesConstraint = false;
    for (const alt of alternatives) {
      if (v.rc !== null && !alt.allowRc) {
        continue;
      }
      let matchesAllClauses = true;
      for (const clause of alt.clauses) {
        if (!clause(v)) {
          matchesAllClauses = false;
          break;
        }
      }
      if (matchesAllClauses) {
        matchesConstraint = true;
        break;
      }
    }

    if (matchesConstraint) {
      if (best === null || compareVersions(v, best) > 0) {
        best = v;
      }
    }
  }

  return best ? best.raw : null;
}

package main

import "sort"

type Tuple1 struct {
	F0 string
	F1 int
}

type state struct {
	score int
	time  int
}

func stateLess(a, b state) bool {
	if a.score != b.score {
		return a.score > b.score
	}
	return a.time < b.time
}

type playerInfo struct {
	bestScore int
	bestTime  int
}

func LeaderboardRanks(submissions []Tuple1) []int {
	n := len(submissions)
	if n == 0 {
		return []int{}
	}

	// Pass 1: Collect all distinct states that will ever exist on the leaderboard.
	players := make(map[string]playerInfo, n)
	states := make([]state, 0, n)

	for i, sub := range submissions {
		p := sub.F0
		sc := sub.F1
		info, ok := players[p]
		if !ok || sc > info.bestScore {
			players[p] = playerInfo{bestScore: sc, bestTime: i}
			states = append(states, state{score: sc, time: i})
		}
	}

	// Coordinate compression: sort all unique states in leaderboard order.
	// Since `time` is strictly unique for each appended state, all states in `states` are unique.
	sort.Slice(states, func(i, j int) bool {
		return stateLess(states[i], states[j])
	})

	m := len(states)
	bit := make([]int, m+1)

	add := func(idx, val int) {
		for idx <= m {
			bit[idx] += val
			idx += idx & -idx
		}
	}

	query := func(idx int) int {
		sum := 0
		for idx > 0 {
			sum += bit[idx]
			idx -= idx & -idx
		}
		return sum
	}

	findRank := func(st state) int {
		// Binary search for the exact state (1-based index for Fenwick tree).
		idx := sort.Search(m, func(i int) bool {
			return !stateLess(states[i], st)
		})
		return idx + 1
	}

	// Pass 2: Simulate the process using the Fenwick tree.
	// Store the current 1-based compressed rank for each active player, along with their bestScore.
	type activePlayer struct {
		bestScore int
		coord     int
	}
	active := make(map[string]activePlayer, len(players))
	ans := make([]int, n)

	for i, sub := range submissions {
		p := sub.F0
		sc := sub.F1
		act, ok := active[p]
		if !ok {
			coord := findRank(state{score: sc, time: i})
			active[p] = activePlayer{bestScore: sc, coord: coord}
			add(coord, 1)
			ans[i] = query(coord)
		} else {
			if sc > act.bestScore {
				add(act.coord, -1)
				coord := findRank(state{score: sc, time: i})
				active[p] = activePlayer{bestScore: sc, coord: coord}
				add(coord, 1)
				ans[i] = query(coord)
			} else {
				ans[i] = query(act.coord)
			}
		}
	}

	return ans
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1) {}

    private static final class PlayerState implements Comparable<PlayerState> {
        final long best;
        final int bestTime;

        PlayerState(long best, int bestTime) {
            this.best = best;
            this.bestTime = bestTime;
        }

        @Override
        public int compareTo(PlayerState o) {
            int cmp = Long.compare(o.best, this.best); // BEST descending
            if (cmp != 0) return cmp;
            return Integer.compare(this.bestTime, o.bestTime); // BEST TIME ascending
        }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof PlayerState that)) return false;
            return best == that.best && bestTime == that.bestTime;
        }

        @Override
        public int hashCode() {
            return Long.hashCode(best) * 31 + bestTime;
        }
    }

    private static final class Fenwick {
        private final int[] tree;

        Fenwick(int n) {
            this.tree = new int[n + 1];
        }

        void add(int idx, int delta) {
            for (int i = idx + 1; i < tree.length; i += i & -i) {
                tree[i] += delta;
            }
        }

        int query(int count) {
            int sum = 0;
            for (int i = count; i > 0; i -= i & -i) {
                sum += tree[i];
            }
            return sum;
        }
    }

    public static List<Long> leaderboardRanks(List<Tuple1> submissions) {
        int n = submissions.size();
        if (n == 0) {
            return new ArrayList<>();
        }

        // Pass 1: Collect all distinct (best, bestTime) pairs that ever exist
        Map<String, PlayerState> map = new HashMap<>();
        List<PlayerState> states = new ArrayList<>(n);

        for (int i = 0; i < n; i++) {
            Tuple1 sub = submissions.get(i);
            String player = sub.f0();
            long score = sub.f1();
            PlayerState cur = map.get(player);
            if (cur == null || score > cur.best) {
                PlayerState next = new PlayerState(score, i);
                map.put(player, next);
                states.add(next);
            }
        }

        // Coordinate compression
        Collections.sort(states);
        int m = states.size();
        long[] bests = new long[m];
        int[] times = new int[m];
        for (int i = 0; i < m; i++) {
            PlayerState ps = states.get(i);
            bests[i] = ps.best;
            times[i] = ps.bestTime;
        }

        // Pass 2: Simulate with Fenwick tree
        Map<String, Integer> playerPos = new HashMap<>(map.size() * 2);
        Fenwick bit = new Fenwick(m);
        List<Long> result = new ArrayList<>(n);

        for (int i = 0; i < n; i++) {
            Tuple1 sub = submissions.get(i);
            String player = sub.f0();
            long score = sub.f1();
            Integer curIdx = playerPos.get(player);
            if (curIdx == null) {
                int newIdx = findState(bests, times, score, i);
                playerPos.put(player, newIdx);
                bit.add(newIdx, 1);
                result.add(1L + bit.query(newIdx));
            } else {
                long curBest = bests[curIdx];
                if (score > curBest) {
                    bit.add(curIdx, -1);
                    int newIdx = findState(bests, times, score, i);
                    playerPos.put(player, newIdx);
                    bit.add(newIdx, 1);
                    result.add(1L + bit.query(newIdx));
                } else {
                    result.add(1L + bit.query(curIdx));
                }
            }
        }

        return result;
    }

    private static int findState(long[] bests, int[] times, long targetBest, int targetTime) {
        int low = 0, high = bests.length - 1;
        while (low <= high) {
            int mid = (low + high) >>> 1;
            long midBest = bests[mid];
            int cmp = Long.compare(targetBest, midBest); // Descending order of bests
            if (cmp == 0) {
                cmp = Integer.compare(times[mid], targetTime); // Ascending order of times
            }
            if (cmp < 0) {
                low = mid + 1;
            } else if (cmp > 0) {
                high = mid - 1;
            } else {
                return mid;
            }
        }
        throw new IllegalStateException("State not found");
    }
}

#include <vector>
#include <string>
#include <tuple>
#include <unordered_map>
#include <algorithm>

struct State {
    long long best_score;
    long long best_time;

    bool operator<(const State& other) const {
        if (best_score != other.best_score) {
            return best_score > other.best_score; // Higher score comes first
        }
        return best_time < other.best_time; // Earlier time comes first
    }

    bool operator==(const State& other) const {
        return best_score == other.best_score && best_time == other.best_time;
    }
};

struct Fenwick {
    int n;
    std::vector<int> tree;

    Fenwick(int n) : n(n), tree(n + 1, 0) {}

    void add(int i, int delta) {
        for (; i <= n; i += i & -i) {
            tree[i] += delta;
        }
    }

    int query(int i) const {
        int sum = 0;
        for (; i > 0; i -= i & -i) {
            sum += tree[i];
        }
        return sum;
    }
};

std::vector<long long> leaderboard_ranks(const std::vector<std::tuple<std::string, long long>>& submissions) {
    int n = submissions.size();
    if (n == 0) {
        return {};
    }

    // Coordinate compression for player names and gathering all reachable states
    std::unordered_map<std::string, int> player_to_id;
    player_to_id.reserve(n);
    std::vector<int> sub_player_id(n);
    std::vector<State> current_player_state;
    current_player_state.reserve(n);

    std::vector<State> all_states;
    all_states.reserve(n);

    int next_player_id = 0;
    for (int i = 0; i < n; ++i) {
        const auto& [player, score] = submissions[i];
        auto it = player_to_id.find(player);
        int pid;
        if (it == player_to_id.end()) {
            pid = next_player_id++;
            player_to_id[player] = pid;
            State st{score, i};
            current_player_state.push_back(st);
            all_states.push_back(st);
        } else {
            pid = it->second;
            if (score > current_player_state[pid].best_score) {
                State st{score, i};
                current_player_state[pid] = st;
                all_states.push_back(st);
            }
        }
        sub_player_id[i] = pid;
    }

    // Sort and remove duplicates to map each unique state to a 1-based rank index
    std::sort(all_states.begin(), all_states.end());
    all_states.erase(std::unique(all_states.begin(), all_states.end()), all_states.end());

    auto get_state_idx = [&](const State& st) {
        auto it = std::lower_bound(all_states.begin(), all_states.end(), st);
        return static_cast<int>(std::distance(all_states.begin(), it)) + 1;
    };

    // Replay the submissions and maintain the active states in a Fenwick tree
    Fenwick bit(all_states.size());
    std::vector<int> player_active_idx(next_player_id, -1);
    std::vector<State> sim_player_state(next_player_id);
    std::vector<long long> result(n);

    for (int i = 0; i < n; ++i) {
        int pid = sub_player_id[i];
        long long score = std::get<1>(submissions[i]);

        if (player_active_idx[pid] == -1) {
            State st{score, i};
            sim_player_state[pid] = st;
            int idx = get_state_idx(st);
            player_active_idx[pid] = idx;
            bit.add(idx, 1);
        } else {
            if (score > sim_player_state[pid].best_score) {
                bit.add(player_active_idx[pid], -1);
                State st{score, i};
                sim_player_state[pid] = st;
                int idx = get_state_idx(st);
                player_active_idx[pid] = idx;
                bit.add(idx, 1);
            }
        }

        // Since all activeBEST TIMEs are strictly distinct, no two players share the same active state.
        // Thus, the rank is simply the number of active states less than or equal to the current state.
        result[i] = bit.query(player_active_idx[pid]);
    }

    return result;
}

export function leaderboardRanks(submissions: [string, number][]): number[] {
    const n = submissions.length;
    if (n === 0) {
        return [];
    }

    // Each player's state is uniquely identified by the submission index `i`
    // where they achieved their current best score.
    // Sort all submission indices by (score DESC, index ASC).
    const order = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        order[i] = i;
    }
    order.sort((a, b) => {
        const scoreDiff = submissions[b][1] - submissions[a][1];
        return scoreDiff !== 0 ? scoreDiff : a - b;
    });

    // Map each submission index to its 1-based rank in the global order of states.
    const pos = new Int32Array(n);
    for (let rank = 0; rank < n; rank++) {
        pos[order[rank]] = rank + 1;
    }

    // Fenwick tree (Binary Indexed Tree) to count active states.
    const bit = new Int32Array(n + 1);
    function add(idx: number, delta: number): void {
        for (; idx <= n; idx += idx & -idx) {
            bit[idx] += delta;
        }
    }
    function query(idx: number): number {
        let sum = 0;
        for (; idx > 0; idx -= idx & -idx) {
            sum += bit[idx];
        }
        return sum;
    }

    // Map from player name to the submission index of their current best score.
    const playerBestIdx = new Map<string, number>();
    const result: number[] = new Array(n);

    for (let i = 0; i < n; i++) {
        const [player, score] = submissions[i];
        let bestIdx = playerBestIdx.get(player);

        if (bestIdx === undefined) {
            bestIdx = i;
            playerBestIdx.set(player, i);
            add(pos[i], 1);
        } else if (score > submissions[bestIdx][1]) {
            add(pos[bestIdx], -1);
            bestIdx = i;
            playerBestIdx.set(player, i);
            add(pos[i], 1);
        }

        result[i] = query(pos[bestIdx]);
    }

    return result;
}

package main

import (
	"sort"
)

type Tuple1 struct {
	F0 int
	F1 int
	F2 int
}

type Tuple2 struct {
	F0 int
	F1 int
}

type node struct {
	left  int32
	right int32
	cnt   int32
	sum   int
}

func BudgetPurchases(prices []int, queries []Tuple1) []Tuple2 {
	if len(queries) == 0 {
		return []Tuple2{}
	}
	n := len(prices)
	if n == 0 {
		return make([]Tuple2, len(queries))
	}

	// Coordinate compression
	sortedPrices := make([]int, n)
	copy(sortedPrices, prices)
	sort.Ints(sortedPrices)

	uniquePrices := sortedPrices[:0]
	for _, p := range sortedPrices {
		if len(uniquePrices) == 0 || uniquePrices[len(uniquePrices)-1] != p {
			uniquePrices = append(uniquePrices, p)
		}
	}
	m := len(uniquePrices)

	// Persistent Segment Tree
	// Node 0 is the implicit zero node.
	nodes := make([]node, 1, n*18+2)

	var update func(prev int32, l, r, idx, val int) int32
	update = func(prev int32, l, r, idx, val int) int32 {
		curr := int32(len(nodes))
		nodes = append(nodes, nodes[prev])
		nodes[curr].cnt++
		nodes[curr].sum += val
		if l == r {
			return curr
		}
		mid := (l + r) >> 1
		if idx <= mid {
			nodes[curr].left = update(nodes[prev].left, l, mid, idx, val)
		} else {
			nodes[curr].right = update(nodes[prev].right, mid+1, r, idx, val)
		}
		return curr
	}

	roots := make([]int32, n+1)
	for i, p := range prices {
		idx := sort.SearchInts(uniquePrices, p)
		roots[i+1] = update(roots[i], 0, m-1, idx, p)
	}

	res := make([]Tuple2, len(queries))
	for i, q := range queries {
		ql, qr, budget := q.F0, q.F1, q.F2
		u := roots[ql]
		v := roots[qr+1]

		if nodes[v].sum-nodes[u].sum <= budget {
			res[i] = Tuple2{int(nodes[v].cnt - nodes[u].cnt), nodes[v].sum - nodes[u].sum}
			continue
		}

		l, r := 0, m-1
		totalCnt := 0
		totalSpent := 0
		remBudget := budget

		for l < r {
			mid := (l + r) >> 1
			uLeft := nodes[u].left
			vLeft := nodes[v].left
			leftSum := nodes[vLeft].sum - nodes[uLeft].sum
			if leftSum <= remBudget {
				remBudget -= leftSum
				totalSpent += leftSum
				totalCnt += int(nodes[vLeft].cnt - nodes[uLeft].cnt)
				u = nodes[u].right
				v = nodes[v].right
				l = mid + 1
			} else {
				u = uLeft
				v = vLeft
				r = mid
			}
		}

		// Leaf node
		price := uniquePrices[l]
		avail := int(nodes[v].cnt - nodes[u].cnt)
		canBuy := remBudget / price
		if canBuy > avail {
			canBuy = avail
		}
		totalCnt += canBuy
		totalSpent += canBuy * price

		res[i] = Tuple2{totalCnt, totalSpent}
	}

	return res
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1, long f2) {}

    public record Tuple2(long f0, long f1) {}

    private static int[] leftChild;
    private static int[] rightChild;
    private static int[] count;
    private static long[] sum;
    private static int nodeCount;

    private static int update(int prevRoot, int l, int r, int pos, long val) {
        int curr = ++nodeCount;
        leftChild[curr] = leftChild[prevRoot];
        rightChild[curr] = rightChild[prevRoot];
        count[curr] = count[prevRoot] + 1;
        sum[curr] = sum[prevRoot] + val;
        if (l < r) {
            int mid = (l + r) >>> 1;
            if (pos <= mid) {
                leftChild[curr] = update(leftChild[prevRoot], l, mid, pos, val);
            } else {
                rightChild[curr] = update(rightChild[prevRoot], mid + 1, r, pos, val);
            }
        }
        return curr;
    }

    public static List<Tuple2> budgetPurchases(List<Long> prices, List<Tuple1> queries) {
        if (queries.isEmpty()) {
            return Collections.emptyList();
        }
        int n = prices.size();
        int q = queries.size();
        if (n == 0) {
            List<Tuple2> res = new ArrayList<>(q);
            for (int i = 0; i < q; i++) {
                res.add(new Tuple2(0, 0));
            }
            return res;
        }

        long[] sorted = new long[n];
        for (int i = 0; i < n; i++) {
            sorted[i] = prices.get(i);
        }
        Arrays.sort(sorted);

        long[] unique = new long[n];
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || sorted[i] != sorted[i - 1]) {
                unique[m++] = sorted[i];
            }
        }

        int maxNodes = n * 20 + 5;
        leftChild = new int[maxNodes];
        rightChild = new int[maxNodes];
        count = new int[maxNodes];
        sum = new long[maxNodes];
        nodeCount = 0;

        int[] roots = new int[n + 1];
        for (int i = 0; i < n; i++) {
            long p = prices.get(i);
            int rank = Arrays.binarySearch(unique, 0, m, p);
            roots[i + 1] = update(roots[i], 0, m - 1, rank, p);
        }

        List<Tuple2> result = new ArrayList<>(q);
        for (int i = 0; i < q; i++) {
            Tuple1 query = queries.get(i);
            int l = (int) query.f0();
            int r = (int) query.f1();
            long budget = query.f2();

            int u = roots[l];
            int v = roots[r + 1];

            if (sum[v] - sum[u] <= budget) {
                result.add(new Tuple2(count[v] - count[u], sum[v] - sum[u]));
                continue;
            }

            long totalCount = 0;
            long totalSpent = 0;
            int tl = 0, tr = m - 1;

            while (tl < tr) {
                int mid = (tl + tr) >>> 1;
                int leftU = leftChild[u];
                int leftV = leftChild[v];
                long leftSum = sum[leftV] - sum[leftU];
                if (leftSum <= budget) {
                    budget -= leftSum;
                    totalSpent += leftSum;
                    totalCount += count[leftV] - count[leftU];
                    u = rightChild[u];
                    v = rightChild[v];
                    tl = mid + 1;
                } else {
                    u = leftU;
                    v = leftV;
                    tr = mid;
                }
            }

            long price = unique[tl];
            long avail = count[v] - count[u];
            long canBuy = Math.min(avail, budget / price);
            totalCount += canBuy;
            totalSpent += canBuy * price;

            result.add(new Tuple2(totalCount, totalSpent));
        }

        // Clear static references to allow GC
        leftChild = null;
        rightChild = null;
        count = null;
        sum = null;

        return result;
    }
}

#include <vector>
