struct Node {
    int lc = 0, rc = 0;
    int cnt = 0;
    long long sum = 0;
};

static int update(int prev_root, int l, int r, int idx, long long val, std::vector<Node>& tree) {
    int curr = tree.size();
    tree.push_back(tree[prev_root]);
    tree[curr].cnt += 1;
    tree[curr].sum += val;
    if (l == r) {
        return curr;
    }
    int mid = l + (r - l) / 2;
    if (idx <= mid) {
        int left_child = update(tree[prev_root].lc, l, mid, idx, val, tree);
        tree[curr].lc = left_child;
    } else {
        int right_child = update(tree[prev_root].rc, mid + 1, r, idx, val, tree);
        tree[curr].rc = right_child;
    }
    return curr;
}

std::vector<std::tuple<long long, long long>> budget_purchases(
    const std::vector<long long>& prices,
    const std::vector<std::tuple<long long, long long, long long>>& queries) {

    int q_size = queries.size();
    std::vector<std::tuple<long long, long long>> results(q_size);
    if (q_size == 0) {
        return results;
    }

    int n = prices.size();
    if (n == 0) {
        for (int i = 0; i < q_size; ++i) {
            results[i] = {0, 0};
        }
        return results;
    }

    std::vector<long long> vals = prices;
    std::sort(vals.begin(), vals.end());
    vals.erase(std::unique(vals.begin(), vals.end()), vals.end());
    int m = vals.size();

    std::vector<Node> tree;
    tree.reserve((n + 1) * 20);
    tree.push_back(Node{0, 0, 0, 0}); // 0-th node is the empty dummy node

    std::vector<int> roots(n + 1, 0);
    for (int i = 0; i < n; ++i) {
        int rank = std::lower_bound(vals.begin(), vals.end(), prices[i]) - vals.begin();
        roots[i + 1] = update(roots[i], 0, m - 1, rank, prices[i], tree);
    }

    for (int i = 0; i < q_size; ++i) {
        auto [l, r, budget] = queries[i];
        int u = roots[l];
        int v = roots[r + 1];

        if (tree[v].sum - tree[u].sum <= budget) {
            results[i] = {tree[v].cnt - tree[u].cnt, tree[v].sum - tree[u].sum};
            continue;
        }

        long long total_cnt = 0;
        long long total_spent = 0;
        long long rem = budget;
        int left = 0, right = m - 1;

        while (left < right) {
            int mid = left + (right - left) / 2;
            int lc_u = tree[u].lc;
            int lc_v = tree[v].lc;
            long long left_sum = tree[lc_v].sum - tree[lc_u].sum;
            int left_cnt = tree[lc_v].cnt - tree[lc_u].cnt;

            if (left_sum <= rem) {
                rem -= left_sum;
                total_spent += left_sum;
                total_cnt += left_cnt;
                u = tree[u].rc;
                v = tree[v].rc;
                left = mid + 1;
            } else {
                u = lc_u;
                v = lc_v;
                right = mid;
            }
        }

        long long price = vals[left];
        long long avail = tree[v].cnt - tree[u].cnt;
        long long take = std::min(avail, rem / price);
        total_cnt += take;
        total_spent += take * price;

        results[i] = {total_cnt, total_spent};
    }

    return results;
}

export function budgetPurchases(prices: number[], queries: [number, number, number][]): [number, number][] {
    const qLen = queries.length;
    if (qLen === 0) {
        return [];
    }
    const n = prices.length;
    if (n === 0) {
        return queries.map(() => [0, 0]);
    }

    // Coordinate compression of prices
    const sortedUnique = Array.from(new Set(prices)).sort((a, b) => a - b);
    const u = sortedUnique.length;

    // Map each price to its rank using binary search
    const ranks = new Int32Array(n);
    for (let i = 0; i < n; i++) {
        const p = prices[i];
        let low = 0;
        let high = u - 1;
        while (low <= high) {
            const mid = (low + high) >>> 1;
            const midVal = sortedUnique[mid];
            if (midVal < p) {
                low = mid + 1;
            } else if (midVal > p) {
                high = mid - 1;
            } else {
                low = mid;
                break;
            }
        }
        ranks[i] = low;
    }

    // Persistent Segment Tree allocation
    // Max depth is ceil(log2(100000)) = 17. Each insertion creates at most 18 nodes.
    const maxNodes = n * 19 + 5;
    const leftChild = new Int32Array(maxNodes);
    const rightChild = new Int32Array(maxNodes);
    const countArr = new Int32Array(maxNodes);
    const sumArr = new Float64Array(maxNodes);

    let nodePtr = 1; // 0 is the null/empty node

    function update(prevRoot: number, l: number, r: number, rank: number, val: number): number {
        const curr = nodePtr++;
        leftChild[curr] = leftChild[prevRoot];
        rightChild[curr] = rightChild[prevRoot];
        countArr[curr] = countArr[prevRoot] + 1;
        sumArr[curr] = sumArr[prevRoot] + val;

        if (l === r) {
            return curr;
        }

        const mid = (l + r) >>> 1;
        if (rank <= mid) {
            leftChild[curr] = update(leftChild[prevRoot], l, mid, rank, val);
        } else {
            rightChild[curr] = update(rightChild[prevRoot], mid + 1, r, rank, val);
        }
        return curr;
    }

    const roots = new Int32Array(n + 1);
    for (let i = 0; i < n; i++) {
        roots[i + 1] = update(roots[i], 0, u - 1, ranks[i], prices[i]);
    }

    const result: [number, number][] = new Array(qLen);

    for (let i = 0; i < qLen; i++) {
        const [ql, qr, budget] = queries[i];
        let remBudget = budget;
        let uNode = roots[ql];
        let vNode = roots[qr + 1];

        const totalAvailableSum = sumArr[vNode] - sumArr[uNode];
        if (totalAvailableSum <= remBudget) {
            result[i] = [countArr[vNode] - countArr[uNode], totalAvailableSum];
            continue;
        }

        let totalCount = 0;
        let totalSpent = 0;
        let l = 0;
        let r = u - 1;

        while (l < r) {
            const mid = (l + r) >>> 1;
            const leftU = leftChild[uNode];
            const leftV = leftChild[vNode];
            const leftSum = sumArr[leftV] - sumArr[leftU];

            if (leftSum <= remBudget) {
                remBudget -= leftSum;
                totalSpent += leftSum;
                totalCount += countArr[leftV] - countArr[leftU];
                uNode = rightChild[uNode];
                vNode = rightChild[vNode];
                l = mid + 1;
            } else {
                uNode = leftU;
                vNode = leftV;
                r = mid;
            }
        }

        // At leaf l === r
        const leafCount = countArr[vNode] - countArr[uNode];
        if (leafCount > 0) {
            const price = sortedUnique[l];
            const canBuy = Math.min(leafCount, Math.floor(remBudget / price));
            totalCount += canBuy;
            totalSpent += canBuy * price;
        }

        result[i] = [totalCount, totalSpent];
    }

    return result;
}

package main

import (
	"math"
)

type Tuple1 struct {
	F0 int
	F1 int
}

const negInf = math.MinInt64 / 2

func CountRecords(levels []int, margin int, queries []Tuple1) []int {
	if len(queries) == 0 {
		return []int{}
	}

	n := len(levels)

	size := 1
	for size < n {
		size <<= 1
	}

	tree := make([]int, 2*size)
	for i := range tree {
		tree[i] = negInf
	}
	for i := 0; i < n; i++ {
		tree[size+i] = levels[i]
	}
	for i := size - 1; i >= 1; i-- {
		left := tree[2*i]
		right := tree[2*i+1]
		if left > right {
			tree[i] = left
		} else {
			tree[i] = right
		}
	}

	findNext := func(startIdx int, target int) int {
		if startIdx >= n {
			return n
		}
		curr := size + startIdx
		for {
			if tree[curr] >= target {
				for curr < size {
					if tree[2*curr] >= target {
						curr = 2 * curr
					} else {
						curr = 2*curr + 1
					}
				}
				res := curr - size
				if res >= n {
					return n
				}
				return res
			}
			for (curr & 1) == 1 {
				curr >>= 1
				if curr == 0 {
					return n
				}
			}
			curr++
		}
	}

	const K = 18
	var up [K][]int
	for k := 0; k < K; k++ {
		up[k] = make([]int, n+1)
	}

	up[0][n] = n
	for i := 0; i < n; i++ {
		up[0][i] = findNext(i+1, levels[i]+margin)
	}

	for k := 1; k < K; k++ {
		prev := up[k-1]
		curr := up[k]
		curr[n] = n
		for i := 0; i < n; i++ {
			curr[i] = prev[prev[i]]
		}
	}

	ans := make([]int, len(queries))
	for qIdx, q := range queries {
		l, r := q.F0, q.F1
		count := 1
		curr := l
		for k := K - 1; k >= 0; k-- {
			nxt := up[k][curr]
			if nxt <= r {
				count += 1 << k
				curr = nxt
			}
		}
		ans[qIdx] = count
	}

	return ans
}

import java.util.*;

public final class Solution {
    public record Tuple1(long f0, long f1) {}

    public static List<Long> countRecords(List<Long> levels, long margin, List<Tuple1> queries) {
        if (queries.isEmpty()) {
            return Collections.emptyList();
        }
        int n = levels.size();
        if (n == 0) {
            return Collections.emptyList();
        }

        long[] arr = new long[n];
        long[] vals = new long[n];
        for (int i = 0; i < n; i++) {
            arr[i] = levels.get(i);
            vals[i] = arr[i];
        }
        Arrays.sort(vals);
        int m = 0;
        for (int i = 0; i < n; i++) {
            if (i == 0 || vals[i] != vals[i - 1]) {
                vals[m++] = vals[i];
            }
        }
        vals = Arrays.copyOf(vals, m);

        int[] bit = new int[m + 2];
        Arrays.fill(bit, n);

        int[] nextRecord = new int[n];
        for (int i = n - 1; i >= 0; i--) {
            long target = arr[i] + margin;
            int idx = lowerBound(vals, target);
            int res = n;
            for (int x = m - idx; x > 0; x -= x & -x) {
                res = Math.min(res, bit[x]);
            }
            nextRecord[i] = res;

            int myIdx = Arrays.binarySearch(vals, arr[i]);
            for (int x = m - myIdx; x <= m; x += x & -x) {
                bit[x] = Math.min(bit[x], i);
            }
        }

        int LOG = 1;
        while ((1 << LOG) <= n) {
            LOG++;
        }

        int[][] up = new int[LOG][n + 1];
        for (int i = 0; i < n; i++) {
            up[0][i] = nextRecord[i];
        }
        up[0][n] = n;

        for (int j = 1; j < LOG; j++) {
            for (int i = 0; i <= n; i++) {
                up[j][i] = up[j - 1][up[j - 1][i]];
            }
        }

        List<Long> ans = new ArrayList<>(queries.size());
        for (Tuple1 q : queries) {
            int l = (int) q.f0();
            int r = (int) q.f1();
            long count = 1;
            int curr = l;
            for (int j = LOG - 1; j >= 0; j--) {
                if (up[j][curr] <= r) {
                    count += (1L << j);
                    curr = up[j][curr];
                }
            }
            ans.add(count);
        }

        return ans;
    }

    private static int lowerBound(long[] a, long key) {
        int low = 0;
        int high = a.length;
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (a[mid] < key) {
                low = mid + 1;
            } else {
                high = mid;
            }
        }
        return low;
    }
}

#include <vector>
#include <tuple>
#include <algorithm>
#include <limits>

std::vector<long long> count_records(
    const std::vector<long long>& levels,
    long long margin,
    const std::vector<std::tuple<long long, long long>>& queries
) {
    if (queries.empty()) {
        return {};
    }

    int n = static_cast<int>(levels.size());
    if (n == 0) {
        return {};
    }

    // For each position i, we need the smallest index j > i such that levels[j] >= levels[i] + margin.
    // We can find this by scanning right-to-left and using a Segment Tree over value coordinates
    // to find the minimum index among values >= levels[i] + margin.

    // Coordinate compression for levels
    std::vector<long long> sorted_vals = levels;
    std::sort(sorted_vals.begin(), sorted_vals.end());
    sorted_vals.erase(std::unique(sorted_vals.begin(), sorted_vals.end()), sorted_vals.end());
    int m = static_cast<int>(sorted_vals.size());

    //Iterative Segment Tree for Range Minimum Query
    int tree_size = 1;
    while (tree_size < m) {
        tree_size *= 2;
    }
    std::vector<int> seg_tree(2 * tree_size, n);

    auto update = [&](int idx, int val) {
        idx += tree_size;
        seg_tree[idx] = std::min(seg_tree[idx], val);
        for (idx /= 2; idx >= 1; idx /= 2) {
            seg_tree[idx] = std::min(seg_tree[2 * idx], seg_tree[2 * idx + 1]);
        }
    };

    auto query_min = [&](int l, int r) {
        int res = n;
        for (l += tree_size, r += tree_size; l <= r; l /= 2, r /= 2) {
            if (l % 2 == 1) res = std::min(res, seg_tree[l++]);
            if (r % 2 == 0) res = std::min(res, seg_tree[r--]);
        }
        return res;
    };

    std::vector<int> next_record(n + 1, n);

    for (int i = n - 1; i >= 0; --i) {
        long long target = levels[i] + margin;
        auto it = std::lower_bound(sorted_vals.begin(), sorted_vals.end(), target);
        if (it != sorted_vals.end()) {
            int rank_target = static_cast<int>(std::distance(sorted_vals.begin(), it));
            next_record[i] = query_min(rank_target, m - 1);
        } else {
            next_record[i] = n;
        }

        int rank_curr = static_cast<int>(std::distance(
            sorted_vals.begin(),
            std::lower_bound(sorted_vals.begin(), sorted_vals.end(), levels[i])
        ));
        update(rank_curr, i);
    }

    // Binary Lifting Table
    int LOGN = 0;
    while ((1 << LOGN) <= n) {
        LOGN++;
    }
    if (LOGN == 0) LOGN = 1;

    std::vector<std::vector<int>> up(LOGN, std::vector<int>(n + 1, n));
    for (int i = 0; i <= n; ++i) {
        up[0][i] = next_record[i];
    }
    for (int k = 1; k < LOGN; ++k) {
        for (int i = 0; i <= n; ++i) {
            up[k][i] = up[k - 1][up[k - 1][i]];
        }
    }

    // Answer Queries
    std::vector<long long> results;
    results.reserve(queries.size());

    for (const auto& q : queries) {
        int l = static_cast<int>(std::get<0>(q));
        int r = static_cast<int>(std::get<1>(q));

        long long count = 1; // levels[l] is always a record
        int curr = l;
        for (int k = LOGN - 1; k >= 0; --k) {
            if (up[k][curr] <= r) {
                curr = up[k][curr];
                count += (1LL << k);
            }
        }
        results.push_back(count);
    }

    return results;
}

export function countRecords(levels: number[], margin: number, queries: [number, number][]): number[] {
    const qLen = queries.length;
    if (qLen === 0) {
        return [];
    }

    const n = levels.length;
    if (n === 0) {
        return [];
    }

    // 1. Build segment tree for finding the first element >= target after a given index
    let M = 1;
    while (M < n) {
        M <<= 1;
    }

    const tree = new Float64Array(2 * M);
    tree.fill(-Infinity);
    for (let i = 0; i < n; i++) {
        tree[M + i] = levels[i];
    }
    for (let i = M - 1; i >= 1; i--) {
        const left = tree[2 * i];
        const right = tree[2 * i + 1];
        tree[i] = left > right ? left : right;
    }

    // 2. Find the next record position for each index i
    const nextRec = new Int32Array(n + 1);
    nextRec[n] = n;

    for (let i = 0; i < n; i++) {
        const target = levels[i] + margin;
        let curr = M + i;
        let foundNode = -1;

        while (curr > 1) {
            if ((curr & 1) === 0) { // curr is a left child
                const sibling = curr + 1;
                if (tree[sibling] >= target) {
                    foundNode = sibling;
                    break;
                }
            }
            curr >>= 1;
        }

        if (foundNode === -1) {
            nextRec[i] = n;
        } else {
            while (foundNode < M) {
                const leftChild = foundNode << 1;
                if (tree[leftChild] >= target) {
                    foundNode = leftChild;
                } else {
                    foundNode = leftChild + 1;
                }
            }
            const idx = foundNode - M;
            nextRec[i] = idx < n ? idx : n;
        }
    }

    // 3. Build binary lifting table
    let LOG = 1;
    while ((1 << LOG) <= n) {
        LOG++;
    }

    const stride = n + 1;
    const up = new Int32Array(LOG * stride);
    up.set(nextRec, 0);

    for (let k = 1; k < LOG; k++) {
        const prevOffset = (k - 1) * stride;
        const currOffset = k * stride;
        for (let i = 0; i <= n; i++) {
            up[currOffset + i] = up[prevOffset + up[prevOffset + i]];
        }
    }

    // 4. Answer queries
    const ans = new Array<number>(qLen);
    for (let q = 0; q < qLen; q++) {
        let curr = queries[q][0];
        const r = queries[q][1];
        let count = 1;

        for (let k = LOG - 1; k >= 0; k--) {
            const nxt = up[k * stride + curr];
            if (nxt <= r) {
                count += 1 << k;
                curr = nxt;
            }
        }
        ans[q] = count;
    }

    return ans;
}

package main

import (
	"errors"
	"math/big"
	"strings"
)

type Tuple1 struct {
	F0 string
	F1 string
	F2 string
}

func isASCIIOnlyDigits(s string) bool {
	if len(s) == 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] < '0' || s[i] > '9' {
			return false
		}
	}
	return true
}

func parseCents(s string) (*big.Int, error) {
	parts := strings.Split(s, ".")
	if len(parts) > 2 {
		return nil, errors.New("invalid principal format")
	}
	intPart := parts[0]
	if !isASCIIOnlyDigits(intPart) {
		return nil, errors.New("invalid principal int part")
	}
	fracPart := ""
	if len(parts) == 2 {
		fracPart = parts[1]
		if len(fracPart) < 1 || len(fracPart) > 2 || !isASCIIOnlyDigits(fracPart) {
			return nil, errors.New("invalid principal frac part")
		}
	}
	for len(fracPart) < 2 {
		fracPart += "0"
	}
	val, ok := new(big.Int).SetString(intPart+fracPart, 10)
	if !ok {
		return nil, errors.New("failed to parse principal")
	}
	if val.Cmp(big.NewInt(0)) <= 0 {
		return nil, errors.New("principal must be > 0")
	}
	return val, nil
}

func parseRateMicro(s string) (*big.Int, error) {
	parts := strings.Split(s, ".")
	if len(parts) > 2 {
		return nil, errors.New("invalid rate format")
	}
	intPart := parts[0]
	if !isASCIIOnlyDigits(intPart) {
		return nil, errors.New("invalid rate int part")
	}
	fracPart := ""
	if len(parts) == 2 {
		fracPart = parts[1]
		if len(fracPart) < 1 || len(fracPart) > 6 || !isASCIIOnlyDigits(fracPart) {
			return nil, errors.New("invalid rate frac part")
		}
	}
	for len(fracPart) < 6 {
		fracPart += "0"
	}
	val, ok := new(big.Int).SetString(intPart+fracPart, 10)
	if !ok {
		return nil, errors.New("failed to parse rate")
	}
	maxRate := big.NewInt(100_000_000)
	if val.Cmp(big.NewInt(0)) < 0 || val.Cmp(maxRate) > 0 {
		return nil, errors.New("rate out of bounds")
	}
	return val, nil
}

func formatCents(c *big.Int) string {
	s := c.String()
	if len(s) == 1 {
		return "0.0" + s
	} else if len(s) == 2 {
		return "0." + s
	}
	return s[:len(s)-2] + "." + s[len(s)-2:]
}

func Amortize(principal string, annual_rate_pct string, months int) ([]Tuple1, error) {
	if months < 1 || months > 1200 {
		return nil, errors.New("months out of bounds")
	}

	P_cents, err := parseCents(principal)
	if err != nil {
		return nil, err
	}

	R_micro, err := parseRateMicro(annual_rate_pct)
	if err != nil {
		return nil, err
	}

	m_num := new(big.Int).Set(R_micro)
	m_den := big.NewInt(1_200_000_000)

	g := new(big.Int).GCD(nil, nil, m_num, m_den)
	m_num.Div(m_num, g)
	m_den.Div(m_den, g)

	var PAY_cents *big.Int
	zero := big.NewInt(0)
	one := big.NewInt(1)

	if m_num.Cmp(zero) == 0 {
		n_big := big.NewInt(int64(months))
		num := new(big.Int).Add(P_cents, n_big)
		num.Sub(num, one)
		PAY_cents = num.Div(num, n_big)
	} else {
		u := new(big.Int).Add(m_den, m_num)
		v := new(big.Int).Set(m_den)
		n_big := big.NewInt(int64(months))

		un := new(big.Int).Exp(u, n_big, nil)
		vn := new(big.Int).Exp(v, n_big, nil)

		num := new(big.Int).Mul(P_cents, m_num)
		num.Mul(num, un)

		sub := new(big.Int).Sub(un, vn)
		den := new(big.Int).Mul(m_den, sub)

		PAY_cents = new(big.Int).Add(num, den)
		PAY_cents.Sub(PAY_cents, one)
		PAY_cents.Div(PAY_cents, den)
	}

	BAL := new(big.Int).Set(P_cents)
	var rows []Tuple1
	two := big.NewInt(2)

	for t := 1; t <= months; t++ {
		num := new(big.Int).Mul(BAL, m_num)
		q := new(big.Int).
			r := new(big.Int)
		q.QuoRem(num, m_den, r)

		r2 := new(big.Int).Mul(r, two)
		cmp := r2.Cmp(m_den)
		var INTEREST *big.Int
		if cmp < 0 {
			INTEREST = q
		} else if cmp > 0 {
			INTEREST = new(big.Int).Add(q, one)
		} else {
			if q.Bit(0) == 0 {
				INTEREST = q
			} else {
				INTEREST = new(big.Int).Add(q, one)
			}
		}

		balPlusInt := new(big.Int).Add(BAL, INTEREST)
		if t == months || balPlusInt.Cmp(PAY_cents) <= 0 {
			payment := balPlusInt
			BAL = big.NewInt(0)
			rows = append(rows, Tuple1{
				F0: formatCents(payment),
				F1: formatCents(INTEREST),
				F2: formatCents(BAL),
			})
			break
		} else {
			payment := PAY_cents
			diff := new(big.Int).Sub(PAY_cents, INTEREST)
			BAL.Sub(BAL, diff)
			rows = append(rows, Tuple1{
				F0: formatCents(payment),
				F1: formatCents(INTEREST),
				F2: formatCents(BAL),
			})
		}
	}

	return rows, nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    public record Tuple1(String f0, String f1, String f2) {}

    public static List<Tuple1> amortize(String principal, String annual_rate_pct, long months) {
        if (principal == null || annual_rate_pct == null) {
            throw new IllegalArgumentException("Inputs cannot be null");
        }
        if (months < 1 || months > 1200) {
            throw new IllegalArgumentException("Invalid months");
        }
        int n = (int) months;

        BigInteger P_cents = parseDecimal(principal, 2);
        if (P_cents.compareTo(BigInteger.ZERO) <= 0) {
            throw new IllegalArgumentException("Principal must be > 0");
        }

        BigInteger R = parseDecimal(annual_rate_pct, 6);
        BigInteger maxRate = BigInteger.valueOf(100_000_000L);
        if (R.compareTo(maxRate) > 0) {
            throw new IllegalArgumentException("Annual rate must be <= 100");
        }

        // m = R / 1_200_000_000
        BigInteger D = BigInteger.valueOf(1_200_000_000L);
        BigInteger g = R.gcd(D);
        BigInteger p = R.divide(g);
        BigInteger q = D.divide(g);

        BigInteger PAY_cents;
        if (p.equals(BigInteger.ZERO)) {
            BigInteger nBI = BigInteger.valueOf(n);
            BigInteger[] qr = P_cents.divideAndRemainder(nBI);
            PAY_cents = qr[1].equals(BigInteger.ZERO) ? qr[0] : qr[0].add(BigInteger.ONE);
        } else {
            // A_cents = P_cents * m / (1 - (1 + m)^(-n))
            // 1 + m = (q + p) / q
            // A_cents = P_cents * p * (q + p)^n / (q * ((q + p)^n - q^n))
            BigInteger qp = q.add(p);
            BigInteger qp_n = qp.pow(n);
            BigInteger q_n = q.pow(n);
            BigInteger num = P_cents.multiply(p).multiply(qp_n);
            BigInteger den = q.multiply(qp_n.subtract(q_n));
            BigInteger[] qr = num.divideAndRemainder(den);
            PAY_cents = qr[1].equals(BigInteger.ZERO) ? qr[0] : qr[0].add(BigInteger.ONE);
        }

        List<Tuple1> schedule = new ArrayList<>(n);
        BigInteger bal = P_cents;
        BigInteger two = BigInteger.valueOf(2);

        for (int t = 1; t <= n; t++) {
            // INTEREST = round_half_even(bal * p / q)
            BigInteger num = bal.multiply(p);
            BigInteger[] qr = num.divideAndRemainder(q);
            BigInteger interest = qr[0];
            BigInteger rem = qr[1];
            int cmp = rem.multiply(two).compareTo(q);
            if (cmp > 0) {
                interest = interest.add(BigInteger.ONE);
            } else if (cmp == 0) {
                if (interest.testBit(0)) { // is odd
                    interest = interest.add(BigInteger.ONE);
                }
            }

            BigInteger totalDue = bal.add(interest);
            if (t == n || totalDue.compareTo(PAY_cents) <= 0) {
                BigInteger payment = totalDue;
                bal = BigInteger.ZERO;
                schedule.add(new Tuple1(formatCents(payment), formatCents(interest), formatCents(bal)));
                break;
            } else {
                BigInteger payment = PAY_cents;
                bal = totalDue.subtract(payment);
                schedule.add(new Tuple1(formatCents(payment), formatCents(interest), formatCents(bal)));
            }
        }

        return schedule;
    }

    private static BigInteger parseDecimal(String s, int maxFracDigits) {
        if (s.isEmpty()) {
            throw new IllegalArgumentException("Empty string");
        }
        int dotIndex = -1;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '.') {
                if (dotIndex != -1) {
                    throw new IllegalArgumentException("Multiple decimal points");
                }
                dotIndex = i;
            } else if (c < '0' || c > '9') {
                throw new IllegalArgumentException("Invalid character: " + c);
            }
        }

        String intPart;
        String fracPart;
        if (dotIndex == -1) {
            intPart = s;
            fracPart = "";
        } else {
            intPart = s.substring(0, dotIndex);
            fracPart = s.substring(dotIndex + 1);
            if (fracPart.isEmpty() || fracPart.length() > maxFracDigits) {
                throw new IllegalArgumentException("Invalid fractional part length");
            }
        }

        if (intPart.isEmpty()) {
            throw new IllegalArgumentException("Missing integer part");
        }

        StringBuilder sb = new StringBuilder(intPart);
        sb.append(fracPart);
        for (int i = fracPart.length(); i < maxFracDigits; i++) {
            sb.append('0');
        }
        return new BigInteger(sb.toString());
    }

    private static String formatCents(BigInteger cents) {
        BigInteger[] qr = cents.divideAndRemainder(BigInteger.valueOf(100));
        long rem = qr[1].longValue();
        return String.format("%s.%02d", qr[0].toString(), rem);
    }
}

#include <iostream>
#include <vector>
#include <string>
#include <tuple>
#include <stdexcept>
#include <cctype>
#include <algorithm>
#include <numeric>
#include <iomanip>
#include <sstream>

namespace {

using u64 = unsigned long long;
using u128 = __uint128_t;

constexpr u64 BASE = 1000000000ULL;

struct BigInt {
    std::vector<u64> d; // little-endian base 10^9

    BigInt() {}
    BigInt(u64 v) {
        while (v > 0) {
            d.push_back(v % BASE);
            v /= BASE;
        }
    }

    bool is_zero() const { return d.empty(); }

    void trim() {
        while (!d.empty() && d.back() == 0) {
            d.pop_back();
        }
    }

    int cmp(const BigInt& o) const {
        if (d.size() != o.d.size()) {
            return d.size() < o.d.size() ? -1 : 1;
        }
        for (int i = (int)d.size() - 1; i >= 0; --i) {
            if (d[i] != o.d[i]) {
                return d[i] < o.d[i] ? -1 : 1;
            }
        }
        return 0;
    }

    bool operator<(const BigInt& o) const { return cmp(o) < 0; }
    bool operator<=(const BigInt& o) const { return cmp(o) <= 0; }
    bool operator>(const BigInt& o) const { return cmp(o) > 0; }
    bool operator>=(const BigInt& o) const { return cmp(o) >= 0; }
    bool operator==(const BigInt& o) const { return cmp(o) == 0; }
    bool operator!=(const BigInt& o) const { return cmp(o) != 0; }

    BigInt operator+(const BigInt& o) const {
        BigInt res;
        size_t n = std::max(d.size(), o.d.size());
        res.d.resize(n, 0);
        u64 carry = 0;
        for (size_t i = 0; i < n; ++i) {
            u64 sum = carry;
            if (i < d.size()) sum += d[i];
            if (i < o.d.size()) sum += o.d[i];
            res.d[i] = sum % BASE;
            carry = sum / BASE;
        }
        if (carry > 0) res.d.push_back(carry);
        return res;
    }

    // Assumes *this >= o
    BigInt operator-(const BigInt& o) const {
        BigInt res;
        res.d.resize(d.size(), 0);
        long long borrow = 0;
        for (size_t i = 0; i < d.size(); ++i) {
            long long diff = (long long)d[i] - borrow - (i < o.d.size() ? (long long)o.d[i] : 0);
            if (diff < 0) {
                diff += BASE;
                borrow = 1;
            } else {
                borrow = 0;
            }
            res.d[i] = (u64)diff;
        }
        res.trim();
        return res;
    }

    BigInt operator*(u64 v) const {
        if (v == 0 || is_zero()) return BigInt();
        BigInt res;
        res.d.resize(d.size(), 0);
        u128 carry = 0;
        for (size_t i = 0; i < d.size(); ++i) {
            u128 prod = (u128)d[i] * v + carry;
            res.d[i] = (u64)(prod % BASE);
            carry = prod / BASE;
        }
        while (carry > 0) {
            res.d.push_back((u64)(carry % BASE));
            carry /= BASE;
        }
        return res;
    }

    BigInt operator*(const BigInt& o) const {
        if (is_zero() || o.is_zero()) return BigInt();
        BigInt res;
        res.d.assign(d.size() + o.d.size(), 0);
        for (size_t i = 0; i < d.size(); ++i) {
            u128 carry = 0;
            for (size_t j = 0; j < o.d.size(); ++j) {
                u128 cur = res.d[i + j] + (u128)d[i] * o.d[j] + carry;
                res.d[i + j] = (u64)(cur % BASE);
                carry = cur / BASE;
            }
            size_t k = i + o.d.size();
            while (carry > 0) {
                u128 cur = res.d[k] + carry;
                res.d[k] = (u64)(cur % BASE);
                carry = cur / BASE;
                k++;
            }
        }
        res.trim();
        return res;
    }

    std::pair<BigInt, u64> divmod(u64 v) const {
        if (v == 0) throw std::invalid_argument("Division by zero");
        BigInt q;
        q.d.resize(d.size(), 0);
        u128 rem = 0;
        for (int i = (int)d.size() - 1; i >= 0; --i) {
            u128 cur = rem * BASE + d[i];
            q.d[i] = (u64)(cur / v);
            rem = cur % v;
        }
        q.trim();
        return {q, (u64)rem};
    }

    static std::pair<BigInt, BigInt> divmod(const BigInt& A, const BigInt& B) {
        if (B.is_zero()) throw std::invalid_argument("Division by zero");
        if (A < B) return {BigInt(0), A};
        if (B.d.size() == 1) {
            auto [q, r] = A.divmod(B.d[0]);
            return {q, BigInt(r)};
        }

        u64 norm = BASE / (B.d.back() + 1);
        BigInt a = A * norm;
        BigInt b = B * norm;

        size_t n = b.d.size();
        size_t m = a.d.size() - n;

        BigInt q;
        q.d.resize(m + 1, 0);

        for (int j = (int)m; j >= 0; --j) {
            u128 a_hi = (j + n < a.d.size()) ? a.d[j + n] : 0;
            u128 a_lo = (j + n - 1 < a.d.size()) ? a.d[j + n - 1] : 0;
            u128 num = a_hi * BASE + a_lo;
            u128 q_hat = num / b.d[n - 1];
            u128 r_hat = num % b.d[n - 1];

            while (q_hat == BASE || (n >= 2 && q_hat * b.d[n - 2] > BASE * r_hat + (j + n - 2 < a.d.size() ? a.d[j + n - 2] : 0))) {
                q_hat--;
                r_hat += b.d[n - 1];
                if (r_hat >= BASE) break;
            }

            BigInt sub = b * (u64)q_hat;
            // Shift sub by j
            BigInt sub_shifted;
            if (!sub.is_zero()) {
                sub_shifted.d.resize(j, 0);
                sub_shifted.d.insert(sub_shifted.d.end(), sub.d.begin(), sub.d.end());
            }

            while (a < sub_shifted) {
                q_hat--;
                sub_shifted = sub_shifted - (b.is_zero() ? BigInt() : [&]() {
                    BigInt b_sh;
                    b_sh.d.resize(j, 0);
                    b_sh.d.insert(b_sh.d.end(), b.d.begin(), b.d.end());
                    return b_sh;
                }());
            }
            a = a - sub_shifted;
            q.d[j] = (u64)q_hat;
        }

        q.trim();
        auto [r, rem_zero] = a.divmod(norm);
        return {q, r};
    }

    static BigInt power(BigInt base, long long exp) {
        BigInt res(1);
        while (exp > 0) {
            if (exp % 2 == 1) res = res * base;
            base = base * base;
            exp /= 2;
        }
        return res;
    }

    static BigInt from_string(const std::string& s) {
        BigInt res(0);
        for (char c : s) {
            res = res * 10 + BigInt(c - '0');
        }
        return res;
    }

    std::string to_string() const {
        if (is_zero()) return "0";
        std::ostringstream oss;
        oss << d.back();
        for (int i = (int)d.size() - 2; i >= 0; --i) {
            oss << std::setw(9) << std::setfill('0') << d[i];
        }
        return oss.str();
    }

    bool is_odd() const {
        if (is_zero()) return false;
        return (d[0] % 2) != 0;
    }
};

std::string format_cents(const BigInt& c) {
    std::string s = c.to_string();
    if (s.length() == 1) return "0.0" + s;
    if (s.length() == 2) return "0." + s;
    return s.substr(0, s.length() - 2) + "." + s.substr(s.length() - 2);
}

BigInt parse_principal(const std::string& s) {
    if (s.empty()) throw std::invalid_argument("Empty principal");
    size_t dot = s.find('.');
    std::string int_part, frac_part;
    if (dot == std::string::npos) {
        int_part = s;
        frac_part = "";
    } else {
        int_part = s.substr(0, dot);
        frac_part = s.substr(dot + 1);
        if (frac_part.empty() || frac_part.length() > 2) {
            throw std::invalid_argument("Invalid principal fraction");
        }
    }
    if (int_part.empty()) throw std::invalid_argument("Empty principal integer part");
    for (char c : int_part) if (c < '0' || c > '9') throw std::invalid_argument("Invalid digit in principal");
    for (char c : frac_part) if (c < '0' || c > '9') throw std::invalid_argument("Invalid digit in principal");

    while (frac_part.length() < 2) frac_part += '0';
    BigInt res = BigInt::from_string(int_part + frac_part);
    if (res.is_zero()) throw std::invalid_argument("Principal must be > 0");
    return res;
}

u64 parse_rate(const std::string& s) {
    if (s.empty()) throw std::invalid_argument("Empty rate");
    size_t dot = s.find('.');
    std::string int_part, frac_part;
    if (dot == std::string::npos) {
        int_part = s;
        frac_part = "";
    } else {
        int_part = s.substr(0, dot);
        frac_part = s.substr(dot + 1);
        if (frac_part.empty() || frac_part.length() > 6) {
            throw std::invalid_argument("Invalid rate fraction");
        }
    }
    if (int_part.empty()) throw std::invalid_argument("Empty rate integer part");
    for (char c : int_part) if (c < '0' || c > '9') throw std::invalid_argument("Invalid digit in rate");
    for (char c : frac_part) if (c < '0' || c > '9') throw std::invalid_argument("Invalid digit in rate");

    while (frac_part.length() < 6) frac_part += '0';
    BigInt res = BigInt::from_string(int_part + frac_part);
    BigInt max_rate(100000000ULL);
    if (res > max_rate) throw std::invalid_argument("Rate > 100");
    if (res.is_zero()) return 0;
    return res.d[0];
}

} // namespace

std::vector<std::tuple<std::string, std::string, std::string>> amortize(
    const std::string& principal, const std::string& annual_rate_pct, long long months) {

    if (months < 1 || months > 1200) {
        throw std::invalid_argument("Invalid months");
    }

    BigInt P = parse_principal(principal);
    u64 R = parse_rate(annual_rate_pct);

    u64 D = 1200000000ULL;
    u64 g = std::gcd(R, D);
    u64 p = R / g;
    u64 q = D / g;

    BigInt PAY;
    if (p == 0) {
        auto [quot, rem] = P.divmod((u64)months);
        PAY = rem == 0 ? quot : quot + BigInt(1);
    } else {
        BigInt qp = BigInt(q + p);
        BigInt q_bi = BigInt(q);
        BigInt pow_qp = BigInt::power(qp, months);
        BigInt pow_q = BigInt::power(q_bi, months);
        BigInt num = P * p * pow_qp;
        BigInt den = q_bi * (pow_qp - pow_q);
        auto [quot, rem] = BigInt::divmod(num, den);
        PAY = rem.is_zero() ? quot : quot + BigInt(1);
    }

    std::vector<std::tuple<std::string, std::string, std::string>> schedule;
    schedule.reserve(months);

    BigInt BAL = P;
    for (long long t = 1; t <= months; ++t) {
        BigInt num = BAL * p;
        auto [I_quot, I_rem] = num.divmod(q);
        BigInt INTEREST = I_quot;

        u128 twice_rem = (u128)I_rem * 2;
        if (twice_rem > q) {
            INTEREST = INTEREST + BigInt(1);
        } else if (twice_rem == q) {
            if (INTEREST.is_odd()) {
                INTEREST = INTEREST + BigInt(1);
            }
        }

        BigInt total_due = BAL + INTEREST;
        if (t == months || total_due <= PAY) {
            BigInt payment = total_due;
            BAL = BigInt(0);
            schedule.emplace_back(format_cents(payment), format_cents(INTEREST), format_cents(BAL));
            break;
        } else {
            BigInt payment = PAY;
            BAL = total_due - PAY;
            schedule.emplace_back(format_cents(payment), format_cents(INTEREST), format_cents(BAL));
        }
    }

    return schedule;
}

function gcd(a: bigint, b: bigint): bigint {
    while (b !== 0n) {
        const t = b;
        b = a % b;
        a = t;
    }
    return a;
}

function formatCents(cents: bigint): string {
    const q = cents / 100n;
    const r = cents % 100n;
    return `${q}.${r.toString().padStart(2, '0')}`;
}

export function amortize(principal: string, annual_rate_pct: string, months: number): [string, string, string][] {
    if (typeof principal !== 'string' || !/^[0-9]+(\.[0-9]{1,2})?$/.test(principal)) {
        throw new Error("Invalid principal");
    }
    if (typeof annual_rate_pct !== 'string' || !/^[0-9]+(\.[0-9]{1,6})?$/.test(annual_rate_pct)) {
        throw new Error("Invalid annual_rate_pct");
    }
    if (typeof months !== 'number' || !Number.isInteger(months) || months < 1 || months > 1200) {
        throw new Error("Invalid months");
    }

    const pParts = principal.split('.');
    const pFrac = (pParts[1] ?? '').padEnd(2, '0');
    const P_cents = BigInt(pParts[0]) * 100n + BigInt(pFrac);
    if (P_cents <= 0n) {
        throw new Error("Principal must be > 0");
    }

    const rParts = annual_rate_pct.split('.');
    const rFrac = (rParts[1] ?? '').padEnd(6, '0');
    const R_micro = BigInt(rParts[0]) * 1000000n + BigInt(rFrac);
    if (R_micro > 100000000n) {
        throw new Error("Annual rate must be <= 100");
    }

    const n = BigInt(months);

    // m = R_micro / (12 * 10^8) = R_micro / 1_200_000_000
    const m_num_raw = R_micro;
    const m_den_raw = 1200000000n;
    const g = gcd(m_num_raw, m_den_raw);
    const num = m_num_raw / g;
    const den = m_den_raw / g;

    let PAY_cents: bigint;
    if (num === 0n) {
        PAY_cents = (P_cents + n - 1n) / n;
    } else {
        // 1 + m = (den + num) / den
        // A_cents = P_cents * m / (1 - (den / (den + num))^n)
        //         = P_cents * (num / den) * (den + num)^n / ((den + num)^n - den^n)
        const base1 = den + num;
        const base2 = den;
        const pow1 = base1 ** n;
        const pow2 = base2 ** n;

        const A_num = P_cents * num * pow1;
        const A_den = den * (pow1 - pow2);
        PAY_cents = (A_num + A_den - 1n) / A_den;
    }

    const schedule: [string, string, string][] = [];
    let BAL = P_cents;

    for (let t = 1; t <= months; t++) {
        // INTEREST = round_half_even(BAL * num / den)
        const prod = BAL * num;
        const q = prod / den;
        const rem = prod % den;
        const twice_rem = rem * 2n;

        let INTEREST = q;
        if (twice_rem > den) {
            INTEREST = q + 1n;
        } else if (twice_rem === den) {
            if (q % 2n === 1n) {
                INTEREST = q + 1n;
            }
        }

        if (t === months || BAL + INTEREST <= PAY_cents) {
            const payment = BAL + INTEREST;
            BAL = 0n;
            schedule.push([formatCents(payment), formatCents(INTEREST), formatCents(BAL)]);
            break;
        } else {
            const payment = PAY_cents;
            BAL = BAL - (PAY_cents - INTEREST);
            schedule.push([formatCents(payment), formatCents(INTEREST), formatCents(BAL)]);
        }
    }

    return schedule;
}

package main

import (
	"errors"
	"math/big"
	"strconv"
	"strings"
)

func FormatBase(p int, q int, base int, k int) (string, error) {
	if q == 0 || base < 2 || base > 36 || k < 0 {
		return "", errors.New("invalid argument")
	}

	if p == 0 {
		return "0", nil
	}

	neg := (p < 0) != (q < 0)
	P := new(big.Int).Abs(big.NewInt(int64(p)))
	Q := new(big.Int).Abs(big.NewInt(int64(q)))
	B := big.NewInt(int64(base))

	// Integer part before rounding: I = P // Q, rem = P % Q
	I := new(big.Int)
	rem := new(big.Int)
	I.QuoRem(P, Q, rem)

	// Fractional part: M = (rem * base^k) // Q, r = (rem * base^k) % Q
	Bk := new(big.Int).Exp(B, big.NewInt(int64(k)), nil)
	remBk := new(big.Int).Mul(rem, Bk)
	M := new(big.Int)
	r := new(big.Int)
	M.QuoRem(remBk, Q, r)

	// Rounding: compare 2*r with Q
	twoR := new(big.Int).Lsh(r, 1)
	cmp := twoR.Cmp(Q)
	roundUp := false
	if cmp > 0 {
		roundUp = true
	} else if cmp == 0 {
		// Tie-breaking: N = I * base^k + M must be even.
		// N is odd iff (I * base^k + M) is odd.
		mOdd := M.Bit(0) == 1
		var iBkOdd bool
		if k == 0 {
			iBkOdd = I.Bit(0) == 1
		} else {
			if base%2 == 0 {
				iBkOdd = false
			} else {
				iBkOdd = I.Bit(0) == 1
			}
		}
		if iBkOdd != mOdd { // N is odd
			roundUp = true
		}
	}

	if roundUp {
		M.Add(M, big.NewInt(1))
		if M.Cmp(Bk) >= 0 {
			M.Sub(M, Bk)
			I.Add(I, big.NewInt(1))
		}
	}

	if I.Sign() == 0 && M.Sign() == 0 {
		return "0", nil
	}

	var sb strings.Builder
	if neg {
		sb.WriteByte('-')
	}
	sb.WriteString(strconv.FormatUint(I.Uint64(), base))

	if k > 0 && M.Sign() > 0 {
		sb.WriteByte('.')
		fracStr := M.Text(base)
		if len(fracStr) < k {
			sb.WriteString(strings.Repeat("0", k-len(fracStr)))
		}
		// Trim trailing zeros
		fracStr = strings.TrimRight(fracStr, "0")
		sb.WriteString(fracStr)
	}

	return sb.String(), nil
}

import java.math.BigInteger;
import java.util.*;

public final class Solution {
    public static String formatBase(long p, long q, long base, long k) {
        if (q == 0 || base < 2 || base > 36 || k < 0) {
            throw new IllegalArgumentException();
        }
        if (p == 0) {
            return "0";
        }

        boolean negative = (p < 0) ^ (q < 0);
        BigInteger P = BigInteger.valueOf(p).abs();
        BigInteger Q = BigInteger.valueOf(q).abs();
        int b = (int) base;
        int K = (int) k;

        BigInteger[] qr = P.divideAndRemainder(Q);
        BigInteger intPart = qr[0];
        BigInteger rem = qr[1];

        int[] fracDigits = new int[K];

        // Since q fits in long, when rem fits in long we can do standard 64-bit arithmetic
        // if rem * base doesn't overflow. Actually, using BigInteger or unsigned math is fast enough,
        // or we can switch to primitive long if Q <= Long.MAX_VALUE / 36.
        if (K > 0) {
            if (Q.compareTo(BigInteger.valueOf(Long.MAX_VALUE / 36)) <= 0) {
                long qLong = Q.longValue();
                long rLong = rem.longValue();
                for (int i = 0; i < K; i++) {
                    if (rLong == 0) break;
                    long num = rLong * b;
                    fracDigits[i] = (int) (num / qLong);
                    rLong = num % qLong;
                }
                rem = BigInteger.valueOf(rLong);
            } else {
                BigInteger B = BigInteger.valueOf(b);
                for (int i = 0; i < K; i++) {
                    if (rem.signum() == 0) break;
                    BigInteger num = rem.multiply(B);
                    BigInteger[] d = num.divideAndRemainder(Q);
                    fracDigits[i] = d[0].intValue();
                    rem = d[1];
                }
            }
        }

        // Now N = floor(|x| * base^k) is represented by intPart and fracDigits.
        // The fractional remainder of |x| * base^k is rem / Q.
        // We compare 2 * rem with Q for rounding.
        BigInteger twiceRem = rem.shiftLeft(1);
        int cmp = twiceRem.compareTo(Q);
        boolean roundUp = false;
        if (cmp > 0) {
            roundUp = true;
        } else if (cmp == 0) {
            // Tie-breaking: round to even N.
            // Determine parity of N.
            boolean isOdd;
            if (b % 2 == 0) {
                if (K > 0) {
                    isOdd = (fracDigits[K - 1] & 1) != 0;
                } else {
                    isOdd = intPart.testBit(0);
                }
            } else {
                // Base is odd, parity of N is parity of (intPart + sum of fracDigits)
                long sum = intPart.testBit(0) ? 1 : 0;
                for (int d : fracDigits) {
                    sum += d;
                }
                isOdd = (sum & 1) != 0;
            }
            if (isOdd) {
                roundUp = true;
            }
        }

        if (roundUp) {
            int carry = 1;
            for (int i = K - 1; i >= 0 && carry > 0; i--) {
                int val = fracDigits[i] + carry;
                if (val == b) {
                    fracDigits[i] = 0;
                    carry = 1;
                } else {
                    fracDigits[i] = val;
                    carry = 0;
                }
            }
            if (carry > 0) {
                intPart = intPart.add(BigInteger.ONE);
            }
        }

        // Find last non-zero fractional digit
        int lastNonZero = -1;
        for (int i = K - 1; i >= 0; i--) {
            if (fracDigits[i] != 0) {
                lastNonZero = i;
                break;
            }
        }

        if (intPart.signum() == 0 && lastNonZero == -1) {
            return "0";
        }

        String intStr = intPart.toString(b);
        int totalLen = intStr.length() + (negative ? 1 : 0) + (lastNonZero >= 0 ? 1 + lastNonZero + 1 : 0);
        StringBuilder sb = new StringBuilder(totalLen);

        if (negative) {
            sb.append('-');
        }
        sb.append(intStr);

        if (lastNonZero >= 0) {
            sb.append('.');
            for (int i = 0; i <= lastNonZero; i++) {
                sb.append(Character.forDigit(fracDigits[i], b));
            }
        }

        return sb.toString();
    }
}

#include <string>
#include <vector>
#include <stdexcept>
#include <algorithm>
