std::string format_base(long long p, long long q, long long base, long long k) {
    if (q == 0 || base < 2 || base > 36 || k < 0) {
        throw std::invalid_argument("Invalid arguments");
    }

    if (p == 0) {
        return "0";
    }

    bool negative = (p < 0) ^ (q < 0);
    unsigned __int128 up = p < 0 ? -static_cast<unsigned __int128>(p) : static_cast<unsigned __int128>(p);
    unsigned __int128 uq = q < 0 ? -static_cast<unsigned __int128>(q) : static_cast<unsigned __int128>(q);
    unsigned __int128 ubase = static_cast<unsigned __int128>(base);

    // Integer part I = floor(|p| / |q|)
    unsigned __int128 I = up / uq;
    unsigned __int128 rem = up % uq;

    std::vector<int> int_digits; // least significant digit first
    if (I == 0) {
        int_digits.push_back(0);
    } else {
        unsigned __int128 temp = I;
        while (temp > 0) {
            int_digits.push_back(static_cast<int>(temp % ubase));
            temp /= ubase;
        }
    }

    std::vector<int> frac_digits(k, 0); // most significant fractional digit first
    for (long long i = 0; i < k; ++i) {
        if (rem == 0) break;
        rem *= ubase;
        frac_digits[i] = static_cast<int>(rem / uq);
        rem %= uq;
    }

    // Determine parity of M = floor(|x| * base^k)
    int parity = 0;
    if (base % 2 == 0) {
        if (k == 0) {
            parity = static_cast<int>(I & 1);
        } else {
            parity = frac_digits[k - 1] & 1;
        }
    } else {
        parity = static_cast<int>(I & 1);
        for (long long i = 0; i < k; ++i) {
            parity ^= (frac_digits[i] & 1);
        }
    }

    // Round-to-even logic
    unsigned __int128 twice_rem = rem * 2;
    bool round_up = false;
    if (twice_rem > uq) {
        round_up = true;
    } else if (twice_rem == uq) {
        if (parity == 1) {
            round_up = true;
        }
    }

    // Propagate carry if rounding up
    if (round_up) {
        int carry = 1;
        for (long long i = k - 1; i >= 0 && carry > 0; --i) {
            int val = frac_digits[i] + carry;
            frac_digits[i] = val % static_cast<int>(base);
            carry = val / static_cast<int>(base);
        }
        for (size_t i = 0; i < int_digits.size() && carry > 0; ++i) {
            int val = int_digits[i] + carry;
            int_digits[i] = val % static_cast<int>(base);
            carry = val / static_cast<int>(base);
        }
        if (carry > 0) {
            int_digits.push_back(carry);
        }
    }

    // Check if rounded magnitude N is 0
    bool is_zero = (int_digits.size() == 1 && int_digits[0] == 0);
    if (is_zero) {
        for (long long i = 0; i < k; ++i) {
            if (frac_digits[i] != 0) {
                is_zero = false;
                break;
            }
        }
    }

    if (is_zero) {
        return "0";
    }

    auto to_char = [](int d) -> char {
        return d < 10 ? static_cast<char>('0' + d) : static_cast<char>('a' + (d - 10));
    };

    std::string result;
    if (negative) {
        result.push_back('-');
    }

    for (auto it = int_digits.rbegin(); it != int_digits.rend(); ++it) {
        result.push_back(to_char(*it));
    }

    // Trim trailing zeros in the fractional part
    long long last_nonzero = k - 1;
    while (last_nonzero >= 0 && frac_digits[last_nonzero] == 0) {
        last_nonzero--;
    }

    if (last_nonzero >= 0) {
        result.push_back('.');
        for (long long i = 0; i <= last_nonzero; ++i) {
            result.push_back(to_char(frac_digits[i]));
        }
    }

    return result;
}

const DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz";

export function formatBase(p: number | bigint, q: number | bigint, base: number, k: number): string {
  const bBase = Number(base);
  const bK = Number(k);

  if (q === 0 || q === 0n || !Number.isInteger(bBase) || bBase < 2 || bBase > 36 || !Number.isInteger(bK) || bK < 0) {
    throw new Error("Invalid arguments");
  }

  let bp = typeof p === "bigint" ? p : BigInt(p);
  let bq = typeof q === "bigint" ? q : BigInt(q);

  const isNegative = (bp < 0n) !== (bq < 0n);
  if (bp < 0n) bp = -bp;
  if (bq < 0n) bq = -bq;

  if (bp === 0n) {
    return "0";
  }

  let intPart = bp / bq;
  let rem = bp % bq;

  const fracDigits = new Uint8Array(bK);

  // Extract fractional digits in blocks if bq fits in a small safe integer,
  // otherwise use BigInt per digit or block.
  // Since the prompt says "Every integer in the tests fits in a number exactly",
  // bp and bq are <= Number.MAX_SAFE_INTEGER (~9e15) when passed as number,
  // though BigInt supports arbitrary size if ever passed.
  const bBaseBig = BigInt(bBase);

  // Determine a chunk size so that base^chunkSize fits comfortably,
  // reducing BigInt overhead for large k.
  let chunkLen = 1;
  let chunkMult = bBase;
  while (chunkLen < 10 && chunkMult * bBase <= 1000000000) {
    chunkMult *= bBase;
    chunkLen++;
  }
  const chunkMultBig = BigInt(chunkMult);

  let idx = 0;
  while (idx + chunkLen <= bK) {
    if (rem === 0n) {
      idx = bK;
      break;
    }
    const prod = rem * chunkMultBig;
    let blockVal = Number(prod / bq);
    rem = prod % bq;
    for (let j = idx + chunkLen - 1; j >= idx; j--) {
      fracDigits[j] = blockVal % bBase;
      blockVal = (blockVal / bBase) | 0;
    }
    idx += chunkLen;
  }

  while (idx < bK) {
    if (rem === 0n) {
      break;
    }
    const prod = rem * bBaseBig;
    fracDigits[idx] = Number(prod / bq);
    rem = prod % bq;
    idx++;
  }

  // Rounding: compare rem / bq with 1/2, i.e., 2 * rem vs bq
  const twiceRem = rem * 2n;
  let roundUp = false;
  if (twiceRem > bq) {
    roundUp = true;
  } else if (twiceRem === bq) {
    // Halfway tie-break: round to EVEN N.
    // N = intPart * base^k + sum_{i=0}^{k-1} fracDigits[i] * base^{k-1-i}
    let isOdd = false;
    if (bBase % 2 === 0) {
      if (bK === 0) {
        isOdd = (intPart & 1n) === 1n;
      } else {
        isOdd = (fracDigits[bK - 1] & 1) === 1;
      }
    } else {
      // In an odd base, base^m === 1 (mod 2), so parity of N is parity of sum of all digits (or intPart + sum of fracDigits)
      let parity = Number(intPart & 1n);
      for (let i = 0; i < bK; i++) {
        parity ^= fracDigits[i] & 1;
      }
      isOdd = parity === 1;
    }
    if (isOdd) {
      roundUp = true;
    }
  }

  if (roundUp) {
    let carry = 1;
    for (let i = bK - 1; i >= 0; i--) {
      const sum = fracDigits[i] + carry;
      if (sum >= bBase) {
        fracDigits[i] = sum - bBase;
        carry = 1;
      } else {
        fracDigits[i] = sum;
        carry = 0;
        break;
      }
    }
    if (carry === 1) {
      intPart += 1n;
    }
  }

  // Find last non-zero fractional digit
  let lastNonZero = bK - 1;
  while (lastNonZero >= 0 && fracDigits[lastNonZero] === 0) {
    lastNonZero--;
  }

  if (intPart === 0n && lastNonZero < 0) {
    return "0";
  }

  const signStr = isNegative ? "-" : "";
  const intStr = intPart.toString(bBase);

  if (lastNonZero < 0) {
    return signStr + intStr;
  }

  // Convert fractional digits up to lastNonZero into string
  const CHUNK_STR = 8192;
  const parts: string[] = [signStr, intStr, "."];
  const charCodes = new Array<number>(CHUNK_STR);

  let pos = 0;
  while (pos <= lastNonZero) {
    const end = Math.min(pos + CHUNK_STR, lastNonZero + 1);
    const len = end - pos;
    charCodes.length = len;
    for (let i = 0; i < len; i++) {
      const d = fracDigits[pos + i];
      charCodes[i] = d < 10 ? 48 + d : 87 + d;
    }
    parts.push(String.fromCharCode.apply(null, charCodes));
    pos = end;
  }

  return parts.join("");
}

package main

import (
	"errors"
	"fmt"
	"math/big"
)

func parseLiteral(s string) (bool, *big.Int, *big.Int, error) {
	if len(s) == 0 {
		return false, nil, nil, errors.New("empty string")
	}
	i := 0
	n := len(s)
	neg := false
	if s[i] == '+' {
		i++
	} else if s[i] == '-' {
		neg = true
		i++
	}
	if i == n {
		return false, nil, nil, errors.New("only sign")
	}

	var intPart, fracPart []byte
	hasDot := false
	for i < n && s[i] >= '0' && s[i] <= '9' {
		intPart = append(intPart, s[i])
		i++
	}
	if i < n && s[i] == '.' {
		hasDot = true
		i++
		for i < n && s[i] >= '0' && s[i] <= '9' {
			fracPart = append(fracPart, s[i])
			i++
		}
	}
	if len(intPart) == 0 && len(fracPart) == 0 {
		return false, nil, nil, errors.New("empty mantissa")
	}
	_ = hasDot

	var expSign int = 1
	var expDigits []byte
	if i < n && (s[i] == 'e' || s[i] == 'E') {
		i++
		if i == n {
			return false, nil, nil, errors.New("incomplete exponent")
		}
		if s[i] == '+' {
			i++
		} else if s[i] == '-' {
			expSign = -1
			i++
		}
		if i == n {
			return false, nil, nil, errors.New("incomplete exponent")
		}
		for i < n && s[i] >= '0' && s[i] <= '9' {
			expDigits = append(expDigits, s[i])
			i++
		}
		if len(expDigits) == 0 {
			return false, nil, nil, errors.New("empty exponent digits")
		}
	}

	if i != n {
		return false, nil, nil, errors.New("trailing characters")
	}

	mantissaStr := string(intPart) + string(fracPart)
	P, ok := new(big.Int).SetString(mantissaStr, 10)
	if !ok {
		return false, nil, nil, errors.New("failed to parse mantissa")
	}

	expVal := int64(0)
	if len(expDigits) > 0 {
		expBig, ok := new(big.Int).SetString(string(expDigits), 10)
		if !ok {
			return false, nil, nil, errors.New("failed to parse exponent")
		}
		if !expBig.IsInt64() {
			if expSign > 0 {
				expVal = 1000000
			} else {
				expVal = -1000000
			}
		} else {
			expVal = expBig.Int64() * int64(expSign)
		}
	}

	totalExp := expVal - int64(len(fracPart))
	Q := big.NewInt(1)
	ten := big.NewInt(10)

	if P.Sign() == 0 {
		return false, big.NewInt(0), big.NewInt(1), nil
	}

	if totalExp > 0 {
		pow10 := new(big.Int).Exp(ten, big.NewInt(totalExp), nil)
		P.Mul(P, pow10)
	} else if totalExp < 0 {
		pow10 := new(big.Int).Exp(ten, big.NewInt(-totalExp), nil)
		Q.Mul(Q, pow10)
	}

	g := new(big.Int).GCD(nil, nil, P, Q)
	P.Div(P, g)
	Q.Div(Q, g)

	return neg, P, Q, nil
}

func ClosestFraction(x string, max_num int, max_den int) (string, error) {
	if max_num < 0 || max_den < 1 {
		return "", errors.New("invalid bounds")
	}
	neg, P, Q, err := parseLiteral(x)
	if err != nil {
		return "", err
	}

	if max_num == 0 || P.Sign() == 0 {
		return "0/1", nil
	}

	M := uint64(max_num)
	D := uint64(max_den)

	// Check if P/Q > M/1
	maxVal := new(big.Int).Mul(Q, new(big.Int).SetUint64(M))
	if P.Cmp(maxVal) >= 0 {
		if neg {
			return fmt.Sprintf("-%d/1", M), nil
		}
		return fmt.Sprintf("%d/1", M), nil
	}

	// Check if P/Q < 1/D
	minCheck := new(big.Int).Mul(P, new(big.Int).SetUint64(D))
	if minCheck.Cmp(Q) <= 0 {
		// Inside [0/1, 1/D].
		p0, q0 := uint64(0), uint64(1)
		p1, q1 := uint64(1), D
		bestP, bestQ := chooseBest(P, Q, p0, q0, p1, q1)
		if bestP == 0 {
			return "0/1", nil
		}
		if neg {
			return fmt.Sprintf("-%d/%d", bestP, bestQ), nil
		}
		return fmt.Sprintf("%d/%d", bestP, bestQ), nil
	}

	// Now 1/D < P/Q < M/1.
	p0, q0 := uint64(0), uint64(1)
	p1, q1 := uint64(1), uint64(0)
	num := new(big.Int).Set(P)
	den := new(big.Int).Set(Q)

	for {
		a := new(big.Int)
		rem := new(big.Int)
		a.QuoRem(num, den, rem)

		var kMax uint64
		if a.IsUint64() {
			kMax = a.Uint64()
		} else {
			kMax = ^uint64(0)
		}

		limitNum := kMax
		if p1 > 0 {
			lim := (M - p0) / p1
			if lim < limitNum {
				limitNum = lim
			}
		}
		limitDen := kMax
		if q1 > 0 {
			lim := (D - q0) / q1
			if lim < limitDen {
				limitDen = lim
			}
		}

		limit := limitNum
		if limitDen < limit {
			limit = limitDen
		}

		if limit < kMax {
			p2 := p0 + limit*p1
			q2 := q0 + limit*q1

			var lowerP, lowerQ, upperP, upperQ uint64
			// Since we know P/Q is strictly between p1/q1 and p2/q2
			// Check which one is lower: p1*q2 - p2*q1.
			// Actually, we can just compare p1/q1 with p2/q2: p1*q2 < p2*q1
			c1 := new(big.Int).Mul(new(big.Int).SetUint64(p1), new(big.Int).SetUint64(q2))
			c2 := new(big.Int).Mul(new(big.Int).SetUint64(p2), new(big.Int).SetUint64(q1))
			if c1.Cmp(c2) < 0 {
				lowerP, lowerQ = p1, q1
				upperP, upperQ = p2, q2
			} else {
				lowerP, lowerQ = p2, q2
				upperP, upperQ = p1, q1
			}
			bestP, bestQ := chooseBest(P, Q, lowerP, lowerQ, upperP, upperQ)
			if bestP == 0 {
				return "0/1", nil
			}
			if neg {
				return fmt.Sprintf("-%d/%d", bestP, bestQ), nil
			}
			return fmt.Sprintf("%d/%d", bestP, bestQ), nil
		}

		p2 := p0 + kMax*p1
		q2 := q0 + kMax*q1

		if rem.Sign() == 0 {
			if p2 == 0 {
				return "0/1", nil
			}
			if neg {
				return fmt.Sprintf("-%d/%d", p2, q2), nil
			}
			return fmt.Sprintf("%d/%d", p2, q2), nil
		}

		p0, q0 = p1, q1
		p1, q1 = p2, q2
		num, den = den, rem
	}
}

func chooseBest(P, Q *big.Int, lowP, lowQ, upP, upQ uint64) (uint64, uint64) {
	// Distance to lower: P/Q - lowP/lowQ = (P*lowQ - Q*lowP) / (Q*lowQ)
	// Distance to upper: upP/upQ - P/Q = (Q*upP - P*upQ) / (Q*upQ)
	// Compare (P*lowQ - Q*lowP)*upQ with (Q*upP - P*upQ)*lowQ
	// Equivalently, compare 2*P*lowQ*upQ with Q*(lowP*upQ + upP*lowQ)

	bLowP := new(big.Int).SetUint64(lowP)
	bLowQ := new(big.Int).SetUint64(lowQ)
	bUpP := new(big.Int).SetUint64(upP)
	bUpQ := new(big.Int).SetUint64(upQ)

	lhs := new(big.Int).Mul(P, bLowQ)
	lhs.Mul(lhs, bUpQ)
	lhs.Lsh(lhs, 1) // * 2

	t1 := new(big.Int).Mul(bLowP, bUpQ)
	t2 := new(big.Int).Mul(bUpP, bLowQ)
	rhs := new(big.Int).Add(t1, t2)
	rhs.Mul(rhs, Q)

	cmp := lhs.Cmp(rhs)
	if cmp < 0 {
		// 2*x < low + up => x is closer to low
		return lowP, lowQ
	} else if cmp > 0 {
		return upP, upQ
	} else {
		// Tie!
		// Smaller denominator wins
		if lowQ < upQ {
			return lowP, lowQ
		} else if upQ < lowQ {
			return upP, upQ
		}
		// Smaller absolute value wins (which is always lowP/lowQ since 0 <= low < up)
		return lowP, lowQ
	}
}

import java.math.BigInteger;
import java.util.*;
import java.util.regex.Pattern;

public final class Solution {

    private static final Pattern LITERAL_PATTERN = Pattern.compile(
        "^[+-]?(?:[0-9]+\\.?[0-9]*|\\.[0-9]+)(?:[eE][+-]?[0-9]+)?$"
    );

    public static String closestFraction(String x, long max_num, long max_den) {
        if (x == null || max_num < 0 || max_den < 1 || !LITERAL_PATTERN.matcher(x).matches()) {
            throw new IllegalArgumentException();
        }

        // Parse x into exact rational P / Q >= 0, and remember sign.
        boolean negative = false;
        int idx = 0;
        if (x.charAt(0) == '+') {
            idx++;
        } else if (x.charAt(0) == '-') {
            negative = true;
            idx++;
        }

        int expIdx = x.indexOf('e', idx);
        if (expIdx == -1) {
            expIdx = x.indexOf('E', idx);
        }

        String mantissa = (expIdx == -1) ? x.substring(idx) : x.substring(idx, expIdx);
        long exp = 0;
        if (expIdx != -1) {
            String expStr = x.substring(expIdx + 1);
            // Exponent absolute value is at most 1000 per problem description,
            // but parse safely in case of larger valid strings.
            try {
                exp = Long.parseLong(expStr);
            } catch (NumberFormatException e) {
                throw new IllegalArgumentException(e);
            }
        }

        int dotIdx = mantissa.indexOf('.');
        String digits;
        int fracDigits = 0;
        if (dotIdx == -1) {
            digits = mantissa;
        } else {
            digits = mantissa.substring(0, dotIdx) + mantissa.substring(dotIdx + 1);
            fracDigits = mantissa.length() - 1 - dotIdx;
        }

        BigInteger P = new BigInteger(digits);
        if (P.signum() == 0) {
            return "0/1";
        }
        if (max_num == 0) {
            return "0/1";
        }

        long totalExp = exp - fracDigits;
        BigInteger Q;
        if (totalExp >= 0) {
            if (totalExp > 10000) {
                // Surely >= max_num
                return (negative ? "-" : "") + max_num + "/1";
            }
            P = P.multiply(BigInteger.TEN.pow((int) totalExp));
            Q = BigInteger.ONE;
        } else {
            if (-totalExp > 10000) {
                // Exceedingly tiny positive number; closest among 0/1 and 1/max_den is 0/1
                return "0/1";
            }
            Q = BigInteger.TEN.pow((int) (-totalExp));
        }

        // Reduce P / Q
        BigInteger gcd = P.gcd(Q);
        P = P.divide(gcd);
        Q = Q.divide(gcd);

        // If P / Q >= max_num, the capped value is max_num / 1
        if (P.compareTo(Q.multiply(BigInteger.valueOf(max_num))) >= 0) {
            return (negative ? "-" : "") + max_num + "/1";
        }

        // Stern-Brocot / Continued Fraction search for |x| = P / Q
        // Brackets: L = p0 / q0 (initially 0 / 1), R = p1 / q1 (initially 1 / 0)
        long p0 = 0, q0 = 1;
        long p1 = 1, q1 = 0;

        BigInteger a = P;
        BigInteger b = Q;
        boolean leftNext = false; // First step a0 is integer part, moves Left bracket (0/1 + a0 * 1/0)

        while (b.signum() != 0) {
            BigInteger[] qr = a.divideAndRemainder(b);
            BigInteger k = qr[0];
            a = b;
            b = qr[1];

            if (k.signum() > 0) {
                if (leftNext) {
                    // Moving R = p1/q1 towards L = p0/q0: new R = (p1 + k*p0) / (q1 + k*q0)
                    long maxK = Long.MAX_VALUE;
                    if (p0 > 0) maxK = Math.min(maxK, (max_num - p1) / p0);
                    if (q0 > 0) maxK = Math.min(maxK, (max_den - q1) / q0);

                    if (k.compareTo(BigInteger.valueOf(maxK)) >= 0) {
                        p1 += maxK * p0;
                        q1 += maxK * q0;
                        break;
                    } else {
                        long kl = k.longValue();
                        p1 += kl * p0;
                        q1 += kl * q0;
                    }
                } else {
                    // Moving L = p0/q0 towards R = p1/q1: new L = (p0 + k*p1) / (q0 + k*q1)
                    long maxK = Long.MAX_VALUE;
                    if (p1 > 0) maxK = Math.min(maxK, (max_num - p0) / p1);
                    if (q1 > 0) maxK = Math.min(maxK, (max_den - q0) / q1);

                    if (k.compareTo(BigInteger.valueOf(maxK)) >= 0) {
                        p0 += maxK * p1;
                        q0 += maxK * q1;
                        break;
                    } else {
                        long kl = k.longValue();
                        p0 += kl * p1;
                        q0 += kl * q1;
                    }
                }
            }
            leftNext = !leftNext;
        }

        // Now L = p0/q0 <= P/Q <= p1/q1 = R.
        // Note: R could still be 1/0 if k=0 on step 0 and then step 1 had maxK=0.
        if (q1 == 0) {
            return formatResult(negative, p0, q0);
        }

        // Compare distances: |P/Q - p0/q0| vs |p1/q1 - P/Q|
        // diff0 = (P*q0 - p0*Q) / (Q*q0)
        // diff1 = (p1*Q - P*q1) / (Q*q1)
        // Compare (P*q0 - p0*Q)*q1 vs (p1*Q - P*q1)*q0
        BigInteger B_p0 = BigInteger.valueOf(p0);
        BigInteger B_q0 = BigInteger.valueOf(q0);
        BigInteger B_p1 = BigInteger.valueOf(p1);
        BigInteger B_q1 = BigInteger.valueOf(q1);

        BigInteger lhs = P.multiply(B_q0).subtract(B_p0.multiply(Q)).multiply(B_q1);
        BigInteger rhs = B_p1.multiply(Q).subtract(P.multiply(B_q1)).multiply(B_q0);

        int cmp = lhs.compareTo(rhs);
        long bestP, bestQ;
        if (cmp < 0) {
            bestP = p0;
            bestQ = q0;
        } else if (cmp > 0) {
            bestP = p1;
            bestQ = q1;
        } else {
            // Tie-breaking rules:
            // 1. Smaller lowest-terms denominator (p0/q0 and p1/q1 are guaranteed coprime)
            if (q0 < q1) {
                bestP = p0;
                bestQ = q0;
            } else if (q1 < q0) {
                bestP = p1;
                bestQ = q1;
            } else {
                // 2. Smaller absolute value (closer to zero). Since p0/q0 < p1/q1, p0/q0 is closer to 0.
                bestP = p0;
                bestQ = q0;
            }
        }

        return formatResult(negative, bestP, bestQ);
    }

    private static String formatResult(boolean negative, long p, long q) {
        if (p == 0) {
            return "0/1";
        }
        return (negative ? "-" : "") + p + "/" + q;
    }
}

#include <iostream>
#include <string>
#include <vector>
#include <stdexcept>
#include <algorithm>
#include <cctype>
#include <cstdint>

namespace {

using u64 = uint64_t;
using i64 = int64_t;
using u128 = unsigned __int128;

struct BigInt {
    std::vector<u64> d; // base 10^9

    BigInt() {}
    BigInt(u64 v) {
        while (v > 0) {
            d.push_back(v % 1000000000ULL);
            v /= 1000000000ULL;
        }
    }
    BigInt(u128 v) {
        while (v > 0) {
            d.push_back(static_cast<u64>(v % 1000000000ULL));
            v /= 1000000000ULL;
        }
    }

    void trim() {
        while (!d.empty() && d.back() == 0) {
            d.pop_back();
        }
    }

    bool is_zero() const {
        return d.empty();
    }

    static BigInt from_dec_string(const std::string& s) {
        BigInt res;
        int n = static_cast<int>(s.size());
        for (int i = n; i > 0; i -= 9) {
            int start = std::max(0, i - 9);
            u64 val = 0;
            for (int j = start; j < i; ++j) {
                val = val * 10 + (s[j] - '0');
            }
            res.d.push_back(val);
        }
        res.trim();
        return res;
    }

    void mul_pow10(int exp) {
        if (is_zero() || exp == 0) return;
        int full_blocks = exp / 9;
        int rem = exp % 9;
        if (rem > 0) {
            u64 m = 1;
            for (int i = 0; i < rem; ++i) m *= 10;
            u64 carry = 0;
            for (size_t i = 0; i < d.size(); ++i) {
                u128 cur = static_cast<u128>(d[i]) * m + carry;
                d[i] = static_cast<u64>(cur % 1000000000ULL);
                carry = static_cast<u64>(cur / 1000000000ULL);
            }
            if (carry > 0) d.push_back(carry);
        }
        if (full_blocks > 0) {
            d.insert(d.begin(), full_blocks, 0);
        }
    }
};

int cmp(const BigInt& a, const BigInt& b) {
    if (a.d.size() != b.d.size()) {
        return a.d.size() < b.d.size() ? -1 : 1;
    }
    for (int i = static_cast<int>(a.d.size()) - 1; i >= 0; --i) {
        if (a.d[i] != b.d[i]) {
            return a.d[i] < b.d[i] ? -1 : 1;
        }
    }
    return 0;
}

BigInt add(const BigInt& a, const BigInt& b) {
    BigInt res;
    size_t n = std::max(a.d.size(), b.d.size());
    res.d.resize(n, 0);
    u64 carry = 0;
    for (size_t i = 0; i < n; ++i) {
        u64 sum = carry;
        if (i < a.d.size()) sum += a.d[i];
        if (i < b.d.size()) sum += b.d[i];
        res.d[i] = sum % 1000000000ULL;
        carry = sum / 1000000000ULL;
    }
    if (carry > 0) res.d.push_back(carry);
    return res;
}

// Assumes a >= b
BigInt sub(const BigInt& a, const BigInt& b) {
    BigInt res;
    res.d.resize(a.d.size(), 0);
    i64 borrow = 0;
    for (size_t i = 0; i < a.d.size(); ++i) {
        i64 diff = static_cast<i64>(a.d[i]) - borrow - (i < b.d.size() ? static_cast<i64>(b.d[i]) : 0);
        if (diff < 0) {
            diff += 1000000000LL;
            borrow = 1;
        } else {
            borrow = 0;
        }
        res.d[i] = static_cast<u64>(diff);
    }
    res.trim();
    return res;
}

BigInt mul(const BigInt& a, u64 b) {
    if (a.is_zero() || b == 0) return BigInt();
    return mul(a, BigInt(b));
}

BigInt mul(const BigInt& a, const BigInt& b) {
    if (a.is_zero() || b.is_zero()) return BigInt();
    BigInt res;
    res.d.resize(a.d.size() + b.d.size(), 0);
    for (size_t i = 0; i < a.d.size(); ++i) {
        u64 carry = 0;
        for (size_t j = 0; j < b.d.size(); ++j) {
            u128 cur = res.d[i + j] + static_cast<u128>(a.d[i]) * b.d[j] + carry;
            res.d[i + j] = static_cast<u64>(cur % 1000000000ULL);
            carry = static_cast<u64>(cur / 1000000000ULL);
        }
        size_t idx = i + b.d.size();
        while (carry > 0) {
            u128 cur = res.d[idx] + carry;
            res.d[idx] = static_cast<u64>(cur % 1000000000ULL);
            carry = static_cast<u64>(cur / 1000000000ULL);
            idx++;
        }
    }
    res.trim();
    return res;
}

BigInt mul_u128(const BigInt& a, u128 b) {
    if (a.is_zero() || b == 0) return BigInt();
    return mul(a, BigInt(b));
}

std::pair<BigInt, BigInt> divmod(const BigInt& A, const BigInt& B) {
    if (B.is_zero()) throw std::invalid_argument("Division by zero");
    if (cmp(A, B) < 0) return {BigInt(), A};

    BigInt Q, R;
    Q.d.resize(A.d.size(), 0);

    for (int i = static_cast<int>(A.d.size()) - 1; i >= 0; --i) {
        if (!R.is_zero() || A.d[i] != 0) {
            R.d.insert(R.d.begin(), A.d[i]);
            R.trim();
        }
        if (cmp(R, B) < 0) {
            Q.d[i] = 0;
            continue;
        }
        u64 low = 1, high = 999999999ULL;
        if (R.d.size() == B.d.size()) {
            u64 r_top = R.d.back();
            u64 b_top = B.d.back();
            low = r_top / (b_top + 1);
            high = (r_top + 1) / b_top;
            if (high > 999999999ULL) high = 999999999ULL;
        } else if (R.d.size() == B.d.size() + 1) {
            u128 r_top = static_cast<u128>(R.d.back()) * 1000000000ULL + R.d[R.d.size() - 2];
            u64 b_top = B.d.back();
            low = static_cast<u64>(r_top / (b_top + 1));
            u128 h = (r_top + 1) / b_top;
            high = h > 999999999ULL ? 999999999ULL : static_cast<u64>(h);
        }
        if (low < 1) low = 1;
        if (low > high) low = high;

        u64 ans = low;
        while (low <= high) {
            u64 mid = low + (high - low) / 2;
            BigInt prod = mul(B, mid);
            if (cmp(prod, R) <= 0) {
                ans = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        Q.d[i] = ans;
        R = sub(R, mul(B, ans));
    }
    Q.trim();
    return {Q, R};
}

} // namespace

std::string closest_fraction(const std::string& x, long long max_num, long long max_den) {
    if (max_num < 0 || max_den < 1) {
        throw std::invalid_argument("Invalid bounds");
    }
    if (x.empty()) {
        throw std::invalid_argument("Empty string");
    }

    size_t i = 0;
    size_t n = x.size();
    bool neg = false;

    if (x[i] == '+' || x[i] == '-') {
        if (x[i] == '-') neg = true;
        i++;
    }
    if (i == n) throw std::invalid_argument("Sign only");

    std::string digits;
    long long frac_digits = 0;

    if (x[i] == '.') {
        i++;
        size_t start_frac = i;
        while (i < n && std::isdigit(static_cast<unsigned char>(x[i]))) {
            digits.push_back(x[i]);
            i++;
        }
        frac_digits = i - start_frac;
        if (frac_digits == 0) throw std::invalid_argument("Single dot");
    } else if (std::isdigit(static_cast<unsigned char>(x[i]))) {
        while (i < n && std::isdigit(static_cast<unsigned char>(x[i]))) {
            digits.push_back(x[i]);
            i++;
        }
        if (i < n && x[i] == '.') {
            i++;
            size_t start_frac = i;
            while (i < n && std::isdigit(static_cast<unsigned char>(x[i]))) {
                digits.push_back(x[i]);
                i++;
            }
            frac_digits = i - start_frac;
        }
    } else {
        throw std::invalid_argument("Invalid start of mantissa");
    }

    long long exp_val = 0;
    if (i < n && (x[i] == 'e' || x[i] == 'E')) {
        i++;
        if (i == n) throw std::invalid_argument("Empty exponent");
        bool exp_neg = false;
        if (x[i] == '+' || x[i] == '-') {
            if (x[i] == '-') exp_neg = true;
            i++;
        }
        if (i == n || !std::isdigit(static_cast<unsigned char>(x[i]))) {
            throw std::invalid_argument("Invalid exponent digits");
        }
        while (i < n && std::isdigit(static_cast<unsigned char>(x[i]))) {
            if (exp_val < 1000000000LL) {
                exp_val = exp_val * 10 + (x[i] - '0');
            }
            i++;
        }
        if (exp_neg) exp_val = -exp_val;
    }

    if (i != n) {
        throw std::invalid_argument("Trailing characters");
    }

    if (max_num == 0) {
        return "0/1";
    }

    BigInt P = BigInt::from_dec_string(digits);
    if (P.is_zero()) {
        return "0/1";
    }

    BigInt Q(1ULL);
    long long net_exp = exp_val - frac_digits;
    if (net_exp > 0) {
        P.mul_pow10(static_cast<int>(net_exp));
    } else if (net_exp < 0) {
        Q.mul_pow10(static_cast<int>(-net_exp));
    }

    u64 M_num = static_cast<u64>(max_num);
    u64 M_den = static_cast<u64>(max_den);

    u64 a = 0, b = 1;
    u64 c = 1, d = 0;

    BigInt A = P, B = Q;
    bool from_even = true; // step 0 is even

    while (!B.is_zero()) {
        auto [q_big, r_big] = divmod(A, B);
        A = B;
        B = r_big;

        u64 max_k_num = (c == 0) ? UINT64_MAX : (M_num - a) / c;
        u64 max_k_den = (d == 0) ? UINT64_MAX : (M_den - b) / d;
        u64 max_k = std::min(max_k_num, max_k_den);

        bool q_exceeds = false;
        u64 q_val = 0;
        if (q_big.d.size() > 3) {
            q_exceeds = true;
        } else {
            u128 q128 = 0;
            for (int idx = static_cast<int>(q_big.d.size()) - 1; idx >= 0; --idx) {
                q128 = q128 * 1000000000ULL + q_big.d[idx];
            }
            if (q128 > max_k) {
                q_exceeds = true;
            } else {
                q_val = static_cast<u64>(q128);
            }
        }

        if (q_exceeds) {
            if (from_even) {
                c = a + max_k * c;
                d = b + max_k * d;
            } else {
                a = c + max_k * a;
                b = d + max_k * b;
            }
            break;
        } else {
            if (from_even) {
                u64 next_a = a + q_val * c;
                u64 next_b = b + q_val * d;
                a = c; b = d;
                c = next_a; d = next_b;
            } else {
                u64 next_c = c + q_val * a;
                u64 next_d = d + q_val * b;
                c = a; d = b;
                a = next_c; b = next_d;
            }
            if (B.is_zero()) {
                if (from_even) {
                    a = c; b = d;
                } else {
                    c = a; d = b;
                }
                break;
            }
            from_even = !from_even;
        }
    }

    u64 chosen_num = 0, chosen_den = 1;

    if (d == 0) {
        chosen_num = a;
        chosen_den = b;
    } else if (a == c && b == d) {
        chosen_num = a;
        chosen_den = b;
    } else {
        u128 coeff = static_cast<u128>(a) * d + static_cast<u128>(b) * c;
        BigInt LHS = mul_u128(Q, coeff);

        u128 bd2 = 2 * static_cast<u128>(b) * d;
        BigInt RHS = mul_u128(P, bd2);

        int cmp_res = cmp(LHS, RHS);
        if (cmp_res > 0) {
            chosen_num = a;
            chosen_den = b;
        } else if (cmp_res < 0) {
            chosen_num = c;
            chosen_den = d;
        } else {
            if (b < d) {
                chosen_num = a;
                chosen_den = b;
            } else if (d < b) {
                chosen_num = c;
                chosen_den = d;
            } else {
                // Equal denominators, a/b < c/d, so a/b is closer to 0
                chosen_num = a;
                chosen_den = b;
            }
        }
    }

    std::string res;
    if (neg && chosen_num > 0) {
        res += "-";
    }
    res += std::to_string(chosen_num) + "/" + std::to_string(chosen_den);
    return res;
}

function gcd(a: bigint, b: bigint): bigint {
  a = a < 0n ? -a : a;
  b = b < 0n ? -b : b;
  while (b !== 0n) {
    const t = a % b;
    a = b;
    b = t;
  }
  return a;
}

function parseDecimal(x: string): [bigint, bigint, boolean] {
  const regex = /^([+-])?(?:(\d+)(?:\.(\d*))?|\.(\d+))(?:[eE]([+-]?\d+))?$/;
  const match = regex.exec(x);
  if (!match) {
    throw new Error("Invalid decimal literal");
  }

  const signStr = match[1];
  const isNeg = signStr === "-";
  const intPart = match[2] ?? "";
  const fracPart = match[3] ?? match[4] ?? "";
  const expStr = match[5];

  const digitsStr = intPart + fracPart;
  let P = BigInt(digitsStr);
  if (P === 0n) {
    return [0n, 1n, false];
  }

  let exp = expStr !== undefined ? Number(expStr) : 0;
  exp -= fracPart.length;

  let Q = 1n;
  if (exp > 0) {
    P *= 10n ** BigInt(exp);
  } else if (exp < 0) {
    Q = 10n ** BigInt(-exp);
  }

  const g = gcd(P, Q);
  return [P / g, Q / g, isNeg];
}

export function closestFraction(
  x: string,
  max_num: number | bigint,
  max_den: number | bigint
): string {
  if (typeof x !== "string") {
    throw new Error("Invalid x");
  }
  if (typeof max_num === "number" && (!Number.isInteger(max_num) || isNaN(max_num))) {
    throw new Error("Invalid max_num");
  }
  if (typeof max_den === "number" && (!Number.isInteger(max_den) || isNaN(max_den))) {
    throw new Error("Invalid max_den");
  }

  const M = BigInt(max_num);
  const N = BigInt(max_den);

  if (M < 0n || N < 1n) {
    throw new Error("Bounds out of range");
  }

  const [P, Q, isNeg] = parseDecimal(x);

  if (P === 0n || M === 0n) {
    return "0/1";
  }

  // Maximum representable positive value is M / 1
  if (P >= M * Q) {
    return (isNeg ? "-" : "") + `${M}/1`;
  }

  // Minimum positive representable value is 1 / N.
  // If x < 1/N, the bracketing fractions in our valid set are 0/1 and 1/N.
  if (P * N < Q) {
    const candidates: [bigint, bigint][] = [
      [0n, 1n],
      [1n, N],
    ];
    let bestA = 0n;
    let bestB = 1n;
    for (let i = 1; i < candidates.length; i++) {
      const [a, b] = candidates[i];
      if (isBetter(a, b, bestA, bestB, P, Q)) {
        bestA = a;
        bestB = b;
      }
    }
    if (bestA === 0n) return "0/1";
    return (isNeg ? "-" : "") + `${bestA}/${bestB}`;
  }

  // Standard Stern-Brocot / Continued Fraction search
  // Lower bound L = a/b = 0/1, Upper bound R = c/d = 1/0
  let a = 0n,
    b = 1n;
  let c = 1n,
    d = 0n;

  while (true) {
    const num = a + c;
    const den = b + d;
    if (num > M || den > N) {
      break;
    }

    const cmp = P * den - Q * num;
    if (cmp === 0n) {
      // Exact match
      return (isNeg ? "-" : "") + `${num}/${den}`;
    } else if (cmp > 0n) {
      // x > mediant, move L up towards R
      const remP = P * d - Q * c; // < 0
      const remM = Q * a - P * b; // < 0
      let kMax = remM / remP;
      if (remM % remP === 0n) {
        kMax -= 1n; // Don't land on exact here, let the next iteration catch it or bound it
      }
      if (c > 0n) {
        const kNum = (M - a) / c;
        if (kNum < kMax) kMax = kNum;
      }
      if (d > 0n) {
        const kDen = (N - b) / d;
        if (kDen < kMax) kMax = kDen;
      }
      if (kMax < 1n) kMax = 1n;
      a += kMax * c;
      b += kMax * d;
    } else {
      // x < mediant, move R down towards L
      const remP = Q * a - P * b; // < 0
      const remM = P * d - Q * c; // < 0
      let kMax = remM / remP;
      if (remM % remP === 0n) {
        kMax -= 1n;
      }
      if (a > 0n) {
        const kNum = (M - c) / a;
        if (kNum < kMax) kMax = kNum;
      }
      if (b > 0n) {
        const kDen = (N - d) / b;
        if (kDen < kMax) kMax = kDen;
      }
      if (kMax < 1n) kMax = 1n;
      c += kMax * a;
      d += kMax * b;
    }
  }

  // Compare final L = a/b and R = c/d
  let bestA = a;
  let bestB = b;
  if (d > 0n && c <= M && d <= N) {
    if (isBetter(c, d, bestA, bestB, P, Q)) {
      bestA = c;
      bestB = d;
    }
  }

  if (bestA === 0n) {
    return "0/1";
  }
  return (isNeg ? "-" : "") + `${bestA}/${bestB}`;
}

function isBetter(
  a1: bigint,
  b1: bigint,
  a2: bigint,
  b2: bigint,
  P: bigint,
  Q: bigint
): boolean {
  let diff1 = a1 * Q - P * b1;
  if (diff1 < 0n) diff1 = -diff1;
  let diff2 = a2 * Q - P * b2;
  if (diff2 < 0n) diff2 = -diff2;

  const lhs = diff1 * b2;
  const rhs = diff2 * b1;

  if (lhs !== rhs) {
    return lhs < rhs;
  }
  if (b1 !== b2) {
    return b1 < b2;
  }
  return a1 * b2 < a2 * b1;
}

package main

import (
	"errors"
	"math"
	"math/bits"
	"strconv"
)

func DecimalToHalfBits(s string) (int, error) {
	if len(s) == 0 {
		return 0, errors.New("empty string")
	}

	i := 0
	n := len(s)
	signBit := 0
	if s[i] == '+' {
		i++
	} else if s[i] == '-' {
		signBit = 0x8000
		i++
	}

	if i == n {
		return 0, errors.New("invalid literal")
	}

	intStart := i
	for i < n && s[i] >= '0' && s[i] <= '9' {
		i++
	}
	intEnd := i

	fracStart := i
	fracEnd := i
	hasDot := false
	if i < n && s[i] == '.' {
		hasDot = true
		i++
		fracStart = i
		for i < n && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		fracEnd = i
	}

	if intEnd == intStart && fracEnd == fracStart {
		return 0, errors.New("no digits in mantissa")
	}
	if !hasDot && intEnd == intStart {
		return 0, errors.New("invalid mantissa")
	}

	expSign := 1
	var expVal int64 = 0
	if i < n && (s[i] == 'e' || s[i] == 'E') {
		i++
		if i == n {
			return 0, errors.New("empty exponent")
		}
		if s[i] == '+' {
			i++
		} else if s[i] == '-' {
			expSign = -1
			i++
		}
		expStart := i
		for i < n && s[i] >= '0' && s[i] <= '9' {
			d := int64(s[i] - '0')
			if expVal < 1000000000 {
				expVal = expVal*10 + d
			}
			i++
		}
		if i == expStart {
			return 0, errors.New("no digits in exponent")
		}
	}

	if i != n {
		return 0, errors.New("trailing characters")
	}

	exp := expVal * int64(expSign)

	var sigDigits []byte
	var firstSigPos int64 = 0
	foundSig := false
	var digitIdx int64 = 0

	for j := intStart; j < intEnd; j++ {
		c := s[j]
		if !foundSig {
			if c != '0' {
				foundSig = true
				firstSigPos = digitIdx
				sigDigits = append(sigDigits, c)
			}
		} else {
			if len(sigDigits) < 40 {
				sigDigits = append(sigDigits, c)
			} else if c != '0' {
				sigDigits[39] |= 1
			}
		}
		digitIdx++
	}
	numIntDigits := digitIdx

	for j := fracStart; j < fracEnd; j++ {
		c := s[j]
		if !foundSig {
			if c != '0' {
				foundSig = true
				firstSigPos = digitIdx
				sigDigits = append(sigDigits, c)
			}
		} else {
			if len(sigDigits) < 40 {
				sigDigits = append(sigDigits, c)
			} else if c != '0' {
				sigDigits[39] |= 1
			}
		}
		digitIdx++
	}

	if !foundSig {
		return signBit, nil
	}

	decExp := (numIntDigits - 1 - firstSigPos) + exp

	if decExp > 5 {
		return signBit | 0x7C00, nil
	}
	if decExp < -8 {
		return signBit, nil
	}

	k := len(sigDigits)
	var cleanStr []byte
	if k <= 19 {
		cleanStr = sigDigits
	} else {
		cleanStr = make([]byte, 19)
		copy(cleanStr, sigDigits[:19])
		hasNonZero := false
		for j := 19; j < k; j++ {
			if sigDigits[j] != '0' {
				hasNonZero = true
				break
			}
		}
		if hasNonZero {
			if cleanStr[18] == '0' || cleanStr[18] == '5' {
				cleanStr[18]++
			}
		}
		k = 19
	}

	exp10 := int64(decExp) - int64(k) + 1
	cleanStr = append(cleanStr, 'e')
	cleanStr = strconv.AppendInt(cleanStr, exp10, 10)

	f, err := strconv.ParseFloat(string(cleanStr), 64)
	if err != nil && !errors.Is(err, strconv.ErrRange) {
		return 0, err
	}

	if math.IsInf(f, 0) || f >= 65520.0 {
		return signBit | 0x7C00, nil
	}
	if f <= 2.98023223876953125e-8 { // 2^-25
		return signBit, nil
	}

	b := math.Float64bits(f)
	e64 := int((b>>52)&0x7FF) - 1023
	m64 := (b & ((1 << 52) - 1)) | (1 << 52)

	var E16 int
	var shift uint
	if e64 < -14 {
		E16 = 0
		shift = uint(28 - e64)
	} else {
		E16 = e64 + 15
		shift = 42
	}

	F16 := m64 >> shift
	rem := m64 & ((uint64(1) << shift) - 1)
	half := uint64(1) << (shift - 1)

	if rem > half || (rem == half && (F16&1) != 0) {
		F16++
	}

	if E16 == 0 {
		if F16 == 1024 {
			E16 = 1
			F16 = 0
		}
	} else {
		if F16 == 2048 {
			E16++
			F16 = 0
			if E16 == 31 {
				return signBit | 0x7C00, nil
			}
		} else {
			F16 &= 1023
		}
	}

	_ = bits.LeadingZeros64 // silence unused import if any
	res := signBit | (E16 << 10) | int(F16)
	return res, nil
}

import java.util.*;
import java.math.BigInteger;

public final class Solution {
    public static long decimalToHalfBits(String s) {
        if (s == null || s.isEmpty()) {
            throw new IllegalArgumentException("Invalid input");
        }

        int n = s.length();
        int idx = 0;

        // 1. Parse sign
        boolean neg = false;
        char c = s.charAt(idx);
        if (c == '+') {
            idx++;
        } else if (c == '-') {
            neg = true;
            idx++;
        }

        if (idx >= n) {
            throw new IllegalArgumentException("Invalid input");
        }

        // 2. Parse mantissa
        int intStart = idx;
        while (idx < n && s.charAt(idx) >= '0' && s.charAt(idx) <= '9') {
            idx++;
        }
        int intEnd = idx;
        int intLen = intEnd - intStart;

        int fracStart = idx;
        int fracEnd = idx;
        if (idx < n && s.charAt(idx) == '.') {
            idx++;
            fracStart = idx;
            while (idx < n && s.charAt(idx) >= '0' && s.charAt(idx) <= '9') {
                idx++;
            }
            fracEnd = idx;
        }
        int fracLen = fracEnd - fracStart;

        if (intLen == 0 && fracLen == 0) {
            throw new IllegalArgumentException("Invalid mantissa");
        }

        // 3. Parse exponent
        long expVal = 0;
        if (idx < n && (s.charAt(idx) == 'e' || s.charAt(idx) == 'E')) {
            idx++;
            if (idx >= n) {
                throw new IllegalArgumentException("Invalid exponent");
            }
            boolean expNeg = false;
            char ec = s.charAt(idx);
            if (ec == '+') {
                idx++;
            } else if (ec == '-') {
                expNeg = true;
                idx++;
            }
            int expStart = idx;
            while (idx < n && s.charAt(idx) >= '0' && s.charAt(idx) <= '9') {
                if (expVal < 1_000_000_000L) {
                    expVal = expVal * 10 + (s.charAt(idx) - '0');
                }
                idx++;
            }
            int expLen = idx - expStart;
            if (expLen == 0) {
                throw new IllegalArgumentException("Invalid exponent digits");
            }
            if (expNeg) {
                expVal = -expVal;
            }
        }

        if (idx != n) {
            throw new IllegalArgumentException("Trailing characters");
        }

        long signBit = neg ? 0x8000L : 0x0000L;

        // 4. Find significant digits in mantissa
        int firstNonZeroPos = -1; // virtual index in [0, intLen + fracLen)
        for (int i = intStart; i < intEnd; i++) {
            if (s.charAt(i) != '0') {
                firstNonZeroPos = i - intStart;
                break;
            }
        }
        if (firstNonZeroPos == -1) {
            for (int i = fracStart; i < fracEnd; i++) {
                if (s.charAt(i) != '0') {
                    firstNonZeroPos = intLen + (i - fracStart);
                    break;
                }
            }
        }

        // If the exact value is 0
        if (firstNonZeroPos == -1) {
            return signBit;
        }

        // Value is d_0 . d_1 d_2 ... * 10^(sciExp)
        long sciExp = expVal + (intLen - 1 - firstNonZeroPos);

        // Quick overflow / underflow checks
        // Max threshold is 65520 = 6.552 * 10^4. If sciExp >= 5, value >= 10^5 > 65520 -> Infinity
        if (sciExp >= 5) {
            return signBit | 0x7C00L;
        }
        // Min threshold is 2^-25 approx 2.98 * 10^-8. If sciExp <= -9, value < 10^-8 < 2^-25 -> Zero
        if (sciExp <= -9) {
            return signBit;
        }

        // Collect up to 40 significant digits, and track if there are non-zero digits beyond that
        int MAX_DIGITS = 40;
        StringBuilder sb = new StringBuilder(MAX_DIGITS + 1);
        int collected = 0;
        boolean sticky = false;

        int totalDigits = intLen + fracLen;
        for (int pos = firstNonZeroPos; pos < totalDigits; pos++) {
            char ch = (pos < intLen) ? s.charAt(intStart + pos) : s.charAt(fracStart + (pos - intLen));
            if (collected < MAX_DIGITS) {
                sb.append(ch);
                collected++;
            } else {
                if (ch != '0') {
                    sticky = true;
                    break;
                }
            }
        }

        long E10 = sciExp - (collected - 1);
        if (sticky) {
            // Append '1' to represent the sticky non-zero tail.
            // Since the exact midpoint of binary16 has at most 26 decimal digits in its mantissa,
            // perturbing the 41st digit cannot cross any midpoint.
            sb.append('1');
            E10 -= 1;
        }

        // Strip trailing zeros from sb to keep the BigInteger small
        int sigLen = sb.length();
        while (sigLen > 1 && sb.charAt(sigLen - 1) == '0') {
            sigLen--;
            E10++;
        }
        String sigStr = sb.substring(0, sigLen);
        BigInteger M = new BigInteger(sigStr);

        // Value is M * 10^E10 = (M * 5^E10) * 2^E10
        BigInteger N;
        BigInteger D;
        if (E10 >= 0) {
            int e10 = (int) E10;
            N = M.multiply(BigInteger.valueOf(5).pow(e10)).shiftLeft(e10);
            D = BigInteger.ONE;
        } else {
            int negE10 = (int) (-E10);
            N = M;
            D = BigInteger.valueOf(5).pow(negE10).shiftLeft(negE10);
        }

        // Now exact value is N / D.
        int bitLenN = N.bitLength();
        int bitLenD = D.bitLength();
        int k = bitLenN - bitLenD; // floor(log2(N/D)) is either k or k - 1

        // Check if N / D < 2^k, i.e., N < D * 2^k
        if (k >= 0) {
            if (N.compareTo(D.shiftLeft(k)) < 0) {
                k--;
            }
        } else {
            if (N.shiftLeft(-k).compareTo(D) < 0) {
                k--;
            }
        }

        // Now 2^k <= N / D < 2^(k+1), so k = floor(log2(v)).
        if (k >= 16) {
            return signBit | 0x7C00L;
        }
        if (k < -25) {
            return signBit;
        }

        int E;
        int shift; // We want to compute v * 2^shift = (N / D) * 2^shift
        if (k <= -15) {
            // Subnormal range (or underflow to 0)
            E = 0;
            shift = 24;
        } else {
            // Normal range
            E = k + 15;
            shift = 10 - k;
        }

        BigInteger num = (shift >= 0) ? N.shiftLeft(shift) : N;
        BigInteger den = (shift >= 0) ? D : D.shiftLeft(-shift);

        BigInteger[] qr = num.divideAndRemainder(den);
        int q = qr[0].intValue();
        BigInteger r = qr[1];

        // Compare 2 * r with den for rounding
        int cmp = r.shiftLeft(1).compareTo(den);
        if (cmp > 0 || (cmp == 0 && (q & 1) != 0)) {
            q++;
        }

        if (E == 0) {
            if (q == 1024) {
                // Transition from subnormal to normal
                return signBit | (1L << 10);
            } else {
                return signBit | q;
            }
        } else {
            int F = q - 1024;
            if (F == 1024) {
                E++;
                F = 0;
                if (E == 31) {
                    // Overflow to infinity
                    return signBit | 0x7C00L;
                }
            }
            return signBit | ((long) E << 10) | F;
        }
    }
}

#include <algorithm>
#include <cctype>
#include <cmath>
#include <cstdint>
#include <stdexcept>
#include <string>
#include <vector>

namespace {

bool is_digit(char c) {
    return c >= '0' && c <= '9';
}

struct BigInt {
    std::vector<uint32_t> d; // base 10^9

    BigInt() {}
    BigInt(uint64_t v) {
        while (v > 0) {
            d.push_back(v % 1000000000);
            v /= 1000000000;
        }
    }

    void trim() {
        while (!d.empty() && d.back() == 0) {
            d.pop_back();
        }
    }

    void mul_small(uint32_t m) {
        if (m == 0 || d.empty()) {
            d.clear();
            return;
        }
        uint64_t carry = 0;
        for (size_t i = 0; i < d.size(); ++i) {
            uint64_t prod = uint64_t(d[i]) * m + carry;
            d[i] = uint32_t(prod % 1000000000);
            carry = prod / 1000000000;
        }
        while (carry > 0) {
            d.push_back(uint32_t(carry % 1000000000));
            carry /= 1000000000;
        }
    }

    void add_small(uint32_t a) {
        uint64_t carry = a;
        for (size_t i = 0; i < d.size() && carry > 0; ++i) {
            uint64_t sum = uint64_t(d[i]) + carry;
            d[i] = uint32_t(sum % 1000000000);
            carry = sum / 1000000000;
        }
        if (carry > 0) {
            d.push_back(uint32_t(carry));
        }
    }

    static int cmp(const BigInt& a, const BigInt& b) {
        if (a.d.size() != b.d.size()) {
            return a.d.size() < b.d.size() ? -1 : 1;
        }
        for (size_t i = a.d.size(); i > 0; --i) {
            if (a.d[i - 1] != b.d[i - 1]) {
                return a.d[i - 1] < b.d[i - 1] ? -1 : 1;
            }
        }
        return 0;
    }
};

BigInt parse_bigint(const std::string& str) {
    BigInt res;
    size_t n = str.size();
    for (size_t i = 0; i < n; ) {
        size_t chunk_len = std::min<size_t>(9, n - i);
        uint32_t val = 0;
        uint32_t mult = 1;
        for (size_t j = 0; j < chunk_len; ++j) {
            val = val * 10 + (str[i + j] - '0');
            mult *= 10;
        }
        res.mul_small(mult);
        res.add_small(val);
        i += chunk_len;
    }
    res.trim();
    return res;
}

void mul_pow2(BigInt& b, int p) {
    while (p >= 29) {
        b.mul_small(1U << 29);
        p -= 29;
    }
    if (p > 0) {
        b.mul_small(1U << p);
    }
}

void mul_pow5(BigInt& b, int p) {
    while (p >= 13) {
        b.mul_small(1220703125U); // 5^13
        p -= 13;
    }
    if (p > 0) {
        uint32_t m = 1;
        for (int i = 0; i < p; ++i) m *= 5;
        b.mul_small(m);
    }
}

// Compares the parsed decimal against the exact midpoint (2*k + 1) * 2^(exp2)
// Returns < 0 if decimal < midpoint, 0 if ==, > 0 if > midpoint
int compare_midpoint(const std::string& sig, int64_t exp10, int k, int exp2) {
    size_t L = sig.size();
    size_t max_len = 50;
    bool sticky = false;
    std::string M_str;

    if (L > max_len) {
        M_str = sig.substr(0, max_len);
        for (size_t i = max_len; i < L; ++i) {
            if (sig[i] != '0') {
                sticky = true;
                break;
            }
        }
        exp10 += (L - max_len);
    } else {
        M_str = sig;
    }

    BigInt M = parse_bigint(M_str);
    M.mul_small(10);
    if (sticky) {
        M.add_small(1);
    }
    exp10 -= 1;

    int a = exp10 - exp2;
    int b = exp10;

    BigInt lhs = M;
    BigInt rhs(2 * k + 1);

    if (a > 0) {
        mul_pow2(lhs, a);
    } else if (a < 0) {
        mul_pow2(rhs, -a);
    }

    if (b > 0) {
        mul_pow5(lhs, b);
    } else if (b < 0) {
        mul_pow5(rhs, -b);
    }

    return BigInt::cmp(lhs, rhs);
}

