long long decimal_to_half_bits(const std::string& s) {
    if (s.empty()) {
        throw std::invalid_argument("Empty string");
    }

    size_t i = 0;
    size_t n = s.size();
    bool neg = false;

    if (s[i] == '+' || s[i] == '-') {
        neg = (s[i] == '-');
        i++;
    }
    if (i == n) {
        throw std::invalid_argument("Sign only");
    }

    size_t int_start = i;
    while (i < n && is_digit(s[i])) {
        i++;
    }
    size_t int_len = i - int_start;

    size_t frac_start = i;
    size_t frac_len = 0;
    if (i < n && s[i] == '.') {
        i++;
        frac_start = i;
        while (i < n && is_digit(s[i])) {
            i++;
        }
        frac_len = i - frac_start;
    }

    if (int_len == 0 && frac_len == 0) {
        throw std::invalid_argument("No digits in mantissa");
    }

    int64_t exp_val = 0;
    if (i < n && (s[i] == 'e' || s[i] == 'E')) {
        i++;
        if (i == n) {
            throw std::invalid_argument("Empty exponent");
        }
        bool exp_neg = false;
        if (s[i] == '+' || s[i] == '-') {
            exp_neg = (s[i] == '-');
            i++;
        }
        if (i == n) {
            throw std::invalid_argument("Sign only in exponent");
        }
        size_t exp_start = i;
        while (i < n && is_digit(s[i])) {
            if (exp_val < 10000000) {
                exp_val = exp_val * 10 + (s[i] - '0');
            }
            i++;
        }
        if (i - exp_start == 0) {
            throw std::invalid_argument("No digits in exponent");
        }
        if (exp_neg) {
            exp_val = -exp_val;
        }
    }

    if (i != n) {
        throw std::invalid_argument("Trailing characters");
    }

    // Extract significant digits (skipping leading zeros)
    std::string sig;
    int64_t num_zeros_skipped = 0;
    bool found_nonzero = false;

    for (size_t j = 0; j < int_len; ++j) {
        char c = s[int_start + j];
        if (!found_nonzero) {
            if (c != '0') {
                found_nonzero = true;
                sig.push_back(c);
            }
        } else {
            sig.push_back(c);
        }
    }

    for (size_t j = 0; j < frac_len; ++j) {
        char c = s[frac_start + j];
        if (!found_nonzero) {
            if (c != '0') {
                found_nonzero = true;
                sig.push_back(c);
            } else {
                num_zeros_skipped++;
            }
        } else {
            sig.push_back(c);
        }
    }

    uint16_t sign_bit = neg ? 0x8000 : 0x0000;
    if (!found_nonzero) {
        return sign_bit;
    }

    // Remove trailing zeros to make representation canonical
    while (!sig.empty() && sig.back() == '0') {
        sig.pop_back();
    }

    // Value is 0.<sig> * 10^(sci_exp + 1)
    int64_t sci_exp = exp_val;
    if (int_len > 0 && s[int_start] != '0') {
        // Need to count non-leading-zero integer digits
        size_t nz_int = 0;
        bool fnz = false;
        for (size_t j = 0; j < int_len; ++j) {
            if (s[int_start + j] != '0') fnz = true;
            if (fnz) nz_int++;
        }
        sci_exp += static_cast<int64_t>(nz_int) - 1;
    } else {
        // Count whether there were any non-zero digits in integer part at all
        size_t nz_int = 0;
        bool fnz = false;
        for (size_t j = 0; j < int_len; ++j) {
            if (s[int_start + j] != '0') fnz = true;
            if (fnz) nz_int++;
        }
        if (nz_int > 0) {
            sci_exp += static_cast<int64_t>(nz_int) - 1;
        } else {
            sci_exp -= (num_zeros_skipped + 1);
        }
    }

    // Fast path for extreme exponents
    if (sci_exp >= 5) {
        return sign_bit | 0x7C00;
    }
    if (sci_exp <= -9) {
        return sign_bit;
    }

    int64_t exp10 = sci_exp + 1 - static_cast<int64_t>(sig.size());

    // Compute double approximation for binary search seed
    std::string prefix = sig.substr(0, std::min<size_t>(sig.size(), 17));
    double d_val = std::stod(prefix);
    int64_t d_exp10 = sci_exp + 1 - static_cast<int64_t>(prefix.size());
    d_val *= std::pow(10.0, static_cast<double>(d_exp10));

    uint16_t low_P = 0;
    if (d_val >= 65504.0) {
        low_P = 31743; // 0x7BFF
    } else if (d_val > 0.0) {
        int e;
        double m = std::frexp(d_val, &e); // d_val = m * 2^e, m in [0.5, 1)
        int E = e + 14;
        if (E >= 1) {
            int F = static_cast<int>((m * 2.0 - 1.0) * 1024.0);
            int P = (E << 10) + F - 1;
            low_P = static_cast<uint16_t>(std::clamp(P, 0, 31743));
        } else {
            int P = static_cast<int>( std::ldexp(d_val, 24) ) - 1;
            low_P = static_cast<uint16_t>(std::clamp(P, 0, 1024));
        }
    }

    auto get_midpoint = [](uint16_t P, int& k, int& exp2) {
        if (P < 1024) {
            k = P;
            exp2 = -25;
        } else {
            int E = P >> 10;
            int F = P & 0x3FF;
            k = 1024 + F;
            exp2 = E - 26;
        }
    };

    // Adjust low_P until we bracket the exact value
    while (low_P > 0) {
        int k, exp2;
        get_midpoint(low_P - 1, k, exp2);
        if (compare_midpoint(sig, exp10, k, exp2) < 0) {
            low_P--;
        } else {
            break;
        }
    }

    while (low_P < 31744) {
        int k, exp2;
        get_midpoint(low_P, k, exp2);
        int cmp = compare_midpoint(sig, exp10, k, exp2);
        if (cmp > 0) {
            low_P++;
        } else if (cmp == 0) {
            // Tie-breaking: round to even bit pattern
            if ((low_P & 1) != 0) {
                low_P++;
            }
            break;
        } else {
            break;
        }
    }

    return sign_bit | low_P;
}

const THRESHOLDS: [bigint, bigint][] = (() => {
    const arr: [bigint, bigint][] = new Array(31744);
    for (let k = 0; k < 31744; k++) {
        const E = k >> 10;
        const F = k & 1023;
        let num: bigint;
        let shift: number;
        if (E === 0) {
            num = BigInt(2 * F + 1);
            shift = 25;
        } else {
            num = BigInt(2048 + 2 * F + 1);
            shift = 26 - E;
        }
        arr[k] = [num * (5n ** BigInt(shift)), 10n ** BigInt(shift)];
    }
    return arr;
})();

export function decimalToHalfBits(s: string): number {
    if (typeof s !== "string") {
        throw new Error("Input must be a string");
    }

    const n = s.length;
    if (n === 0) {
        throw new Error("Empty string");
    }

    let i = 0;
    let signBit = 0;
    const c0 = s.charCodeAt(0);
    if (c0 === 43) { // '+'
        i++;
    } else if (c0 === 45) { // '-'
        signBit = 0x8000;
        i++;
    }

    let intStart = i;
    while (i < n) {
        const c = s.charCodeAt(i);
        if (c >= 48 && c <= 57) i++;
        else break;
    }
    let intEnd = i;
    const hasIntDigits = intEnd > intStart;

    let fracStart = i;
    let fracEnd = i;
    let hasFracDigits = false;

    if (i < n && s.charCodeAt(i) === 46) { // '.'
        i++;
        fracStart = i;
        while (i < n) {
            const c = s.charCodeAt(i);
            if (c >= 48 && c <= 57) i++;
            else break;
        }
        fracEnd = i;
        hasFracDigits = fracEnd > fracStart;
    }

    if (!hasIntDigits && !hasFracDigits) {
        throw new Error("Invalid mantissa");
    }

    let expSign = 1;
    let expVal = 0;
    if (i < n) {
        const ce = s.charCodeAt(i);
        if (ce === 101 || ce === 69) { // 'e' or 'E'
            i++;
            if (i < n) {
                const cs = s.charCodeAt(i);
                if (cs === 43) {
                    i++;
                } else if (cs === 45) {
                    expSign = -1;
                    i++;
                }
            }
            const expStart = i;
            while (i < n) {
                const c = s.charCodeAt(i);
                if (c >= 48 && c <= 57) {
                    if (expVal < 10000000) {
                        expVal = expVal * 10 + (c - 48);
                    }
                    i++;
                } else {
                    break;
                }
            }
            if (i === expStart) {
                throw new Error("Invalid exponent");
            }
        }
    }

    if (i !== n) {
        throw new Error("Unexpected trailing characters");
    }

    // Find first significant digit and calculate base-10 exponent e10
    let firstSigIdx = -1;
    let isFirstInInt = false;

    for (let j = intStart; j < intEnd; j++) {
        if (s.charCodeAt(j) !== 48) {
            firstSigIdx = j;
            isFirstInInt = true;
            break;
        }
    }

    if (firstSigIdx === -1) {
        for (let j = fracStart; j < fracEnd; j++) {
            if (s.charCodeAt(j) !== 48) {
                firstSigIdx = j;
                isFirstInInt = false;
                break;
            }
        }
    }

    // Exact zero
    if (firstSigIdx === -1) {
        return signBit;
    }

    const rawExp = expSign * expVal;
    const e10 = isFirstInInt
        ? (intEnd - 1 - firstSigIdx) + rawExp
        : -(firstSigIdx - fracStart + 1) + rawExp;

    if (e10 >= 5) {
        return signBit | 0x7C00; // Infinity
    }
    if (e10 <= -9) {
        return signBit; // Underflow to 0
    }

    // Since -8 <= e10 <= 4, we collect up to 35 significant digits,
    // and remember if any truncated digits beyond 35 are non-zero.
    const MAX_SIG = 35;
    let sigStr = "";
    let hasMoreNonZero = false;

    if (isFirstInInt) {
        const availInt = intEnd - firstSigIdx;
        if (availInt >= MAX_SIG) {
            sigStr = s.slice(firstSigIdx, firstSigIdx + MAX_SIG);
            for (let j = firstSigIdx + MAX_SIG; j < intEnd; j++) {
                if (s.charCodeAt(j) !== 48) {
                    hasMoreNonZero = true;
                    break;
                }
            }
            if (!hasMoreNonZero) {
                for (let j = fracStart; j < fracEnd; j++) {
                    if (s.charCodeAt(j) !== 48) {
                        hasMoreNonZero = true;
                        break;
                    }
                }
            }
        } else {
            const needFrac = MAX_SIG - availInt;
            const availFrac = fracEnd - fracStart;
            if (availFrac >= needFrac) {
                sigStr = s.slice(firstSigIdx, intEnd) + s.slice(fracStart, fracStart + needFrac);
                for (let j = fracStart + needFrac; j < fracEnd; j++) {
                    if (s.charCodeAt(j) !== 48) {
                        hasMoreNonZero = true;
                        break;
                    }
                }
            } else {
                sigStr = s.slice(firstSigIdx, intEnd) + s.slice(fracStart, fracEnd);
            }
        }
    } else {
        const availFrac = fracEnd - firstSigIdx;
        if (availFrac >= MAX_SIG) {
            sigStr = s.slice(firstSigIdx, firstSigIdx + MAX_SIG);
            for (let j = firstSigIdx + MAX_SIG; j < fracEnd; j++) {
                if (s.charCodeAt(j) !== 48) {
                    hasMoreNonZero = true;
                    break;
                }
            }
        } else {
            sigStr = s.slice(firstSigIdx, fracEnd);
        }
    }

    const L = sigStr.length;
    const M = BigInt(sigStr);
    // Exact value up to sticky bit is M * 10^scale + (hasMoreNonZero ? eps : 0)
    // where 0 < eps < 10^scale
    const scale = e10 - L + 1;

    let P_scale: bigint | null = null;
    if (scale >= 0) {
        P_scale = 10n ** BigInt(scale);
    } else if (-scale > 25) {
        P_scale = 10n ** BigInt(-scale - 25);
    }

    function compareToMidpoint(k: number): number {
        const [T_num, P_shift] = THRESHOLDS[k];
        if (scale >= 0) {
            // Compare M * 10^scale * 10^shift vs T_num
            const lhs = M * P_scale! * P_shift;
            if (lhs < T_num) return -1;
            if (lhs > T_num) return 1;
            return hasMoreNonZero ? 1 : 0;
        } else {
            const negScale = -scale;
            if (negScale <= 25) {
                // Compare M * 10^(shift - negScale) vs T_num
                // THRESHOLDS[negScale - 1][1] is 10^negScale
                const P_negScale = THRESHOLDS[negScale - 1][1];
                if (P_shift >= P_negScale) {
                    const factor = P_shift / P_negScale;
                    const lhs = M * factor;
                    if (lhs < T_num) return -1;
                    if (lhs > T_num) return 1;
                    return hasMoreNonZero ? 1 : 0;
                } else {
                    const factor = P_negScale / P_shift;
                    const rhs = T_num * factor;
                    if (M < rhs) return -1;
                    if (M > rhs) return 1;
                    return hasMoreNonZero ? 1 : 0;
                }
            } else {
                // negScale > 25 >= shift. factor = 10^(negScale - shift) = 10^(negScale - 25) * 10^(25 - shift)
                const P_25 = THRESHOLDS[24][1];
                const factor = P_scale! * (P_25 / P_shift);
                const rhs = T_num * factor;
                if (M < rhs) return -1;
                if (M > rhs) return 1;
                return hasMoreNonZero ? 1 : 0;
            }
        }
    }

    let lo = 0;
    let hi = 31744;
    while (lo < hi) {
        const mid = (lo + hi) >> 1;
        const cmp = compareToMidpoint(mid);
        let roundUp: boolean;
        if (cmp > 0) {
            roundUp = true;
        } else if (cmp < 0) {
            roundUp = false;
        } else {
            // Tie: round to even pattern.
            // Candidates are mid and mid + 1. If mid is odd, mid + 1 is even -> round up.
            roundUp = (mid & 1) === 1;
        }
        if (roundUp) {
            lo = mid + 1;
        } else {
            hi = mid;
        }
    }

    return signBit | lo;
}

package main

import (
	"container/heap"
	"fmt"
	"sort"
)

type Tuple1 struct {
	F0 string
	F1 int
	F2 int
	F3 int
	F4 *int
}

type Tuple2 struct {
	F0 string
	F1 int
	F2 int
}

type Tuple3 struct {
	F0 []Tuple2
	F1 []string
}

type readyQueue []Tuple1

func (rq readyQueue) Len() int { return len(rq) }

func (rq readyQueue) Less(i, j int) bool {
	// Highest priority first
	if rq[i].F3 != rq[j].F3 {
		return rq[i].F3 > rq[j].F3
	}
	// Smaller release time next
	if rq[i].F1 != rq[j].F1 {
		return rq[i].F1 < rq[j].F1
	}
	// Smaller job_id next
	return rq[i].F0 < rq[j].F0
}

func (rq readyQueue) Swap(i, j int) {
	rq[i], rq[j] = rq[j], rq[i]
}

func (rq *readyQueue) Push(x interface{}) {
	*rq = append(*rq, x.(Tuple1))
}

func (rq *readyQueue) Pop() interface{} {
	old := *rq
	n := len(old)
	item := old[n-1]
	*rq = old[0 : n-1]
	return item
}

func Schedule(jobs []Tuple1) (Tuple3, error) {
	seen := make(map[string]struct{}, len(jobs))
	for _, job := range jobs {
		jobID := job.F0
		release := job.F1
		duration := job.F2

		if _, exists := seen[jobID]; exists {
			return Tuple3{}, fmt.Errorf("duplicate job id %q", jobID)
		}
		seen[jobID] = struct{}{}

		if release < 0 {
			return Tuple3{}, fmt.Errorf("job %q has a negative release time", jobID)
		}
		if duration < 1 {
			return Tuple3{}, fmt.Errorf("job %q has a non-positive duration", jobID)
		}
	}

	// Copy the caller's slice so we do not mutate their data
	sortedJobs := make([]Tuple1, len(jobs))
	copy(sortedJobs, jobs)

	// Sort by release time ascending
	sort.Slice(sortedJobs, func(i, j int) bool {
		return sortedJobs[i].F1 < sortedJobs[j].F1
	})

	runs := make([]Tuple2, 0)
	dropped := make([]string, 0)
	var ready readyQueue
	heap.Init(&ready)

	clock := 0
	nxt := 0
	n := len(sortedJobs)

	for nxt < n || ready.Len() > 0 {
		// Admit everything released on or before current clock
		for nxt < n && sortedJobs[nxt].F1 <= clock {
			heap.Push(&ready, sortedJobs[nxt])
			nxt++
		}

		if ready.Len() == 0 {
			// Machine idles until the earliest release among unhandled jobs
			if sortedJobs[nxt].F1 > clock {
				clock = sortedJobs[nxt].F1
			}
			for nxt < n && sortedJobs[nxt].F1 <= clock {
				heap.Push(&ready, sortedJobs[nxt])
				nxt++
			}
		}

		best := heap.Pop(&ready).(Tuple1)
		jobID := best.F0
		duration := best.F2
		deadline := best.F4

		if deadline != nil && clock+duration > *deadline {
			dropped = append(dropped, jobID)
			continue
		}

		runs = append(runs, Tuple2{
			F0: jobID,
			F1: clock,
			F2: clock + duration,
		})
		clock += duration
	}

	return Tuple3{
		F0: runs,
		F1: dropped,
	}, nil
}

import java.util.*;

public final class Solution {
    public record Tuple1(String f0, long f1, long f2, long f3, Long f4) {}

    public record Tuple2(String f0, long f1, long f2) {}

    public record Tuple3(List<Tuple2> f0, List<String> f1) {}

    public static Tuple3 schedule(List<Tuple1> jobs) {
        if (jobs == null) {
            throw new IllegalArgumentException("jobs cannot be null");
        }

        int n = jobs.size();
        Set<String> seen = new HashSet<>(n * 2);
        List<Tuple1> sortedJobs = new ArrayList<>(n);

        for (Tuple1 job : jobs) {
            if (job == null || job.f0() == null) {
                throw new IllegalArgumentException("each job must be a valid 5-tuple");
            }
            String jobId = job.f0();
            long release = job.f1();
            long duration = job.f2();

            if (!seen.add(jobId)) {
                throw new IllegalArgumentException("duplicate job id " + jobId);
            }
            if (release < 0) {
                throw new IllegalArgumentException("job " + jobId + " has a negative release time");
            }
            if (duration < 1) {
                throw new IllegalArgumentException("job " + jobId + " has a non-positive duration");
            }
            sortedJobs.add(job);
        }

        // Sort a copy of the list by release time so the caller's list is not mutated
        sortedJobs.sort(Comparator.comparingLong(Tuple1::f1));

        // Priority queue orders by: highest priority (descending), smallest release (ascending), smallest job_id (ascending)
        PriorityQueue<Tuple1> ready = new PriorityQueue<>((a, b) -> {
            int cmp = Long.compare(b.f3(), a.f3()); // priority descending
            if (cmp != 0) return cmp;
            cmp = Long.compare(a.f1(), b.f1());     // release ascending
            if (cmp != 0) return cmp;
            return a.f0().compareTo(b.f0());        // job_id ascending
        });

        List<Tuple2> runs = new ArrayList<>();
        List<String> dropped = new ArrayList<>();

        long clock = 0;
        int nxt = 0;

        while (nxt < n || !ready.isEmpty()) {
            // If no jobs are currently eligible and ready, advance the clock to the next release time
            if (ready.isEmpty() && nxt < n && sortedJobs.get(nxt).f1() > clock) {
                clock = sortedJobs.get(nxt).f1();
            }

            // Admit all jobs whose release time is <= clock
            while (nxt < n && sortedJobs.get(nxt).f1() <= clock) {
                ready.add(sortedJobs.get(nxt));
                nxt++;
            }

            Tuple1 best = ready.poll();
            String jobId = best.f0();
            long duration = best.f2();
            Long deadline = best.f4();

            if (deadline != null && clock + duration > deadline) {
                dropped.add(jobId);
            } else {
                runs.add(new Tuple2(jobId, clock, clock + duration));
                clock += duration;
            }
        }

        return new Tuple3(runs, dropped);
    }
}

