#include <unordered_set>
#include <vector>

std::tuple<std::vector<std::tuple<std::string, long long, long long>>, std::vector<std::string>> schedule(const std::vector<std::tuple<std::string, long long, long long, long long, std::optional<long long>>>& jobs) {
    struct Job {
        std::string id;
        long long release;
        long long duration;
        long long priority;
        std::optional<long long> deadline;
    };

    std::unordered_set<std::string> seen;
    seen.reserve(jobs.size());
    std::vector<Job> sorted_jobs;
    sorted_jobs.reserve(jobs.size());

    for (const auto& job_tuple : jobs) {
        const auto& [job_id, release, duration, priority, deadline] = job_tuple;
        if (!seen.insert(job_id).second) {
            throw std::invalid_argument("duplicate job id " + job_id);
        }
        if (release < 0) {
            throw std::invalid_argument("job " + job_id + " has a negative release time");
        }
        if (duration < 1) {
            throw std::invalid_argument("job " + job_id + " has a non-positive duration");
        }
        sorted_jobs.push_back({job_id, release, duration, priority, deadline});
    }

    std::sort(sorted_jobs.begin(), sorted_jobs.end(), [](const Job& a, const Job& b) {
        return a.release < b.release;
    });

    auto cmp = [](const Job* a, const Job* b) {
        // std::priority_queue puts the "largest" element at the top.
        // We return true if `a` is strictly WORSE than `b`.
        if (a->priority != b->priority) {
            return a->priority < b->priority; // Higher priority is better
        }
        if (a->release != b->release) {
            return a->release > b->release;   // Smaller release time is better
        }
        return a->id > b->id;                 // Lexicographically smaller job_id is better
    };

    std::priority_queue<const Job*, std::vector<const Job*>, decltype(cmp)> ready(cmp);

    std::vector<std::tuple<std::string, long long, long long>> runs;
    std::vector<std::string> dropped;

    long long clock = 0;
    size_t nxt = 0;
    const size_t n = sorted_jobs.size();

    while (nxt < n || !ready.empty()) {
        if (ready.empty() && clock < sorted_jobs[nxt].release) {
            clock = sorted_jobs[nxt].release;
        }
        while (nxt < n && sorted_jobs[nxt].release <= clock) {
            ready.push(&sorted_jobs[nxt]);
            ++nxt;
        }

        const Job* best = ready.top();
        ready.pop();

        if (best->deadline.has_value() && clock + best->duration > best->deadline.value()) {
            dropped.push_back(best->id);
        } else {
            runs.emplace_back(best->id, clock, clock + best->duration);
            clock += best->duration;
        }
    }

    return {runs, dropped};
}

type Job = [string, number, number, number, number | null];
type Run = [string, number, number];

function compareJobs(a: Job, b: Job): number {
    // Higher priority is more urgent (smaller in min-heap)
    if (a[3] !== b[3]) {
        return b[3] - a[3];
    }
    // Smaller release time breaks ties
    if (a[1] !== b[1]) {
        return a[1] - b[1];
    }
    // Smaller job_id breaks ties (lexicographical / code point order)
    if (a[0] < b[0]) return -1;
    if (a[0] > b[0]) return 1;
    return 0;
}

class MinHeap {
    private data: Job[] = [];

    get size(): number {
        return this.data.length;
    }

    push(job: Job): void {
        const data = this.data;
        data.push(job);
        let idx = data.length - 1;
        while (idx > 0) {
            const parentIdx = (idx - 1) >> 1;
            const parent = data[parentIdx];
            if (compareJobs(job, parent) < 0) {
                data[idx] = parent;
                idx = parentIdx;
            } else {
                break;
            }
        }
        data[idx] = job;
    }

    pop(): Job {
        const data = this.data;
        const top = data[0];
        const bottom = data.pop()!;
        const len = data.length;
        if (len > 0) {
            let idx = 0;
            const half = len >> 1;
            while (idx < half) {
                let leftIdx = (idx << 1) + 1;
                const rightIdx = leftIdx + 1;
                let bestChild = data[leftIdx];
                if (rightIdx < len && compareJobs(data[rightIdx], bestChild) < 0) {
                    leftIdx = rightIdx;
                    bestChild = data[rightIdx];
                }
                if (compareJobs(bestChild, bottom) < 0) {
                    data[idx] = bestChild;
                    idx = leftIdx;
                } else {
                    break;
                }
            }
            data[idx] = bottom;
        }
        return top;
    }
}

export function schedule(jobs: Job[]): [Run[], string[]] {
    if (!Array.isArray(jobs)) {
        throw new Error("jobs must be an array");
    }

    const seen = new Set<string>();
    for (let i = 0; i < jobs.length; i++) {
        const job = jobs[i];
        if (!Array.isArray(job) || job.length !== 5) {
            throw new Error("each job must be a 5-tuple");
        }
        const [job_id, release, duration] = job;
        if (seen.has(job_id)) {
            throw new Error(`duplicate job id ${job_id}`);
        }
        seen.add(job_id);
        if (release < 0) {
            throw new Error(`job ${job_id} has a negative release time`);
        }
        if (duration < 1) {
            throw new Error(`job ${job_id} has a non-positive duration`);
        }
    }

    // Copy to avoid mutating the caller's array
    const sortedJobs = jobs.slice();
    sortedJobs.sort((a, b) => a[1] - b[1]);

    const runs: Run[] = [];
    const dropped: string[] = [];
    const ready = new MinHeap();
    let clock = 0;
    let nxt = 0;
    const total = sortedJobs.length;

    while (nxt < total || ready.size > 0) {
        if (ready.size === 0 && clock < sortedJobs[nxt][1]) {
            clock = sortedJobs[nxt][1];
        }

        // Admit everything released at or before the current clock
        while (nxt < total && sortedJobs[nxt][1] <= clock) {
            ready.push(sortedJobs[nxt]);
            nxt++;
        }

        const best = ready.pop();
        const [job_id, , duration, , deadline] = best;

        if (deadline !== null && deadline !== undefined && clock + duration > deadline) {
            dropped.push(job_id);
            continue;
        }

        runs.push([job_id, clock, clock + duration]);
        clock += duration;
    }

    return [runs, dropped];
}

