import (
	"container/heap"
	"errors"
)

type item struct {
	val int
	idx int
}

type maxHeap []*item

func (h maxHeap) Len() int { return len(h) }
func (h maxHeap) Less(i, j int) bool {
	if h[i].val != h[j].val {
		return h[i].val > h[j].val
	}
	return h[i].idx > h[j].idx
}
func (h maxHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *maxHeap) Push(x interface{}) { *h = append(*h, x.(*item)) }
func (h *maxHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

type minHeap []*item

func (h minHeap) Len() int { return len(h) }
func (h minHeap) Less(i, j int) bool {
	if h[i].val != h[j].val {
		return h[i].val < h[j].val
	}
	return h[i].idx < h[j].idx
}
func (h minHeap) Swap(i, j int)      { h[i], h[j] = h[j], h[i] }
func (h *minHeap) Push(x interface{}) { *h = append(*h, x.(*item)) }
func (h *minHeap) Pop() interface{} {
	old := *h
	n := len(old)
	x := old[n-1]
	*h = old[0 : n-1]
	return x
}

func WindowMedians(readings []*int, k int) ([]*int, error) {
	if k < 1 {
		return nil, errors.New("k must be a positive int")
	}

	low := &maxHeap{}
	high := &minHeap{}
	heap.Init(low)
	heap.Init(high)

	delayed := make([]bool, len(readings))
	inLow := make([]bool, len(readings))
	lowSize, highSize := 0, 0

	pruneLow := func() {
		for low.Len() > 0 && delayed[(*low)[0].idx] {
			heap.Pop(low)
		}
	}

	pruneHigh := func() {
		for high.Len() > 0 && delayed[(*high)[0].idx] {
			heap.Pop(high)
		}
	}

	rebalance := func() {
		pruneLow()
		pruneHigh()
		for lowSize > highSize+1 {
			pruneLow()
			it := heap.Pop(low).(*item)
			inLow[it.idx] = false
			heap.Push(high, it)
			lowSize--
			highSize++
			pruneLow()
		}
		for lowSize < highSize {
			pruneHigh()
			it := heap.Pop(high).(*item)
			inLow[it.idx] = true
			heap.Push(low, it)
			highSize--
			lowSize++
			pruneHigh()
		}
		pruneLow()
		pruneHigh()
	}

	add := func(val, idx int) {
		pruneLow()
		it := &item{val: val, idx: idx}
		if lowSize == 0 || val <= (*low)[0].val {
			heap.Push(low, it)
			inLow[idx] = true
			lowSize++
		} else {
			heap.Push(high, it)
			inLow[idx] = false
			highSize++
		}
		rebalance()
	}

	remove := func(idx int) {
		delayed[idx] = true
		if inLow[idx] {
			lowSize--
		} else {
			highSize--
		}
		rebalance()
	}

	out := make([]*int, len(readings))
	for i, x := range readings {
		if i >= k && readings[i-k] != nil {
			remove(i - k)
		}
		if x != nil {
			add(*x, i)
		}
		if lowSize > 0 {
			pruneLow()
			v := (*low)[0].val
			out[i] = &v
		} else {
			out[i] = nil
		}
	}

	return out, nil
}

import java.util.*;

public final class Solution {

    private record Entry(long val, int index) implements Comparable<Entry> {
        @Override
        public int compareTo(Entry other) {
            int cmp = Long.compare(this.val, other.val);
            if (cmp != 0) {
                return cmp;
            }
            return Integer.compare(this.index, other.index);
        }
    }

    public static List<Long> windowMedians(List<Long> readings, long k) {
        if (k < 1) {
            throw new IllegalArgumentException("k must be a positive integer");
        }
        if (readings == null) {
            throw new IllegalArgumentException("readings cannot be null");
        }

        int n = readings.size();
        List<Long> out = new ArrayList<>(n);
        if (n == 0) {
            return out;
        }

        TreeSet<Entry> low = new TreeSet<>();
        TreeSet<Entry> high = new TreeSet<>();

        for (int i = 0; i < n; i++) {
            Long x = readings.get(i);
            if (x != null) {
                Entry e = new Entry(x, i);
                if (low.isEmpty() || e.compareTo(low.last()) <= 0) {
                    low.add(e);
                } else {
                    high.add(e);
                }
            }

            if (i >= k) {
                int oldIdx = (int) (i - k);
                Long oldVal = readings.get(oldIdx);
                if (oldVal != null) {
                    Entry oldEntry = new Entry(oldVal, oldIdx);
                    if (!low.remove(oldEntry)) {
                        high.remove(oldEntry);
                    }
                }
            }

            while (low.size() > high.size() + 1) {
                high.add(low.pollLast());
            }
            while (low.size() < high.size()) {
                low.add(high.pollFirst());
            }

            if (low.isEmpty()) {
                out.add(null);
            } else {
                out.add(low.last().val());
            }
        }

        return out;
    }
}

#include <vector>
#include <optional>
#include <set>
#include <stdexcept>
#include <iterator>

std::vector<std::optional<long long>> window_medians(const std::vector<std::optional<long long>>& readings, long long k) {
    if (k < 1) {
        throw std::invalid_argument("k must be a positive int");
    }

    std::multiset<long long> low;
    std::multiset<long long> high;

    auto rebalance = [&]() {
        while (low.size() > high.size() + 1) {
            auto it = std::prev(low.end());
            high.insert(*it);
            low.erase(it);
        }
        while (low.size() < high.size()) {
            auto it = high.begin();
            low.insert(*it);
            high.erase(it);
        }
    };

    auto add = [&](long long x) {
        if (low.empty() || x <= *low.rbegin()) {
            low.insert(x);
        } else {
            high.insert(x);
        }
        rebalance();
    };

    auto remove = [&](long long x) {
        auto it = low.find(x);
        if (it != low.end()) {
            low.erase(it);
        } else {
            auto it_high = high.find(x);
            if (it_high != high.end()) {
                high.erase(it_high);
            }
        }
        rebalance();
    };

    std::vector<std::optional<long long>> out;
    out.reserve(readings.size());

    for (size_t i = 0; i < readings.size(); ++i) {
        if (readings[i].has_value()) {
            add(*readings[i]);
        }
        if (i >= static_cast<size_t>(k) && readings[i - k].has_value()) {
            remove(*readings[i - k]);
        }
        if (!low.empty()) {
            out.push_back(*low.rbegin());
        } else {
            out.push_back(std::nullopt);
        }
    }

    return out;
}

class Heap {
    private data: number[] = [];
    private isMax: boolean;

    constructor(isMax: boolean) {
        this.isMax = isMax;
    }

    get length(): number {
        return this.data.length;
    }

    peek(): number {
        return this.data[0];
    }

    private compare(a: number, b: number): boolean {
        return this.isMax ? a > b : a < b;
    }

    push(val: number): void {
        const data = this.data;
        data.push(val);
        let i = data.length - 1;
        while (i > 0) {
            const p = (i - 1) >> 1;
            if (this.compare(data[i], data[p])) {
                const tmp = data[i];
                data[i] = data[p];
                data[p] = tmp;
                i = p;
            } else {
                break;
            }
        }
    }

    pop(): number {
        const data = this.data;
        const top = data[0];
        const last = data.pop()!;
        if (data.length > 0) {
            data[0] = last;
            let i = 0;
            const n = data.length;
            while (true) {
                let best = i;
                const l = (i << 1) + 1;
                const r = l + 1;
                if (l < n && this.compare(data[l], data[best])) {
                    best = l;
                }
                if (r < n && this.compare(data[r], data[best])) {
                    best = r;
                }
                if (best !== i) {
                    const tmp = data[i];
                    data[i] = data[best];
                    data[best] = tmp;
                    i = best;
                } else {
                    break;
                }
            }
        }
        return top;
    }
}

export function windowMedians(readings: (number | null)[], k: number): (number | null)[] {
    if (typeof k !== "number" || !Number.isInteger(k) || k < 1) {
        throw new Error("k must be a positive int");
    }

    const low = new Heap(true);   // max-heap: the smaller half, its top is the median
    const high = new Heap(false); // min-heap: the larger half
    const delayed = new Map<number, number>();
    let lowSize = 0;
    let highSize = 0;
    const out: (number | null)[] = new Array(readings.length);

    function prune(heap: Heap): void {
        while (heap.length > 0) {
            const top = heap.peek();
            const count = delayed.get(top) ?? 0;
            if (count > 0) {
                if (count === 1) {
                    delayed.delete(top);
                } else {
                    delayed.set(top, count - 1);
                }
                heap.pop();
            } else {
                break;
            }
        }
    }

    function rebalance(): void {
        if (lowSize > highSize + 1) {
            high.push(low.pop());
            lowSize -= 1;
            highSize += 1;
            prune(low);
        } else if (lowSize < highSize) {
            low.push(high.pop());
            highSize -= 1;
            lowSize += 1;
            prune(high);
        }
    }

    function add(x: number): void {
        if (lowSize === 0 || x <= low.peek()) {
            low.push(x);
            lowSize += 1;
        } else {
            high.push(x);
            highSize += 1;
        }
        rebalance();
    }

    function remove(x: number): void {
        delayed.set(x, (delayed.get(x) ?? 0) + 1);
        if (x <= low.peek()) {
            lowSize -= 1;
            if (x === low.peek()) {
                prune(low);
            }
        } else {
            highSize -= 1;
            if (high.length > 0 && x === high.peek()) {
                prune(high);
            }
        }
        rebalance();
    }

    for (let i = 0; i < readings.length; i++) {
        const x = readings[i];
        if (x !== null) {
            add(x);
        }
        if (i >= k) {
            const old = readings[i - k];
            if (old !== null) {
                remove(old);
            }
        }
        out[i] = lowSize > 0 ? low.peek() : null;
    }

    return out;
}

import heapq


def fastest_delivery(n, roads, stations, capacity, swap_time, max_swaps, s, t):
    if s == t:
        return (0, 0)

    # Build adjacency list.
    # For parallel edges with identical (u, v, energy), keep only the minimum minutes.
    best_edges = {}
    for u, v, minutes, energy in roads:
        if u == v and energy >= 0:
            continue  # Self-loops that don't regenerate battery are never useful
        key = (u, v, energy)
        if key not in best_edges or minutes < best_edges[key]:
            best_edges[key] = minutes

    adj = [[] for _ in range(n)]
    for (u, v, energy), minutes in best_edges.items():
        adj[u].append((v, minutes, energy))

    is_station = [False] * n
    for st in stations:
        if 0 <= st < n:
            is_station[st] = True

    C = capacity + 1
    S = max_swaps + 1
    INF = float("inf")

    # dist[u][swaps][charge] stores the minimum minutes to reach junction `u`
    # having used `swaps` swaps and remaining battery `charge`.
    dist = [[[INF] * C for _ in range(S)] for _ in range(n)]
    dist[s][0][capacity] = 0

    # Priority queue stores tuples of (minutes, swaps, u, charge).
    # Since minutes and swaps are the first two elements, heapq naturally orders
    # states by the lexicographically smallest (minutes, swaps) pair.
    pq = [(0, 0, s, capacity)]

    while pq:
        d, swaps, u, c = heapq.heappop(pq)

        if u == t:
            return (d, swaps)

        if d > dist[u][swaps][c]:
            continue

        # Action 1: Swap battery if at a station, under swap limit, and battery isn't full.
        if is_station[u] and swaps < max_swaps and c < capacity:
            ns = swaps + 1
            nd = d + swap_time
            u_dist = dist[u]

            # Dominance check: is there already a better or equal state at u
            # with full capacity and <= ns swaps?
            dominated = False
            for s_idx in range(ns + 1):
                if u_dist[s_idx][capacity] <= nd:
                    dominated = True
                    break

            if not dominated:
                u_dist[ns][capacity] = nd
                heapq.heappush(pq, (nd, ns, u, capacity))

        # Action 2: Drive along outgoing roads.
        for v, minutes, energy in adj[u]:
            if c >= energy:
                nc = c - energy
                if nc > capacity:
                    nc = capacity
                nd = d + minutes
                v_dist = dist[v]

                # Dominance check: is there already a state at v with <= swaps
                # and >= nc charge that achieved a time <= nd?
                dominated = False
                for s_idx in range(swaps + 1):
                    row = v_dist[s_idx]
                    for c_idx in range(nc, C):
                        if row[c_idx] <= nd:
                            dominated = True
                            break
                    if dominated:
                        break

                if not dominated:
                    v_dist[swaps][nc] = nd
                    heapq.heappush(pq, (nd, swaps, v, nc))

    return None

def min_pruning_cost(parent, demand, cap, cut_cost, critical, root_cap, penalty):
    """
    Computes the minimum pruning cost for a radial power feeder to satisfy capacity
    and criticality constraints using bottom-up tree dynamic programming.
    """
    n = len(parent)
    children = [[] for _ in range(n)]
    for v in range(1, n):
        children[parent[v]].append(v)

    # Compute post-order traversal iteratively to handle deep trees (paths of length 250)
    # without hitting recursion limits.
    order = []
    stack = [0]
    while stack:
        u = stack.pop()
        order.append(u)
        for v in children[u]:
            stack.append(v)
    order.reverse()

    # Precompute total subtree demands and whether each subtree contains a critical node.
    sub_demand = [0] * n
    has_critical = [False] * n
    for u in order:
        sd = demand[u]
        hc = bool(critical[u])
        for v in children[u]:
            sd += sub_demand[v]
            if has_critical[v]:
                hc = True
        sub_demand[u] = sd
        has_critical[u] = hc

    INF = float('inf')
    # dp[u] maps load -> minimum cost in subtree u, assuming u is retained.
    dp = [None] * n

    for u in order:
        limit = root_cap if u == 0 else cap[u]
        if demand[u] > limit:
            dp[u] = {}
            continue

        cur = {demand[u]: 0}

        for v in children[u]:
            dp_v = dp[v]
            # Cost to cut the line between u and v (only valid if subtree v has no critical nodes)
            cut_v_cost = (cut_cost[v] + penalty * sub_demand[v]) if not has_critical[v] else INF

            if not dp_v and cut_v_cost == INF:
                cur = {}
                break

            nxt = {}
            if cut_v_cost != INF:
                for l_u, c_u in cur.items():
                    nxt[l_u] = c_u + cut_v_cost

            if dp_v:
                dp_v_items = list(dp_v.items())
                for l_u, c_u in cur.items():
                    max_l_v = limit - l_u
                    for l_v, c_v in dp_v_items:
                        if l_v <= max_l_v:
                            nl = l_u + l_v
                            nc = c_u + c_v
                            if nl not in nxt or nc < nxt[nl]:
                                nxt[nl] = nc

            cur = nxt
            if not cur:
                break

        dp[u] = cur

    if not dp[0]:
        return None
    return min(dp[0].values())

import math
from collections import defaultdict


def earliest_arrival(
    connections, transfer, source, target, start_time, max_boardings
):
    if source == target:
        return start_time
    if max_boardings <= 0 or not connections:
        return None

    num_stations = len(transfer)
    INF = math.inf

    # Case 1: max_boardings is large enough that the boarding limit is never binding.
    # A simple chronological Connection Scanning Algorithm (CSA) solves this in one pass.
    if max_boardings >= len(connections):
        # Sort by departure time, then by arrival time.
        # Since dep < arr for all connections, chaining within the same trip is preserved.
        sorted_conns = sorted(connections, key=lambda c: (c[3], c[4]))

        ready = [INF] * num_stations
        ready[source] = start_time
        in_trip = set()
        best_target_arr = INF

        for trip_id, u, v, dep, arr in sorted_conns:
            if dep >= best_target_arr:
                break  # No subsequent connection can improve the target arrival time

            boarded = (trip_id in in_trip) or (ready[u] <= dep)
            if boarded:
                in_trip.add(trip_id)
                if v == target and arr < best_target_arr:
                    best_target_arr = arr
                new_ready = arr + transfer[v]
                if new_ready < ready[v]:
                    ready[v] = new_ready

        return None if best_target_arr == INF else best_target_arr

    # Case 2: Constrained boardings.
    # Use a RAPTOR-inspired round-based propagation with per-station departure pointers
    # and per-trip earliest-boarded indices to avoid redundant work.
    trips_raw = defaultdict(list)
    for c in connections:
        if c[3] >= start_time:  # Filter out connections departing before start_time
            trips_raw[c[0]].append(c)

    if not trips_raw:
        return None

    trips = []
    station_deps = [[] for _ in range(num_stations)]

    for t_idx, (_, c_list) in enumerate(trips_raw.items()):
        c_list.sort(key=lambda c: (c[3], c[4]))
        trips.append(c_list)
        for seq_idx, c in enumerate(c_list):
            station_deps[c[1]].append((c[3], t_idx, seq_idx))

    # Sort departures at each station in descending order of departure time.
    # As a station's ready time decreases across rounds, we can advance a pointer.
    for u in range(num_stations):
        station_deps[u].sort(key=lambda x: x[0], reverse=True)

    ptr = [0] * num_stations
    trip_min_seq = [len(t) for t in trips]

    ready = [INF] * num_stations
    ready[source] = start_time
    best_target_arr = INF

    improved_stations = [source]

    for _ in range(max_boardings):
        if not improved_stations:
            break

        # Find all trips that can be boarded earlier (at an earlier sequence index)
        # from the stations whose ready time improved in the previous round.
        boarded_trips = {}
        for u in improved_stations:
            r_u = ready[u]
            deps = station_deps[u]
            p = ptr[u]
            n_deps = len(deps)

            while p < n_deps and deps[p][0] >= r_u:
                _, t_idx, seq_idx = deps[p]
                if seq_idx < trip_min_seq[t_idx]:
                    if (
                        t_idx not in boarded_trips
                        or seq_idx < boarded_trips[t_idx]
                    ):
                        boarded_trips[t_idx] = seq_idx
                p += 1
            ptr[u] = p

        if not boarded_trips:
            break

        next_ready_updates = {}
        for t_idx, start_seq in boarded_trips.items():
            end_seq = trip_min_seq[t_idx]
            trip_min_seq[t_idx] = start_seq
            t_conns = trips[t_idx]

            # Scan the newly reachable segment of the trip
            for seq_idx in range(start_seq, end_seq):
                _, _, v, _, arr = t_conns[seq_idx]
                if v == target and arr < best_target_arr:
                    best_target_arr = arr

                nr = arr + transfer[v]
                if nr < ready[v]:
                    if (
                        v not in next_ready_updates
                        or nr < next_ready_updates[v]
                    ):
                        next_ready_updates[v] = nr

        # Apply updates for the next round
        improved_stations = []
        for v, nr in next_ready_updates.items():
            if nr < best_target_arr:  # Pruning: ignore updates that cannot beat best_target_arr
                ready[v] = nr
                improved_stations.append(v)

    return None if best_target_arr == INF else best_target_arr

import re

# Precompiled regular expressions for fast and exact ASCII validation
_NAME_RE = re.compile(r'^[a-z0-9_]+\Z', re.ASCII)
_PRINCIPAL_RE = re.compile(r'^(?:\*|(?:user|group):[a-z0-9_]+)\Z', re.ASCII)
_ACTION_WORD_RE = re.compile(r'^[a-z]+\Z', re.ASCII)
_ACTION_LIST_RE = re.compile(r'^(?:\*|[a-z]+(?:,[a-z]+)*)\Z', re.ASCII)
_RES_SEG_RE = re.compile(r'^(?:\*|\*\*|[a-z0-9._-]+)\Z', re.ASCII)
_PATH_SEG_RE = re.compile(r'^[a-z0-9._-]+\Z', re.ASCII)


def _match_segments(res_segs: tuple[str, ...], path_segs: tuple[str, ...]) -> bool:
    """Matches resource segments against path segments in O(N * M) time without recursion."""
    n = len(path_segs)
    if not res_segs:
        return n == 0

    # reachable is a bitmask where bit j is 1 if the resource pattern
    # processed so far can match the prefix path_segs[:j].
    reachable = 1  # Initially, 0 resource segments match 0 path segments (bit 0).
    mask_all = (1 << (n + 1)) - 1

    for r in res_segs:
        if r == '**':
            # If state j is reachable, all states >= j become reachable.
            # Over two's complement, (x | -x) sets all bits from the lowest set bit upwards.
            reachable = (reachable | -reachable) & mask_all
        elif r == '*':
            # Advances all reachable states by 1 segment.
            reachable = (reachable << 1) & mask_all
        else:
            # Advances state j to j + 1 only if path_segs[j] == r.
            next_reach = 0
            temp = reachable
            while temp:
                lowbit = temp & -temp
                j = lowbit.bit_length() - 1
                if j < n and path_segs[j] == r:
                    next_reach |= (lowbit << 1)
                temp ^= lowbit
            reachable = next_reach

        if not reachable:
            return False

    return bool(reachable & (1 << n))


def evaluate_access(rules, requests) -> list[str]:
    # 1 & 2. Top-level container validation
    if not isinstance(rules, list):
        raise TypeError("rules must be a list")
    if not isinstance(requests, list):
        raise TypeError("requests must be a list")

    # 3. Validate and parse rules
    parsed_rules = []
    for i, rule in enumerate(rules):
        if not isinstance(rule, str):
            raise TypeError(f"rule {i}: not a str")

        fields = rule.split()
        if len(fields) != 4:
            raise ValueError(f"rule {i}: expected 4 fields, got {len(fields)}")

        effect, principal, action, resource = fields

        # EFFECT
        if effect not in ("ALLOW", "DENY"):
            raise ValueError(f"rule {i}: bad effect {effect!r}")

        # PRINCIPAL
        if not _PRINCIPAL_RE.match(principal):
            raise ValueError(f"rule {i}: bad principal {principal!r}")
        if principal == "*":
            p_type, p_val, p_spec = "*", None, 0
        elif principal.startswith("user:"):
            p_type, p_val, p_spec = "user", principal[5:], 2
        else:
            p_type, p_val, p_spec = "group", principal[6:], 1

        # ACTION
        if not _ACTION_LIST_RE.match(action):
            raise ValueError(f"rule {i}: bad action {action!r}")
        if action == "*":
            a_set, a_spec = None, 0
        else:
            a_set, a_spec = frozenset(action.split(",")), 1

        # RESOURCE
        if not resource.startswith("/"):
            raise ValueError(f"rule {i}: bad resource {resource!r}")
        if resource == "/":
            res_segs = ()
        else:
            res_segs = tuple(resource[1:].split("/"))
            for seg in res_segs:
                if not _RES_SEG_RE.match(seg):
                    raise ValueError(f"rule {i}: bad resource {resource!r}")

        # Optimize consecutive '**' segments into a single '**' for matching
        opt_segs = []
        for s in res_segs:
            if s == "**" and opt_segs and opt_segs[-1] == "**":
                continue
            opt_segs.append(s)
        opt_segs = tuple(opt_segs)

        l_spec = sum(1 for seg in res_segs if seg not in ("*", "**"))

        # Ranking Key:
        # We want to maximize (L, P, A), prioritize DENY (1) over ALLOW (0),
        # and minimize rule index `i` (so we maximize `-i`).
        is_deny = 1 if effect == "DENY" else 0
        rank_key = (l_spec, p_spec, a_spec, is_deny, -i)

        has_double_star = "**" in opt_segs
        min_len = len(opt_segs) - opt_segs.count("**")

        parsed_rules.append((
            rank_key, p_type, p_val, a_set, opt_segs, has_double_star, min_len, effect, i
        ))

    # 4. Validate and parse requests
    parsed_requests = []
    for j, req in enumerate(requests):
        if not isinstance(req, tuple) or len(req) != 4:
            raise TypeError(f"request {j}: expected 4-tuple")

        user, groups, action, path = req

        if not isinstance(user, str) or not _NAME_RE.match(user):
            raise ValueError(f"request {j}: bad user {user!r}")

        if not isinstance(groups, list) or not all(isinstance(g, str) and _NAME_RE.match(g) for g in groups):
            raise ValueError(f"request {j}: bad groups")

        if not isinstance(action, str) or not _ACTION_WORD_RE.match(action):
            raise ValueError(f"request {j}: bad action {action!r}")

        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError(f"request {j}: bad path {path!r}")
        if path == "/":
            path_segs = ()
        else:
            path_segs = tuple(path[1:].split("/"))
            for seg in path_segs:
                if not _PATH_SEG_RE.match(seg):
                    raise ValueError(f"request {j}: bad path {path!r}")

        parsed_requests.append((user, frozenset(groups), action, path_segs))

    # Sort rules from highest priority to lowest priority.
    # This allows us to stop at the very first matching rule for any request.
    parsed_rules.sort(key=lambda r: r[0], reverse=True)

    # 5. Evaluate requests
    decisions = []
    for user, group_set, req_action, path_segs in parsed_requests:
        n_path = len(path_segs)
        decision = "DENY by default"

        for _, p_type, p_val, a_set, opt_segs, has_double_star, min_len, effect, orig_i in parsed_rules:
            # Fast length pre-checks before running segment matcher
            if has_double_star:
                if n_path < min_len:
                    continue
            else:
                if n_path != min_len:
                    continue

            # Principal check
            if p_type == "user":
                if p_val != user:
                    continue
            elif p_type == "group":
                if p_val not in group_set:
                    continue

            # Action check
            if a_set is not None and req_action not in a_set:
                continue

            # Resource path check
            if _match_segments(opt_segs, path_segs):
                decision = f"{effect} by rule {orig_i}"
                break

        decisions.append(decision)

    return decisions

import re

# Regex components for version numbers and clauses
_INT = r"(?:0|[1-9][0-9]*)"
_RC = r"(?:~rc([1-9][0-9]*))?"
_VER_STR = rf"({_INT})\.({_INT})\.({_INT}){_RC}"

_VER_RE = re.compile(rf"^{_VER_STR}$", re.ASCII)
_CMP_CLAUSE_RE = re.compile(rf"^(>=|<=|!=|=|>|<|){_VER_STR}$", re.ASCII)
_WILDCARD_MAJOR_RE = re.compile(rf"^({_INT})\.\*$", re.ASCII)
_WILDCARD_MINOR_RE = re.compile(rf"^({_INT})\.({_INT})\.\*$", re.ASCII)
_AT_CLAUSE_RE = re.compile(rf"^@({_INT})\.({_INT})$", re.ASCII)


def _parse_version_groups(x_str, y_str, z_str, rc_str):
    # A plain release gets (1, 0), whereas ~rcN gets (0, N).
    # This naturally orders (X, Y, Z, 0, N) < (X, Y, Z, 1, 0).
    is_plain = 1 if rc_str is None else 0
    rc_num = 0 if rc_str is None else int(rc_str)
    return (int(x_str), int(y_str), int(z_str), is_plain, rc_num)


def _parse_version(s):
    if not isinstance(s, str):
        return None
    m = _VER_RE.match(s)
    if not m:
        return None
    return _parse_version_groups(*m.groups())


def _parse_clause(c_str):
    if c_str == "*":
        return lambda v: True

    m = _CMP_CLAUSE_RE.match(c_str)
    if m:
        op, x, y, z, rc = m.groups()
        target = _parse_version_groups(x, y, z, rc)
        if op in ("", "="):
            return lambda v, t=target: v == t
        elif op == "!=":
            return lambda v, t=target: v != t
        elif op == ">":
            return lambda v, t=target: v > t
        elif op == ">=":
            return lambda v, t=target: v >= t
        elif op == "<":
            return lambda v, t=target: v < t
        elif op == "<=":
            return lambda v, t=target: v <= t

    m = _WILDCARD_MAJOR_RE.match(c_str)
    if m:
        x = int(m.group(1))
        return lambda v, x=x: v[0] == x

    m = _WILDCARD_MINOR_RE.match(c_str)
    if m:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda v, x=x, y=y: v[0] == x and v[1] == y

    m = _AT_CLAUSE_RE.match(c_str)
    if m:
        x, y = int(m.group(1)), int(m.group(2))
        return lambda v, x=x, y=y: v[0] == x and v[1] >= y

    return None


def pick_version(available, constraint) -> str | None:
    # 1. Validate `available` is a list
    if not isinstance(available, list):
        raise TypeError("available must be a list")

    # 2. Validate each element in `available` in index order
    parsed_available = []
    for i, elem in enumerate(available):
        v = _parse_version(elem)
        if v is None:
            raise ValueError(f"invalid version at index {i}: {elem!r}")
        parsed_available.append((v, elem))

    # 3. Validate `constraint` is a str
    if not isinstance(constraint, str):
        raise TypeError("constraint must be a str")

    # 4. Validate `constraint` is not empty or spaces only (" " only)
    if constraint.strip(" ") == "":
        raise ValueError("empty constraint")

    # 5. Parse and validate alternatives and clauses
    alternatives = []
    raw_alts = constraint.split("|")
    for a_idx, raw_alt in enumerate(raw_alts, start=1):
        alt = raw_alt.strip(" ")
        allow_rc = False
        if alt.startswith("?"):
            allow_rc = True
            alt = alt[1:].strip(" ")

        if alt == "":
            raise ValueError(f"alternative {a_idx} is empty")

        raw_clauses = alt.split(",")
        clauses = []
        for c_idx, raw_clause in enumerate(raw_clauses, start=1):
            clause_str = raw_clause.strip(" ")
            pred = _parse_clause(clause_str)
            if pred is None:
                raise ValueError(
                    f"alternative {a_idx}, clause {c_idx}: invalid clause {clause_str!r}"
                )
            clauses.append(pred)

        alternatives.append((allow_rc, clauses))

    # Match versions against the validated constraint
    best_version = None
    best_str = None

    for v, v_str in parsed_available:
        is_rc = v[3] == 0
        for allow_rc, clauses in alternatives:
            if is_rc and not allow_rc:
                continue
            if all(pred(v) for pred in clauses):
                if best_version is None or v > best_version:
                    best_version = v
                    best_str = v_str
                break

    return best_str

DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"


def format_base(p: int, q: int, base: int, k: int) -> str:
    # 1. Input validation
    if q == 0:
        raise ValueError("Denominator q cannot be 0.")
    if not (2 <= base <= 36):
        raise ValueError("Base must be between 2 and 36.")
    if k < 0:
        raise ValueError("Precision k must be non-negative.")

    if p == 0:
        return "0"

    # 2. Sign normalization
    neg = (p < 0) ^ (q < 0)
    p = abs(p)
    q = abs(q)

    # 3. Precompute powers of `base` for divide-and-conquer conversion
    # powers[i] = (2**i, base**(2**i))
    powers = []
    if k > 0:
        b = base
        m = 1
        while m <= k:
            powers.append((m, b))
            if m * 2 > k and (p // q) == 0:
                break
            b = b * b
            m *= 2

    # Compute base**k using the precomputed powers
    bk = 1
    rem_k = k
    for m, b in reversed(powers):
        if rem_k >= m:
            bk *= b
            rem_k -= m

    # 4. Exact round-half-to-even calculation
    num = p * bk
    N, r = divmod(num, q)
    twice_r = 2 * r
    if twice_r > q or (twice_r == q and (N & 1)):
        N += 1

    if N == 0:
        return "0"

    int_part, frac_part = divmod(N, bk)

    # Extend powers table if int_part is larger than base**k
    if int_part > 0:
        if not powers:
            powers.append((1, base))
        m, b = powers[-1]
        while b <= int_part:
            b = b * b
            m *= 2
            powers.append((m, b))

    # 5. Fast base conversion helper
    # Leaf threshold for switching from divide-and-conquer to iterative division
    LEAF = 32

    def to_base_fixed(x: int, length: int, idx: int) -> str:
        """Converts x to a base-`base` string of exact `length`, zero-padded on the left."""
        if x == 0:
            return "0" * length
        if length <= LEAF:
            chars = []
            for _ in range(length):
                x, rem = divmod(x, base)
                chars.append(DIGITS[rem])
            return "".join(reversed(chars))

        # Find the largest power of 2 strictly less than `length`
        while powers[idx][0] >= length:
            idx -= 1
        m, b = powers[idx]
        high, low = divmod(x, b)
        return to_base_fixed(high, length - m, idx - 1) + to_base_fixed(
            low, m, idx - 1
        )

    # 6. Convert integer part
    if int_part == 0:
        int_str = "0"
    else:
        # Determine exact number of digits in int_part
        temp = int_part
        int_len = 0
        for idx in range(len(powers) - 1, -1, -1):
            m, b = powers[idx]
            if temp >= b:
                temp //= b
                int_len += m
        while temp > 0:
            temp //= base
            int_len += 1

        int_str = to_base_fixed(int_part, int_len, len(powers) - 1)

    # 7. Convert fractional part and assemble final output
    sign_str = "-" if neg else ""
    if frac_part == 0:
        return f"{sign_str}{int_str}"
    else:
        frac_str = to_base_fixed(frac_part, k, len(powers) - 1).rstrip("0")
        return f"{sign_str}{int_str}.{frac_str}"

import heapq
from collections import defaultdict


def window_medians(readings, k):
    if isinstance(k, bool) or not isinstance(k, int) or k < 1:
        raise ValueError("k must be a positive int")

    low = []    # max-heap via negation: the smaller half, its top is the median
    high = []   # min-heap: the larger half
    delayed = defaultdict(int)  # value -> pending lazy deletions
    sizes = {"low": 0, "high": 0}  # live (not yet deleted) element counts
    out = []

    def prune(heap, sign):
        # drop deleted values sitting on top of a heap
        while heap and delayed[sign * heap[0]]:
            delayed[sign * heap[0]] -= 1
            heapq.heappop(heap)

    def rebalance():
        # invariant: sizes["low"] == sizes["high"] or sizes["low"] == sizes["high"] + 1
        if sizes["low"] > sizes["high"] + 1:
            heapq.heappush(high, -heapq.heappop(low))
            sizes["low"] -= 1
            sizes["high"] += 1
            prune(low, -1)
        elif sizes["low"] < sizes["high"]:
            heapq.heappush(low, -heapq.heappop(high))
            sizes["high"] -= 1
            sizes["low"] += 1
            prune(high, 1)

    def add(x):
        if sizes["low"] == 0 or x <= -low[0]:
            heapq.heappush(low, -x)
            sizes["low"] += 1
        else:
            heapq.heappush(high, x)
            sizes["high"] += 1
        rebalance()

    def remove(x):
        delayed[x] += 1
        if x <= -low[0]:
            sizes["low"] -= 1
            if x == -low[0]:
                prune(low, -1)
        else:
            sizes["high"] -= 1
            if high and x == high[0]:
                prune(high, 1)
        rebalance()

    for i, x in enumerate(readings):
        if x is not None:
            add(x)
        if i >= k and readings[i - k] is not None:
            remove(readings[i - k])
        out.append(-low[0] if sizes["low"] else None)

    return out
